const TWILIO_ACCOUNT_SID = process.env.TWILIO_ACCOUNT_SID || '';
const TWILIO_AUTH_TOKEN = process.env.TWILIO_AUTH_TOKEN || '';
const TWILIO_FROM_NUMBER = process.env.TWILIO_FROM_NUMBER || '';
const CLICKSEND_USERNAME = process.env.CLICKSEND_USERNAME || '';
const CLICKSEND_API_KEY = process.env.CLICKSEND_API_KEY || '';
const CLICKSEND_FROM = process.env.CLICKSEND_FROM || '';
const ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY || '';
// Overridable without a redeploy — set ORDER_PARSE_MODEL in Railway if this default is ever retired.
const ANTHROPIC_MODEL = process.env.ORDER_PARSE_MODEL || 'claude-sonnet-4-5-20250929';
const ANTHROPIC_API = 'https://api.anthropic.com/v1/messages';
