const SMTP_PASS = process.env.SMTP_PASS || '';
const SMTP_FROM = process.env.SMTP_FROM || SMTP_USER;

// ---------------------------------------------------------------------------
// Database (embedded schema + helpers)
// ---------------------------------------------------------------------------
const SCHEMA_SQL = "-- MaterialFlow schema\n\nCREATE TABLE IF NOT EXISTS customers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT,\n  email TEXT,\n  billing_address TEXT,\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS drivers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT,\n  truck_label TEXT,\n  pin TEXT NOT NULL,\n  active INTEGER NOT NULL DEFAULT 1,\n  -- Lets this driver submit their own repeat/add-on order requests from the\n  -- delivery board (POST /api/driver/order-requests) — off by default.\n  can_request_orders INTEGER NOT NULL DEFAULT 0,\n  -- Off excludes this driver from the automatic load-balancer\n  -- (autoAssignDelivery) — office can still assign them explicitly by name,\n  -- just never picked automatically. Seeded off for Jared Parrillo and Tom\n  -- Brown at seed time (see lib/seed.js).\n  auto_assign_eligible INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- Field crew — non-driving laborers who work job sites. A separate login\n-- (name + PIN, like drivers) and their own minimal time clock\n-- (field_shifts below); they don't drive, deliver, or touch materials, so\n-- they're kept out of the `drivers` table entirely rather than overloading\n-- it with a \"type\" flag. Not to be confused with `crews` (below) — that's\n-- office's work-crew groups for scheduling jobs, a different concept.\nCREATE TABLE IF NOT EXISTS field_workers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT,\n  pin TEXT NOT NULL,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS materials (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  unit TEXT NOT NULL DEFAULT 'yard',\n  default_price REAL NOT NULL DEFAULT 0,\n  active INTEGER NOT NULL DEFAULT 1\n);\n\nCREATE TABLE IF NOT EXISTS settings (\n  key TEXT PRIMARY KEY,\n  value TEXT\n);\n\nCREATE TABLE IF NOT EXISTS mileage_bands (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  min_miles REAL NOT NULL,\n  max_miles REAL,\n  fee REAL,\n  label TEXT,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS sms_recipients (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT NOT NULL,\n  carrier TEXT NOT NULL DEFAULT 'verizon',\n  custom_gateway_domain TEXT,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS orders (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  order_number TEXT NOT NULL UNIQUE,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  material_id INTEGER NOT NULL REFERENCES materials(id),\n  quantity REAL NOT NULL,\n  unit TEXT NOT NULL,\n  price_per_unit REAL NOT NULL DEFAULT 0,\n  delivery_address TEXT NOT NULL,\n  distance_miles REAL,\n  delivery_fee REAL NOT NULL DEFAULT 0,\n  sales_tax_rate REAL NOT NULL DEFAULT 0,\n  sales_tax_enabled INTEGER NOT NULL DEFAULT 1,\n  sales_tax_amount REAL NOT NULL DEFAULT 0,\n  total_amount REAL NOT NULL DEFAULT 0,\n  square_invoice_number TEXT,\n  square_invoiced INTEGER NOT NULL DEFAULT 0,\n  square_paid INTEGER NOT NULL DEFAULT 0,\n  requested_date TEXT,\n  requested_window TEXT,\n  notes TEXT,\n  status TEXT NOT NULL DEFAULT 'new', -- new, scheduled, out_for_delivery, delivered, refused, invoiced, cancelled\n  driver_id INTEGER REFERENCES drivers(id),\n  scheduled_date TEXT,\n  scheduled_time TEXT,\n  delivered_at TEXT,\n  driver_notes TEXT,\n  invoice_id INTEGER,\n  payment_collected INTEGER NOT NULL DEFAULT 0, -- driver collected payment (cash/check) at delivery time, ahead of formal invoicing\n  payment_collected_method TEXT,\n  payment_collected_amount REAL,\n  payment_collected_at TEXT,\n  -- job_id: this order is a material load delivered to one of OPD's own job\n  -- sites, not sold to a paying customer — see POST /api/orders, which\n  -- forces a fixed $20/yard, no tax, and a shared internal customer row\n  -- whenever it's set. requested_by_driver_id/source_order_id record a\n  -- driver-submitted repeat/add-on request (POST /api/driver/order-requests)\n  -- and which of that driver's own past orders it was based on.\n  job_id INTEGER REFERENCES jobs(id),\n  requested_by_driver_id INTEGER REFERENCES drivers(id),\n  source_order_id INTEGER REFERENCES orders(id),\n  -- Which rig is hauling this order's one truckload, when it matters: NULL\n  -- (most orders — the standard tri-axle cap applies with no special\n  -- handling), 'triaxle', or 'trailer'. Only 'trailer' actually changes\n  -- behavior — it raises the one-truckload size from MAX_YARDS_PER_DELIVERY\n  -- (20) to TRAILER_MAX_YARDS_PER_DELIVERY (30) wherever a delivery gets\n  -- split/resized (see splitIntoDeliveryChunks), so a single 30-yard trailer\n  -- load stays one truckload instead of silently being cut into 20+10. Set\n  -- from order-detail.html's Load Type toggle.\n  load_type TEXT,\n  -- For-hire trucking orders (order_type = 'trucking'): hourly billing, no\n  -- material/quantity picked up front. quantity/price_per_unit/total_amount\n  -- are still reused as hours/hourly-rate/total so invoicing needs no\n  -- changes; material_id points at an auto-created \"For-Hire Trucking\n  -- (Hourly)\" material row so every existing order/material join still\n  -- works. See POST /api/orders and PUT /api/deliveries/:id/{start,deliver}.\n  order_type TEXT NOT NULL DEFAULT 'material',\n  trucking_dropoff_address TEXT,\n  trucking_contact_name TEXT,\n  trucking_contact_phone TEXT,\n  trucking_start_time TEXT,\n  trucking_end_time TEXT,\n  -- Opts this order out of the Saturday/Sunday soft-default skip the\n  -- auto-scheduler otherwise applies on its own — Sunday is never offered\n  -- either way. See isBlockedWeekendDay/nextEligibleWeekday in server.template.js.\n  allow_saturday INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS invoices (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  invoice_number TEXT NOT NULL UNIQUE,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  status TEXT NOT NULL DEFAULT 'draft', -- draft, sent, paid, partial, void\n  subtotal REAL NOT NULL DEFAULT 0,\n  tax_rate REAL NOT NULL DEFAULT 0,\n  tax_amount REAL NOT NULL DEFAULT 0,\n  total REAL NOT NULL DEFAULT 0,\n  amount_paid REAL NOT NULL DEFAULT 0,\n  issued_date TEXT,\n  due_date TEXT,\n  paid_date TEXT,\n  notes TEXT,\n  pay_token TEXT UNIQUE,\n  stripe_checkout_url TEXT,\n  stripe_session_id TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS invoice_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  invoice_id INTEGER NOT NULL REFERENCES invoices(id),\n  order_id INTEGER REFERENCES orders(id),\n  description TEXT NOT NULL,\n  quantity REAL NOT NULL,\n  unit TEXT,\n  unit_price REAL NOT NULL,\n  amount REAL NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS payments (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  invoice_id INTEGER NOT NULL REFERENCES invoices(id),\n  amount REAL NOT NULL,\n  method TEXT NOT NULL, -- stripe, cash, check, ach, other\n  reference TEXT,\n  paid_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS deliveries (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  sequence INTEGER NOT NULL DEFAULT 1,\n  quantity REAL NOT NULL,\n  driver_id INTEGER REFERENCES drivers(id),\n  scheduled_date TEXT,\n  slot_index INTEGER,\n  status TEXT NOT NULL DEFAULT 'unscheduled', -- unscheduled, scheduled, delivered, cancelled\n  delivered_at TEXT,\n  -- This load's own share of the order's total_amount (proportional split by\n  -- quantity at generation time; office can override with an agreed flat\n  -- number, e.g. one that already folds in delivery — see PUT /api/deliveries/:id).\n  amount REAL,\n  payment_collected INTEGER NOT NULL DEFAULT 0, -- driver collected payment (cash/check) for THIS load at delivery time, ahead of formal invoicing\n  payment_collected_method TEXT,\n  payment_collected_amount REAL,\n  payment_collected_at TEXT,\n  -- For-hire trucking (order_type = 'trucking' on the parent order): exactly\n  -- one delivery row per order, no chunking. punch_in_at/punch_out_at are the\n  -- driver's actual clock times; quantity (hours) and amount are computed\n  -- from the gap between them when the driver punches out, then rolled up\n  -- into the order's own quantity/total_amount. See PUT\n  -- /api/deliveries/:id/start and /deliver.\n  punch_in_at TEXT,\n  punch_out_at TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- Driver time clock — one row per shift. At most one \"open\" row\n-- (clock_out IS NULL) per driver, enforced at the route level.\nCREATE TABLE IF NOT EXISTS driver_shifts (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  driver_id INTEGER NOT NULL REFERENCES drivers(id),\n  clock_in TEXT NOT NULL DEFAULT (datetime('now')),\n  clock_out TEXT,\n  -- Optional truck mileage log — the truck a driver picked at clock-in and\n  -- the odometer readings they entered at clock-in/out. Both the truck and\n  -- the readings are optional; a driver who skips the prompt still clocks\n  -- in/out normally.\n  asset_id INTEGER REFERENCES assets(id),\n  start_mileage REAL,\n  end_mileage REAL,\n  -- Job site + GPS location captured at clock-in and again at clock-out —\n  -- both required (see POST /api/driver/clock-in|clock-out): office wants\n  -- to know where a driver actually was for each punch, not just when.\n  -- job_site_other holds free text when the driver picked \"Other\" instead\n  -- of a job from the list.\n  clock_in_job_id INTEGER REFERENCES jobs(id),\n  clock_in_job_other TEXT,\n  clock_in_lat REAL,\n  clock_in_lng REAL,\n  clock_out_job_id INTEGER REFERENCES jobs(id),\n  clock_out_job_other TEXT,\n  clock_out_lat REAL,\n  clock_out_lng REAL,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_driver_shifts_driver ON driver_shifts(driver_id, clock_in);\n\n-- Field crew time clock — same job-site + GPS requirement as driver_shifts,\n-- no truck/mileage (field workers don't drive).\nCREATE TABLE IF NOT EXISTS field_shifts (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  field_worker_id INTEGER NOT NULL REFERENCES field_workers(id),\n  clock_in TEXT NOT NULL DEFAULT (datetime('now')),\n  clock_out TEXT,\n  clock_in_job_id INTEGER REFERENCES jobs(id),\n  clock_in_job_other TEXT,\n  clock_in_lat REAL,\n  clock_in_lng REAL,\n  clock_out_job_id INTEGER REFERENCES jobs(id),\n  clock_out_job_other TEXT,\n  clock_out_lat REAL,\n  clock_out_lng REAL,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_field_shifts_worker ON field_shifts(field_worker_id, clock_in);\n\n-- ===== Construction Jobs module =====\n\nCREATE TABLE IF NOT EXISTS crews (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS equipment (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  type TEXT,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS jobs (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_number TEXT NOT NULL UNIQUE,\n  customer_id INTEGER REFERENCES customers(id),\n  customer_name TEXT NOT NULL,\n  customer_phone TEXT,\n  site_address TEXT,\n  scope TEXT,\n  price REAL,\n  target_start_date TEXT,\n  duration_days REAL,\n  crew_id INTEGER REFERENCES crews(id),\n  status TEXT NOT NULL DEFAULT 'inquiry',\n  -- inquiry, estimate_scheduled, quote_sent, accepted, scheduled, deposit_received, in_progress, complete, cancelled\n  permit_number TEXT,\n  next_followup_date TEXT,\n  followup_note TEXT,\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS job_equipment (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  equipment_id INTEGER NOT NULL REFERENCES equipment(id),\n  start_date TEXT,\n  end_date TEXT\n);\n\nCREATE TABLE IF NOT EXISTS job_checklist_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  label TEXT NOT NULL,\n  done INTEGER NOT NULL DEFAULT 0,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS job_todos (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  description TEXT NOT NULL,\n  category TEXT NOT NULL DEFAULT 'office', -- office, field\n  done INTEGER NOT NULL DEFAULT 0,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS job_permits (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  permit_number TEXT,\n  file_name TEXT,\n  file_type TEXT,\n  file_data BLOB,\n  uploaded_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- ---- Estimates: the first half of the estimate -> accepted -> invoice flow\n-- ---- for a job. An estimate always belongs to exactly one job (so it isn't\n-- ---- its own top-level \"customer\" concept the way invoices are) — customer\n-- ---- identity is read through job_id -> jobs.customer_name/phone (and, when\n-- ---- the job is linked to a real customer record, jobs.customer_id) rather\n-- ---- than duplicated here, so a job that only has a free-text customer name\n-- ---- can still get an estimate with no extra setup.\nCREATE TABLE IF NOT EXISTS estimates (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  estimate_number TEXT NOT NULL UNIQUE,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  status TEXT NOT NULL DEFAULT 'draft', -- draft, sent, accepted, declined, converted\n  subtotal REAL NOT NULL DEFAULT 0,\n  tax_rate REAL NOT NULL DEFAULT 0,\n  tax_enabled INTEGER NOT NULL DEFAULT 1,\n  tax_amount REAL NOT NULL DEFAULT 0,\n  total REAL NOT NULL DEFAULT 0,\n  issued_date TEXT,\n  valid_until TEXT,\n  notes TEXT,\n  -- Snapshot of who this goes to, editable independent of the job/customer\n  -- record — same idea as jobs.customer_name/phone — so an estimate can\n  -- show a full \"Bill To\" block even when the job has no linked customer,\n  -- or when the estimate should go to a different address/contact than\n  -- what's on file. Pre-filled from the linked customer record when there\n  -- is one, but always editable on the estimate itself.\n  customer_email TEXT,\n  customer_address TEXT,\n  -- Lets a customer view + accept/decline this one estimate via a plain link\n  -- (see /estimate/:token, mirroring the existing /pay/:token invoice link) —\n  -- no login or full client portal needed for this first version.\n  view_token TEXT UNIQUE,\n  accepted_at TEXT,\n  declined_at TEXT,\n  -- Captured when the customer accepts via the public link: a drawn\n  -- signature (PNG data URL) plus the typed name that goes with it, so an\n  -- accepted estimate can show real proof of sign-off, not just a status\n  -- flag. Null when accepted manually by the office on the customer's\n  -- behalf (e.g. a verbal go-ahead over the phone).\n  signature_data TEXT,\n  signed_name TEXT,\n  converted_invoice_id INTEGER REFERENCES invoices(id),\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS estimate_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  estimate_id INTEGER NOT NULL REFERENCES estimates(id) ON DELETE CASCADE,\n  description TEXT NOT NULL,\n  -- Longer explanatory text shown under the item's title on the printed/\n  -- viewed estimate — e.g. \"Excavation\" as the title, with the scope\n  -- details spelled out here.\n  notes TEXT,\n  quantity REAL NOT NULL,\n  unit TEXT,\n  unit_price REAL NOT NULL,\n  amount REAL NOT NULL,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS idx_estimates_job ON estimates(job_id);\nCREATE INDEX IF NOT EXISTS idx_estimate_items_estimate ON estimate_items(estimate_id);\n\nCREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);\nCREATE INDEX IF NOT EXISTS idx_orders_driver_date ON orders(driver_id, scheduled_date);\nCREATE INDEX IF NOT EXISTS idx_invoices_customer ON invoices(customer_id);\nCREATE INDEX IF NOT EXISTS idx_deliveries_order ON deliveries(order_id);\nCREATE INDEX IF NOT EXISTS idx_deliveries_driver_date ON deliveries(driver_id, scheduled_date);\nCREATE INDEX IF NOT EXISTS idx_jobs_status ON jobs(status);\nCREATE INDEX IF NOT EXISTS idx_jobs_start_date ON jobs(target_start_date);\nCREATE INDEX IF NOT EXISTS idx_jobs_followup ON jobs(next_followup_date);\nCREATE INDEX IF NOT EXISTS idx_job_equipment_job ON job_equipment(job_id);\nCREATE INDEX IF NOT EXISTS idx_job_equipment_equip_dates ON job_equipment(equipment_id, start_date, end_date);\nCREATE INDEX IF NOT EXISTS idx_job_checklist_job ON job_checklist_items(job_id);\nCREATE INDEX IF NOT EXISTS idx_job_todos_job ON job_todos(job_id);\nCREATE INDEX IF NOT EXISTS idx_job_permits_job ON job_permits(job_id);\n\nCREATE TABLE IF NOT EXISTS users (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  username TEXT NOT NULL UNIQUE,\n  email TEXT,\n  password_hash TEXT NOT NULL,\n  password_salt TEXT NOT NULL,\n  active INTEGER NOT NULL DEFAULT 1,\n  -- 'full' sees everything; 'limited' sees only core dispatch pages plus\n  -- whichever of the flags below are turned on for that account.\n  access_level TEXT NOT NULL DEFAULT 'full',\n  can_view_financials INTEGER NOT NULL DEFAULT 0,\n  can_view_assets INTEGER NOT NULL DEFAULT 0,\n  can_view_realestate INTEGER NOT NULL DEFAULT 0,\n  can_access_admin INTEGER NOT NULL DEFAULT 0,\n  reset_token_hash TEXT,\n  reset_token_expires TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- ---- Equipment / Asset inventory (net-worth tracking; separate from the\n-- ---- scheduling-oriented `equipment` table used by the Jobs module) ----\nCREATE TABLE IF NOT EXISTS assets (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  category TEXT NOT NULL DEFAULT 'equipment', -- equipment, truck, vehicle, tool, other\n  make TEXT,\n  model TEXT,\n  year INTEGER,\n  serial_vin TEXT,\n  purchase_date TEXT,\n  purchase_price REAL,\n  condition TEXT DEFAULT 'good', -- excellent, good, fair, poor\n  location TEXT,\n  notes TEXT,\n  estimated_value REAL,\n  value_updated_at TEXT,\n  debt_balance REAL NOT NULL DEFAULT 0,\n  debt_lender TEXT,\n  debt_notes TEXT,\n  -- Live odometer reading for a truck/vehicle asset, kept in sync from the\n  -- newest driver shift's ending mileage — see POST /api/driver/clock-out.\n  current_mileage REAL,\n  mileage_updated_at TEXT,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_assets_category ON assets(category);\nCREATE INDEX IF NOT EXISTS idx_assets_active ON assets(active);\n\n-- ---- Real estate / rental portfolio (kept separate from OPD's operating\n-- ---- financials — this revenue flows to the rental holdings account) ----\nCREATE TABLE IF NOT EXISTS properties (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  address TEXT,\n  purchase_date TEXT,\n  purchase_price REAL,\n  current_value REAL,\n  value_updated_at TEXT,\n  mortgage_balance REAL NOT NULL DEFAULT 0,\n  mortgage_lender TEXT,\n  notes TEXT,\n  active INTEGER NOT NULL DEFAULT 1,\n  -- Standing monthly figures (punched in once, not re-entered every month) —\n  -- these drive the automatic monthly/annual net so a property doesn't need\n  -- every rent payment and bill logged as a transaction to see its net.\n  monthly_rent_income REAL NOT NULL DEFAULT 0,\n  monthly_mortgage_payment REAL NOT NULL DEFAULT 0,\n  monthly_property_tax REAL NOT NULL DEFAULT 0,\n  monthly_insurance REAL NOT NULL DEFAULT 0,\n  monthly_maintenance REAL NOT NULL DEFAULT 0,\n  monthly_other_expenses REAL NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS property_income (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  property_id INTEGER NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  date TEXT NOT NULL,\n  amount REAL NOT NULL,\n  source TEXT, -- e.g. rent, late fee, deposit\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS property_expenses (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  property_id INTEGER NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  date TEXT NOT NULL,\n  amount REAL NOT NULL,\n  category TEXT, -- e.g. mortgage, insurance, tax, repair, utility, management\n  payee TEXT,\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_properties_active ON properties(active);\nCREATE INDEX IF NOT EXISTS idx_property_income_property ON property_income(property_id, date);\nCREATE INDEX IF NOT EXISTS idx_property_expenses_property ON property_expenses(property_id, date);\n\n-- ---- Audit log: every login attempt (success/failure) and every mutating\n-- ---- action taken in the app. Visible only to the super admin (the shared\n-- ---- office login) via GET /api/audit-log / audit-log.html.\nCREATE TABLE IF NOT EXISTS audit_log (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  actor_role TEXT,          -- 'office', 'driver', or NULL (e.g. a failed login with no matching account)\n  actor_name TEXT,          -- display name at the time of the action\n  actor_user_id INTEGER,    -- named office user id, when applicable\n  actor_driver_id INTEGER,  -- driver id, when applicable\n  is_super_admin INTEGER NOT NULL DEFAULT 0,\n  action TEXT NOT NULL,     -- 'login_success', 'login_failed', 'logout', or 'request' for a generic action\n  method TEXT NOT NULL,\n  path TEXT NOT NULL,\n  status INTEGER,\n  detail TEXT,\n  ip TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_audit_log_created ON audit_log(created_at);\n\n-- ---- Materials Out slips: a driver's own record of what they actually\n-- ---- loaded at the shop before heading out, separate from the office's\n-- ---- scheduled orders/deliveries (a slip can optionally point back at one,\n-- ---- see delivery_id/order_id, but it's just as often an ad hoc pull with\n-- ---- no matching schedule entry). Exists purely so the office has a real\n-- ---- log of material leaving the yard to reconcile against inventory —\n-- ---- submitting one never changes any order/delivery status.\nCREATE TABLE IF NOT EXISTS material_out_slips (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  driver_id INTEGER NOT NULL REFERENCES drivers(id),\n  material_id INTEGER NOT NULL REFERENCES materials(id),\n  quantity REAL NOT NULL,\n  unit TEXT NOT NULL DEFAULT 'yard',\n  destination_address TEXT NOT NULL,\n  -- Where the material was loaded from — one of the standing supplier\n  -- names, or whatever the driver typed after picking \"Other\" (see the\n  -- MATERIAL_SOURCES list in driver.html). Free text either way, so a new\n  -- supplier never needs an admin screen first.\n  source TEXT NOT NULL DEFAULT '',\n  -- Optional photo of the paper slip the supplier handed the driver —\n  -- same convention as deliveries.photo_data (a resized/compressed JPEG\n  -- data URL, capped size, validated in POST /api/driver/material-slips).\n  photo_data TEXT,\n  -- Optional correlation back to the scheduled load this slip came from —\n  -- set when the driver taps \"Log Materials Out\" on one of their stops\n  -- rather than starting a blank slip.\n  delivery_id INTEGER REFERENCES deliveries(id),\n  order_id INTEGER REFERENCES orders(id),\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_material_out_slips_created ON material_out_slips(created_at);\nCREATE INDEX IF NOT EXISTS idx_material_out_slips_driver ON material_out_slips(driver_id, created_at);\n\n-- Removal slips: the reverse of material_out_slips — debris/spoils a driver\n-- hauls AWAY from one of OPD's own job sites (concrete, dirt, brush, etc.),\n-- rather than material loaded at the shop and delivered out to one. Exists\n-- for accountability/billing: office needs to know what left a job site and\n-- where it went, then attach a real disposal cost once they've reviewed it\n-- (dump-ticket prices vary, so the cost is entered by the office, not the\n-- driver) — see POST /api/driver/removal-slips and PUT /api/removal-slips/:id.\nCREATE TABLE IF NOT EXISTS removal_slips (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  driver_id INTEGER NOT NULL REFERENCES drivers(id),\n  job_id INTEGER NOT NULL REFERENCES jobs(id),\n  -- Free text debris/material description — one of the standing types (see\n  -- DEBRIS_TYPES in driver.html), or whatever the driver typed after\n  -- picking \"Other\". Never an admin-managed list, same philosophy as\n  -- material_out_slips.source.\n  material TEXT NOT NULL,\n  quantity REAL NOT NULL,\n  unit TEXT NOT NULL DEFAULT 'load', -- load, yard, ton\n  -- Where it went — dump, transfer station, recycler. Free text; OPD has no\n  -- standing list of these the way it does for material suppliers.\n  destination TEXT NOT NULL DEFAULT '',\n  -- Optional photo of the dump/weight ticket — same convention as\n  -- material_out_slips.photo_data.\n  photo_data TEXT,\n  notes TEXT,\n  -- Office review / billing workflow: every slip starts here so nothing a\n  -- driver logs goes unseen. The office attaches the actual disposal cost\n  -- when they mark it reviewed (see PUT /api/removal-slips/:id) — that's\n  -- also what \"clears\" it from the needs-review inbox.\n  status TEXT NOT NULL DEFAULT 'needs_review', -- needs_review, reviewed\n  cost REAL,\n  review_notes TEXT,\n  reviewed_by TEXT,\n  reviewed_at TEXT,\n  -- Set once this slip has been billed to the customer on a real invoice —\n  -- see POST /api/removal-slips/invoice (mirrors orders.invoice_id). A slip\n  -- must be 'reviewed' first and can only be billed once; this is what\n  -- flips its Review button into an \"Invoiced\" badge/link on\n  -- removal-slips.html.\n  invoice_id INTEGER REFERENCES invoices(id),\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_removal_slips_created ON removal_slips(created_at);\nCREATE INDEX IF NOT EXISTS idx_removal_slips_job ON removal_slips(job_id);\nCREATE INDEX IF NOT EXISTS idx_removal_slips_status ON removal_slips(status);\n";

// DATA_DIR points at a persistent volume mount in production (e.g. Railway) so
// the database survives redeploys. Falls back to the app directory otherwise
// (fine for local runs, but ephemeral on most hosts without a volume).
const DATA_DIR = process.env.DATA_DIR || __dirname;
const DB_PATH = path.join(DATA_DIR, 'materialflow.db');
const db = new DatabaseSync(DB_PATH);
db.exec('PRAGMA foreign_keys = ON;');
db.exec(SCHEMA_SQL);

// Lightweight migrations: CREATE TABLE IF NOT EXISTS above does nothing for a
// table that already exists, so any new column added to the schema after a
// database was first created needs an explicit ADD COLUMN here (guarded so
// it's a no-op once applied). This keeps existing data intact across deploys.
function ensureColumn(table, column, definition) {
  const cols = db.prepare(`PRAGMA table_info(${table})`).all();
  if (!cols.some((c) => c.name === column)) { db.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`); return true; }
  return false;
}

// The office's Job Tracker spreadsheet only ever carried a board_status
// (Planning Stage/In Progress/.../Job Completed) — no sales-pipeline
// status — so every job it imported was hardcoded to the pipeline default
// 'inquiry' (see /api/jobs/tracker-import below). That was invisible back
// when job-tracker.html and jobs.html (Projects) were separate pages, but
// now that they're merged into one table, a job whose board says "Job
// Completed" while its Project Status still reads "Inquiry" just looks
// wrong. These board states unambiguously mean the job is well past the
// inquiry stage, so they get a one-time correction; 'planning_stage' is
// deliberately left out below since it's also the default board state for
// a genuinely brand-new lead, and there's no reliable way to tell the two
// apart after the fact.
const BOARD_TO_JOB_STATUS = {
  job_completed: 'complete',
  in_progress: 'in_progress',
  overdue_balance: 'complete',
  awarded: 'accepted',
  for_bid: 'quote_sent',
  trash: 'cancelled',
};
// One-time (guarded by a settings flag, not just "status is still
// inquiry" — a job legitimately moved back to Inquiry later should never
// get silently re-corrected on a later server restart).
function backfillJobStatusFromBoard() {
  if (db.prepare(`SELECT value FROM settings WHERE key = 'job_status_backfilled_v1'`).get()) return;
  for (const [boardStatus, status] of Object.entries(BOARD_TO_JOB_STATUS)) {
    db.prepare(`UPDATE jobs SET status = ? WHERE status = 'inquiry' AND board_status = ?`).run(status, boardStatus);
  }
  db.prepare(`INSERT INTO settings (key, value) VALUES ('job_status_backfilled_v1', '1')`).run();
}
(function migrate() {
  // Vendor hauling — OPD's trucks hauling material for another company
  // (first one: Cullion Concrete, Rawson Materials Plant #3 -> Cranston).
  // Created here (idempotent, every boot) rather than in the embedded
  // SCHEMA_SQL string so an existing production database picks them up.
  db.exec(`
    CREATE TABLE IF NOT EXISTS haul_vendors (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      color TEXT NOT NULL DEFAULT '#ea580c',
      pickup_name TEXT,
      pickup_address TEXT,
      dropoff_address TEXT,
      material_name TEXT,
      rate_per_ton REAL,
      active INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE TABLE IF NOT EXISTS haul_assignments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      vendor_id INTEGER NOT NULL REFERENCES haul_vendors(id),
      driver_id INTEGER NOT NULL REFERENCES drivers(id),
      date TEXT NOT NULL,
      created_by TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      UNIQUE (vendor_id, driver_id, date)
    );
    CREATE TABLE IF NOT EXISTS haul_loads (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      assignment_id INTEGER NOT NULL REFERENCES haul_assignments(id),
      vendor_id INTEGER NOT NULL REFERENCES haul_vendors(id),
      driver_id INTEGER NOT NULL REFERENCES drivers(id),
      date TEXT NOT NULL,
      time_out TEXT,
      time_in TEXT,
      tons REAL,
      ticket_number TEXT,
      photo_data TEXT,
      notes TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT
    );
  `);
  // How each hauling vendor is billed: 'ton' (tons x rate_per_ton) or 'hour'
  // (hours x rate_per_hour). Both rates are kept so flipping the toggle never
  // loses the other number.
  ensureColumn('haul_vendors', 'billing_basis', "TEXT NOT NULL DEFAULT 'ton'");
  ensureColumn('haul_vendors', 'rate_per_hour', 'REAL');
  // Tolls on hourly vendors: the vendor stores the $ per toll crossing and
  // whether tolls are billed at all; each time entry then carries how many
  // trips went through the toll and an "each way" switch (x2 when on).
  ensureColumn('haul_vendors', 'tolls_enabled', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('haul_vendors', 'toll_amount', 'REAL');
  ensureColumn('haul_loads', 'toll_trips', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('haul_loads', 'toll_each_way', 'INTEGER NOT NULL DEFAULT 0');
  // Archived entries stay on file but drop out of the driver's block, the
  // billing report and the "ready to bill" prompt. statement_id marks an
  // entry as billed on a vendor statement.
  // Vendor Orders: an assignment doubles as the order — start time and
  // instructions the office sets, and ack_at = when the driver tapped "Got it"
  // on the popup they get when they open the app that day.
  ensureColumn('haul_assignments', 'start_time', 'TEXT');
  ensureColumn('haul_assignments', 'notes', 'TEXT');
  ensureColumn('haul_assignments', 'ack_at', 'TEXT');
  ensureColumn('haul_loads', 'archived_at', 'TEXT');
  ensureColumn('haul_loads', 'statement_id', 'INTEGER');
  db.exec(`
    CREATE TABLE IF NOT EXISTS driver_time_off (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      driver_id INTEGER NOT NULL REFERENCES drivers(id),
      start_date TEXT NOT NULL,
      end_date TEXT NOT NULL,
      reason TEXT,
      created_by TEXT NOT NULL DEFAULT 'Driver',
      seen_at TEXT,
      seen_by TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE INDEX IF NOT EXISTS idx_time_off_dates ON driver_time_off(start_date, end_date);
  `);
  db.exec(`
    CREATE TABLE IF NOT EXISTS haul_day_closeouts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      vendor_id INTEGER NOT NULL REFERENCES haul_vendors(id),
      date TEXT NOT NULL,
      printed_at TEXT,
      printed_by TEXT,
      billed_at TEXT,
      billed_by TEXT,
      UNIQUE (vendor_id, date)
    );
  `);
  db.exec(`
    CREATE TABLE IF NOT EXISTS haul_statements (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      statement_number TEXT NOT NULL UNIQUE,
      vendor_id INTEGER NOT NULL REFERENCES haul_vendors(id),
      period_from TEXT,
      period_to TEXT,
      billing_basis TEXT NOT NULL DEFAULT 'ton',
      rate REAL,
      toll_amount REAL,
      entries INTEGER NOT NULL DEFAULT 0,
      hours REAL NOT NULL DEFAULT 0,
      tons REAL NOT NULL DEFAULT 0,
      subtotal REAL NOT NULL DEFAULT 0,
      tolls_total REAL NOT NULL DEFAULT 0,
      total REAL NOT NULL DEFAULT 0,
      status TEXT NOT NULL DEFAULT 'open',
      paid_at TEXT,
      payment_reference TEXT,
      notes TEXT,
      created_by TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
  `);
  // Statements can be part-paid; imported ones come from an outside invoicing
  // system (external_ref = that system's invoice #, title = its description).
  ensureColumn('haul_statements', 'amount_paid', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('haul_statements', 'due_date', 'TEXT');
  ensureColumn('haul_statements', 'title', 'TEXT');
  ensureColumn('haul_statements', 'imported', 'INTEGER NOT NULL DEFAULT 0');
  db.exec(`UPDATE haul_statements SET amount_paid = total WHERE status = 'paid' AND amount_paid = 0 AND imported = 0`);
  ensureColumn('orders', 'distance_miles', 'REAL');
  // Pre-trip inspection: one row per clock-in, answered right as the driver
  // punches in (never at any other time of day). completed = they checked the
  // box that they walked the truck; has_issue/issue_notes = something they
  // reported wrong, which the office sees until it's marked resolved.
  db.exec(`
    CREATE TABLE IF NOT EXISTS pretrip_inspections (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      driver_id INTEGER NOT NULL REFERENCES drivers(id),
      shift_id INTEGER,
      asset_id INTEGER,
      date TEXT NOT NULL,
      completed INTEGER NOT NULL DEFAULT 0,
      has_issue INTEGER NOT NULL DEFAULT 0,
      issue_notes TEXT,
      resolved_at TEXT,
      resolved_by TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE INDEX IF NOT EXISTS idx_pretrip_date ON pretrip_inspections(date);
  `);
  ensureColumn('pretrip_inspections', 'acknowledged_at', 'TEXT');
  ensureColumn('pretrip_inspections', 'acknowledged_by', 'TEXT');
  // A driver-entered order at $0 stays flagged "needs a price" until the
  // office prices it, or a super user approves it as no-charge with the
  // override PIN (these record who/when).
  ensureColumn('orders', 'zero_price_approved_at', 'TEXT');
  ensureColumn('orders', 'zero_price_approved_by', 'TEXT');
  ensureColumn('orders', 'delivery_fee', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('orders', 'square_invoice_number', 'TEXT');
  ensureColumn('orders', 'square_invoiced', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('orders', 'square_paid', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('sms_recipients', 'carrier', "TEXT NOT NULL DEFAULT 'verizon'");
  ensureColumn('sms_recipients', 'custom_gateway_domain', 'TEXT');
  ensureColumn('orders', 'sales_tax_rate', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('orders', 'sales_tax_amount', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('orders', 'total_amount', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('users', 'access_level', "TEXT NOT NULL DEFAULT 'full'");
  ensureColumn('users', 'can_view_financials', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('users', 'can_view_assets', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('users', 'can_view_realestate', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('users', 'can_access_admin', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('orders', 'payment_collected', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('orders', 'payment_collected_method', 'TEXT');
  ensureColumn('orders', 'payment_collected_amount', 'REAL');
  ensureColumn('orders', 'payment_collected_at', 'TEXT');
  ensureColumn('users', 'email', 'TEXT');
  ensureColumn('users', 'reset_token_hash', 'TEXT');
  ensureColumn('users', 'reset_token_expires', 'TEXT');
  // Per-load amount + payment tracking (a multi-load order used to show the
  // FULL order total/payment status on every one of its loads, because those
  // lived only on `orders`). See backfillDeliveryAmounts/backfillDeliveryPayments.
  ensureColumn('deliveries', 'amount', 'REAL');
  ensureColumn('deliveries', 'payment_collected', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('deliveries', 'payment_collected_method', 'TEXT');
  ensureColumn('deliveries', 'payment_collected_amount', 'REAL');
  ensureColumn('deliveries', 'payment_collected_at', 'TEXT');
  // Who actually collected the cash/check — separate from driver_id (who
  // ran the load). A driver can legitimately collect payment on a stop a
  // different driver delivered (e.g. running behind them on the same
  // route); this lets that show up correctly on both drivers' reports
  // instead of silently reassigning the delivery to whoever marked it paid.
  ensureColumn('deliveries', 'payment_collected_by', 'INTEGER REFERENCES drivers(id)');
  // For-hire trucking orders — hourly billing, no material/quantity picked up
  // front. order_type distinguishes them from ordinary material orders;
  // quantity/price_per_unit/total_amount are still reused as hours/rate/total
  // so invoicing needs no changes at all. punch_in_at/punch_out_at capture
  // exactly when the driver started and finished so hours are computed from
  // real clock times, not a guess.
  ensureColumn('orders', 'order_type', "TEXT NOT NULL DEFAULT 'material'");
  ensureColumn('orders', 'trucking_dropoff_address', 'TEXT');
  ensureColumn('orders', 'trucking_contact_name', 'TEXT');
  ensureColumn('orders', 'trucking_contact_phone', 'TEXT');
  ensureColumn('orders', 'trucking_start_time', 'TEXT');
  ensureColumn('orders', 'trucking_end_time', 'TEXT');
  ensureColumn('deliveries', 'punch_in_at', 'TEXT');
  ensureColumn('deliveries', 'punch_out_at', 'TEXT');
  // Standing monthly rent/expense figures for the automatic net gain/loss —
  // see computePropertyCashFlow in this file's route section.
  ensureColumn('properties', 'monthly_rent_income', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_mortgage_payment', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_property_tax', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_insurance', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_maintenance', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_other_expenses', 'REAL NOT NULL DEFAULT 0');
  // Lets office toggle sales tax off (or back on) per order — independent of
  // sales_tax_rate, so turning it off doesn't lose the rate to re-apply later.
  ensureColumn('orders', 'sales_tax_enabled', 'INTEGER NOT NULL DEFAULT 1');
  // Links an invoice back to the job (and, when it came from an accepted
  // estimate, the estimate) it was billed from.
  ensureColumn('invoices', 'job_id', 'INTEGER REFERENCES jobs(id)');
  ensureColumn('invoices', 'estimate_id', 'INTEGER REFERENCES estimates(id)');
  ensureColumn('estimates', 'customer_email', 'TEXT');
  ensureColumn('estimates', 'customer_address', 'TEXT');
  ensureColumn('estimates', 'signature_data', 'TEXT');
  ensureColumn('estimates', 'signed_name', 'TEXT');
  ensureColumn('estimate_items', 'notes', 'TEXT');
  ensureColumn('drivers', 'can_request_orders', 'INTEGER NOT NULL DEFAULT 0');
  const addedAutoAssignEligible = ensureColumn('drivers', 'auto_assign_eligible', 'INTEGER NOT NULL DEFAULT 1');
  if (addedAutoAssignEligible) {
    db.exec(`UPDATE drivers SET auto_assign_eligible = 0 WHERE name IN ('Jared Parrillo', 'Tom Brown')`);
  }
  // "Lead driver" — a driver who can see AND change every other driver's work
  // (reassign deliveries and vendor orders, fix shifts/loads, time off, slips,
  // pre-trips) from the Override tab on the driver side. Everyone else can see
  // the team's schedule read-only. Al Loiselle is the first lead; the office
  // can change who it is on the Settings page.
  const addedIsLead = ensureColumn('drivers', 'is_lead', 'INTEGER NOT NULL DEFAULT 0');
  if (addedIsLead) {
    db.exec(`UPDATE drivers SET is_lead = 1 WHERE lower(name) LIKE 'al loiselle%'`);
  }
  ensureColumn('orders', 'job_id', 'INTEGER REFERENCES jobs(id)');
  ensureColumn('orders', 'requested_by_driver_id', 'INTEGER REFERENCES drivers(id)');
  ensureColumn('orders', 'source_order_id', 'INTEGER REFERENCES orders(id)');
  // A customer's own read-only self-serve link — order history and invoices,
  // pay links reuse the existing /pay/:token flow. Generated lazily the
  // first time office shares it (getOrCreatePortalToken), not up front for
  // every customer, so this stays NULL for most rows until then.
  ensureColumn('customers', 'portal_token', 'TEXT');
  // How the customer's paying for this particular order — office picks one
  // (Cash on Delivery / Invoice / On Account) at creation or any time after.
  // Free text, not an enum, so a one-off arrangement can still be typed in;
  // the order-slip text generator (buildOrderSlipText, orders-database.html)
  // falls back to "Cash on Delivery" when this is blank on an older order.
  ensureColumn('orders', 'payment_terms', 'TEXT');
  // Opts this specific order out of the Saturday/Sunday soft-default skip
  // (see isBlockedWeekendDay/nextEligibleWeekday near addDays) — Sunday is
  // never offered either way. New Order's "Allow scheduling on Saturday"
  // checkbox, editable after the fact too (PUT /api/orders/:id).
  ensureColumn('orders', 'allow_saturday', 'INTEGER NOT NULL DEFAULT 0');
  // Job Tracker fields — deliberately separate from the existing sales-
  // pipeline `status` column (inquiry/quote_sent/.../complete, still used by
  // the Projects Pipeline widget and crew/equipment scheduling): board_status
  // is the office's day-to-day "what board column is this job in right now"
  // state (planning_stage/in_progress/overdue_balance/awarded/for_bid/
  // job_completed/trash), tracked alongside billed/paid and a free-form
  // job_type — matching the office's own spreadsheet-style Job Tracker
  // (job-tracker.html) and TV job board (job-board.html) one for one.
  ensureColumn('jobs', 'job_type', 'TEXT');
  ensureColumn('jobs', 'board_status', "TEXT NOT NULL DEFAULT 'planning_stage'");
  ensureColumn('jobs', 'billed', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('jobs', 'paid', 'INTEGER NOT NULL DEFAULT 0');
  // "Sort My Stops" — cached geocode coordinates for a delivery's destination
  // so a driver can re-sort their day without re-geocoding every address
  // (and hammering Nominatim's rate limit) each time. Populated lazily by
  // /api/driver/sort-stops the first time a stop is sorted; never required.
  ensureColumn('deliveries', 'dest_lat', 'REAL');
  ensureColumn('deliveries', 'dest_lng', 'REAL');
  // Optional proof-of-delivery photo (base64 data URL, resized/compressed
  // client-side before upload) — for when nobody's on site to sign for a
  // load. Never required to complete a delivery; see POST
  // /api/deliveries/:id/deliver.
  ensureColumn('deliveries', 'photo_data', 'TEXT');
  // Materials Out slips: where the load came from (a standing supplier name
  // or free text after picking "Other") and an optional photo of the paper
  // slip the supplier handed the driver. Added after the table's first
  // release, so existing installs need the columns backfilled in place.
  ensureColumn('material_out_slips', 'source', "TEXT NOT NULL DEFAULT ''");
  ensureColumn('material_out_slips', 'photo_data', 'TEXT');
  // The supplier's scale ticket number (e.g. Rawson's 30030190), so a slip
  // can be matched back to the paper ticket / the supplier's own invoice.
  ensureColumn('material_out_slips', 'ticket_number', 'TEXT');
  // Set when the office moves a Materials Out slip into Vendor Hauling (see
  // POST /api/material-slips/move-to-hauling) — points at the haul load it
  // became, so it's no longer counted as plain material going out.
  ensureColumn('material_out_slips', 'moved_haul_load_id', 'INTEGER');
  // Truck mileage log — captured at clock-in/out (see POST
  // /api/driver/clock-in and /clock-out). The truck and both mileage
  // readings are optional, so a driver who skips the prompt still clocks
  // in/out normally.
  ensureColumn('driver_shifts', 'asset_id', 'INTEGER REFERENCES assets(id)');
  ensureColumn('driver_shifts', 'start_mileage', 'REAL');
  ensureColumn('driver_shifts', 'end_mileage', 'REAL');
  // Job site + GPS location, required at clock-in and clock-out — see
  // resolveClockJobSite/resolveClockLocation and the field_workers/
  // field_shifts tables (a separate non-driving "field crew" role that
  // shares this same requirement).
  ensureColumn('driver_shifts', 'clock_in_job_id', 'INTEGER REFERENCES jobs(id)');
  ensureColumn('driver_shifts', 'clock_in_job_other', 'TEXT');
  ensureColumn('driver_shifts', 'clock_in_lat', 'REAL');
  ensureColumn('driver_shifts', 'clock_in_lng', 'REAL');
  ensureColumn('driver_shifts', 'clock_out_job_id', 'INTEGER REFERENCES jobs(id)');
  ensureColumn('driver_shifts', 'clock_out_job_other', 'TEXT');
  ensureColumn('driver_shifts', 'clock_out_lat', 'REAL');
  ensureColumn('driver_shifts', 'clock_out_lng', 'REAL');
  // Live odometer reading for a truck/vehicle asset, kept in sync from the
  // newest shift's ending mileage — office can also correct it directly on
  // the asset's own page (asset-detail.html).
  ensureColumn('assets', 'current_mileage', 'REAL');
  ensureColumn('assets', 'mileage_updated_at', 'TEXT');
  // Load Type toggle (order-detail.html) — see the column's own comment in
  // db/schema.sql for what 'trailer' actually changes.
  ensureColumn('orders', 'load_type', 'TEXT');
  // Pricing model for a material order — 'per_unit' (default, today's
  // quantity x price_per_unit), 'per_load' (reuses quantity/price_per_unit
  // but quantity means "number of loads" instead of yards, kept in sync
  // with the order's actual non-cancelled deliveries by recomputeOrderRollup
  // so the bill always matches real trips made), or 'lump_sum' (one flat
  // total in lump_sum_amount, ignoring quantity/price_per_unit entirely).
  ensureColumn('orders', 'pricing_mode', "TEXT NOT NULL DEFAULT 'per_unit'");
  ensureColumn('orders', 'lump_sum_amount', 'REAL');
  // Removal-slip billing (POST /api/removal-slips/invoice) — see the
  // column's own comment in db/schema.sql.
  ensureColumn('removal_slips', 'invoice_id', 'INTEGER REFERENCES invoices(id)');
  backfillDeliveries();
  backfillDeliveryAmounts();
  backfillDeliveryPayments();
  backfillJobStatusFromBoard();
  extendMileageBandsPast20Miles();
})();

// One-time: the office's original mileage bands topped out at 15–20mi
// ($150), then a flat "20+ miles — call for quote" band with no fee —
// meaning Quote/New Order could never offer a number for anything past 20
// miles, only a manual callback. The office asked to keep going with the
// same +$25-per-5-miles pattern their existing bands already follow, out to
// 50 miles, with the manual-quote catch-all pushed out to start there
// instead. Guarded by a settings flag (not "is there already a 20-25mi
// band", since re-adding a band the office later deleted on purpose would
// be just as wrong as skipping this once); only touches the specific
// default 20+/no-fee row it's looking for, so a catch-all the office has
// already customized by the time this runs is left alone.
function extendMileageBandsPast20Miles() {
  if (db.prepare(`SELECT value FROM settings WHERE key = 'mileage_bands_extended_v1'`).get()) return;
  const oldCatchAll = db.prepare(
    `SELECT * FROM mileage_bands WHERE min_miles = 20 AND max_miles IS NULL AND fee IS NULL`
  ).get();
  if (oldCatchAll) {
    db.prepare(`UPDATE mileage_bands SET min_miles = 50, label = '50+ miles — call for quote', sort_order = 10 WHERE id = ?`)
      .run(oldCatchAll.id);
    const newBands = [
      [20, 25, 175, '20–25 miles', 4], [25, 30, 200, '25–30 miles', 5], [30, 35, 225, '30–35 miles', 6],
      [35, 40, 250, '35–40 miles', 7], [40, 45, 275, '40–45 miles', 8], [45, 50, 300, '45–50 miles', 9],
    ];
    for (const [minMiles, maxMiles, fee, label, sortOrder] of newBands) {
      db.prepare(`INSERT INTO mileage_bands (min_miles, max_miles, fee, label, sort_order) VALUES (?, ?, ?, ?, ?)`)
        .run(minMiles, maxMiles, fee, label, sortOrder);
    }
  }
  db.prepare(`INSERT INTO settings (key, value) VALUES ('mileage_bands_extended_v1', '1')`).run();
}

// Orders created before the `deliveries` table existed have no rows there.
// The schedule board and driver app both read from `deliveries`, so give
// every such order exactly one delivery mirroring its own driver/date/status
// — never re-split a legacy order, that would rewrite real delivery history.
function backfillDeliveries() {
  const orphans = db.prepare(`
    SELECT o.id, o.quantity, o.status, o.driver_id, o.scheduled_date, o.delivered_at
    FROM orders o LEFT JOIN deliveries d ON d.order_id = o.id
    WHERE d.id IS NULL
  `).all();
  if (!orphans.length) return;
  for (const o of orphans) {
    let status = 'unscheduled';
    let driverId = null, scheduledDate = null, slotIndex = null, deliveredAt = null;
    if (o.status === 'cancelled') {
      status = 'cancelled';
    } else if (o.status === 'delivered' || o.status === 'invoiced') {
      status = 'delivered'; driverId = o.driver_id; scheduledDate = o.scheduled_date; deliveredAt = o.delivered_at;
    } else if (o.status === 'out_for_delivery') {
      status = 'out_for_delivery'; driverId = o.driver_id; scheduledDate = o.scheduled_date; slotIndex = 0;
    } else if (o.driver_id && o.scheduled_date) {
      status = 'scheduled'; driverId = o.driver_id; scheduledDate = o.scheduled_date; slotIndex = 0;
    }
    db.prepare(
      `INSERT INTO deliveries (order_id, sequence, quantity, driver_id, scheduled_date, slot_index, status, delivered_at) VALUES (?, 1, ?, ?, ?, ?, ?, ?)`
    ).run(o.id, o.quantity, driverId, scheduledDate, slotIndex, status, deliveredAt);
  }
}

// One-time: give every existing delivery row a dollar `amount` (its
// proportional share of its order's total_amount, split by quantity, with
// the last load absorbing the rounding remainder so the loads sum exactly
// to the order total). Only fills rows where amount is still NULL, so it
// never overwrites a manual override made after this has already run once.
function backfillDeliveryAmounts() {
  const orders = db.prepare(`
    SELECT DISTINCT o.id, o.total_amount
    FROM orders o
    JOIN deliveries d ON d.order_id = o.id AND d.amount IS NULL
  `).all();
  for (const o of orders) {
    const loads = db.prepare(
      `SELECT id, quantity FROM deliveries WHERE order_id = ? AND status != 'cancelled' ORDER BY sequence`
    ).all(o.id);
    if (!loads.length) continue;
    const totalQty = loads.reduce((s, l) => s + l.quantity, 0) || 1;
    let assigned = 0;
    loads.forEach((l, i) => {
      let amt;
      if (i === loads.length - 1) {
        amt = Math.round((o.total_amount - assigned) * 100) / 100;
      } else {
        amt = Math.round((o.total_amount * (l.quantity / totalQty)) * 100) / 100;
        assigned += amt;
      }
      db.prepare(`UPDATE deliveries SET amount = ? WHERE id = ?`).run(amt, l.id);
    });
    const cancelled = db.prepare(
      `SELECT id, quantity FROM deliveries WHERE order_id = ? AND status = 'cancelled' AND amount IS NULL`
    ).all(o.id);
    for (const l of cancelled) {
      const amt = Math.round((o.total_amount * (l.quantity / totalQty)) * 100) / 100;
      db.prepare(`UPDATE deliveries SET amount = ? WHERE id = ?`).run(amt, l.id);
    }
  }
}

// One-time: move each order's COD payment-collected record (recorded before
// per-delivery tracking existed) onto that order's first non-cancelled
// delivery, so already-collected payments aren't silently lost. Guarded to
// only copy when the target delivery doesn't already show payment_collected.
function backfillDeliveryPayments() {
  const paidOrders = db.prepare(`
    SELECT id, payment_collected_method, payment_collected_amount, payment_collected_at
    FROM orders WHERE payment_collected = 1
  `).all();
  for (const o of paidOrders) {
    const target = db.prepare(
      `SELECT id, payment_collected FROM deliveries WHERE order_id = ? AND status != 'cancelled' ORDER BY sequence LIMIT 1`
    ).get(o.id);
    if (!target || target.payment_collected) continue;
    db.prepare(
      `UPDATE deliveries SET payment_collected = 1, payment_collected_method = ?, payment_collected_amount = ?, payment_collected_at = ? WHERE id = ?`
    ).run(o.payment_collected_method, o.payment_collected_amount, o.payment_collected_at, target.id);
  }
}

function run(sql, params = []) { return db.prepare(sql).run(...params); }
function get(sql, params = []) { return db.prepare(sql).get(...params); }
function all(sql, params = []) { return db.prepare(sql).all(...params); }

function getSetting(key, fallback = null) {
  const row = get('SELECT value FROM settings WHERE key = ?', [key]);
  return row && row.value !== '' && row.value !== null ? row.value : fallback;
}
function setSetting(key, value) {
  const existing = get('SELECT key FROM settings WHERE key = ?', [key]);
  if (existing) run('UPDATE settings SET value = ? WHERE key = ?', [value, key]);
  else run('INSERT INTO settings (key, value) VALUES (?, ?)', [key, value]);
}

