// ---------------------------------------------------------------------------
// Delivery distance estimator (Nominatim geocoding + OSRM driving distance,
// both free/no-key public services; falls back to a padded straight-line
// estimate if the routing service is unreachable)
// ---------------------------------------------------------------------------
async function geocodeAddress(address) {
  const geoUrl = `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(address)}`;
  const res = await fetch(geoUrl, { headers: { 'User-Agent': 'OPD-Raw-Materials-Dispatch/1.0 (internal delivery estimator)' } });
  if (!res.ok) throw new Error('Geocoding service unavailable right now.');
  const data = await res.json();
  if (!data || !data.length) throw new Error(`Could not locate "${address}". Check the address and try again.`);
  return { lat: Number(data[0].lat), lng: Number(data[0].lon) };
}
function haversineMiles(a, b) {
  const R = 3958.8;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat), dLng = toRad(b.lng - a.lng);
  const lat1 = toRad(a.lat), lat2 = toRad(b.lat);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.asin(Math.sqrt(h));
}
async function drivingMiles(origin, dest) {
  try {
    const routeUrl = `https://router.project-osrm.org/route/v1/driving/${origin.lng},${origin.lat};${dest.lng},${dest.lat}?overview=false`;
    const res = await fetch(routeUrl);
    if (res.ok) {
      const data = await res.json();
      if (data && data.routes && data.routes[0]) return { miles: data.routes[0].distance / 1609.34, method: 'driving' };
    }
  } catch (e) { /* fall through to straight-line */ }
  return { miles: haversineMiles(origin, dest) * 1.3, method: 'estimated' };
}
function sleep(ms) { return new Promise((resolve) => setTimeout(resolve, ms)); }

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------
// The business runs on US Eastern time (America/New_York — tracks EST/EDT
// automatically). The server process itself runs in UTC, and SQLite's own
// datetime('now') is always UTC too, so "today"/"now" for business logic
// has to explicitly convert — otherwise "today" flips over a few hours too
// early (as early as 8pm Eastern).
const BUSINESS_TZ = 'America/New_York';
function todayStr() {
  return new Intl.DateTimeFormat('en-CA', { timeZone: BUSINESS_TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
}
function parseUtcSqlDate(input) {
  if (!input) return null;
  if (input instanceof Date) return input;
  const d = new Date(String(input).replace(' ', 'T') + 'Z');
  return isNaN(d.getTime()) ? null : d;
}
function formatEasternDate(input) {
  const d = parseUtcSqlDate(input);
  if (!d) return '';
  return new Intl.DateTimeFormat('en-US', { timeZone: BUSINESS_TZ, month: 'short', day: 'numeric', year: 'numeric' }).format(d);
}
function formatEasternTime(input) {
  const d = parseUtcSqlDate(input);
  if (!d) return '';
  return new Intl.DateTimeFormat('en-US', { timeZone: BUSINESS_TZ, hour: 'numeric', minute: '2-digit' }).format(d);
}
function formatEasternDateTime(input) {
  const d = parseUtcSqlDate(input);
  if (!d) return '';
  return `${formatEasternDate(d)}, ${formatEasternTime(d)} ET`;
}
function formatEasternDateShort(input) {
  const d = parseUtcSqlDate(input);
  if (!d) return '';
  return new Intl.DateTimeFormat('en-US', { timeZone: BUSINESS_TZ, month: 'numeric', day: 'numeric', year: '2-digit' }).format(d);
}
// The Eastern calendar date (YYYY-MM-DD) a UTC timestamp string falls on —
// e.g. for grouping a delivery into "today" the same way todayStr() defines
// today, instead of SQLite's date() which would use the raw (UTC) date and
// flip a late-evening load into "tomorrow".
function easternDateStr(input) {
  const d = parseUtcSqlDate(input);
  if (!d) return null;
  return new Intl.DateTimeFormat('en-CA', { timeZone: BUSINESS_TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
}
function formatDateOnlyShort(dateStr) {
  if (!dateStr) return '';
  const d = new Date(`${dateStr}T00:00:00`);
  if (isNaN(d.getTime())) return dateStr;
  return `${d.getMonth() + 1}/${d.getDate()}/${String(d.getFullYear()).slice(2)}`;
}
function money(n) { return Math.round((Number(n) || 0) * 100) / 100; }

// ---- CSV import helpers (zero-dependency) ----
function parseCsv(text) {
  const rows = []; let row = []; let field = ''; let inQuotes = false;
  const len = text.length; let i = 0;
  while (i < len) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i += 2; continue; } inQuotes = false; i += 1; continue; }
      field += c; i += 1; continue;
    }
    if (c === '"') { inQuotes = true; i += 1; continue; }
    if (c === ',') { row.push(field); field = ''; i += 1; continue; }
    if (c === '\r') { i += 1; continue; }
    if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; i += 1; continue; }
    field += c; i += 1;
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }
  return rows.filter((r) => !(r.length === 1 && r[0].trim() === ''));
}
function csvToObjects(text) {
  const rows = parseCsv(text);
  if (!rows.length) return [];
  const headers = rows[0].map((h) => h.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''));
  return rows.slice(1).map((r) => {
    const obj = {};
    headers.forEach((h, idx) => { obj[h] = (r[idx] !== undefined ? r[idx] : '').trim(); });
    return obj;
  });
}
function parseFlexibleDate(str) {
  if (!str) return null;
  const s = String(str).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if (m) { let [, mo, d, y] = m; if (y.length === 2) y = `20${y}`; return `${y}-${mo.padStart(2, '0')}-${d.padStart(2, '0')}`; }
  return null;
}
function parseMoneyLoose(str) {
  if (str === undefined || str === null || str === '') return null;
  const n = Number(String(str).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? null : n;
}

// ---- .xlsx import helpers (zero-dependency) ----
// An .xlsx file is just a zip archive of XML files. Rather than pull in a
// library for it, this reads the zip's central directory by hand (well-
// documented, fixed-layout binary format), inflates each entry with Node's
// built-in zlib (the only compression method real spreadsheet exports use),
// and picks apart the small slice of the OOXML spec — workbook.xml (which
// sheet is first), sharedStrings.xml (Excel dedupes repeated text into a
// shared table instead of writing it inline) and the sheet's own XML — that
// a plain data export actually uses. It deliberately does not handle
// multi-sheet selection, cell styles/formatting, formulas, or merged cells;
// this is for reading a single flat table off the first tab, which is what
// every "download this sheet" export from Excel or Google Sheets produces.
function zipCentralDirectoryEntries(buf) {
  const EOCD_SIG = 0x06054b50;
  let eocdOffset = -1;
  const searchFloor = Math.max(0, buf.length - 66000); // EOCD (22B) + max 64KB comment
  for (let i = buf.length - 22; i >= searchFloor; i--) {
    if (buf.readUInt32LE(i) === EOCD_SIG) { eocdOffset = i; break; }
  }
  if (eocdOffset === -1) throw new Error('That file is not a valid .xlsx');
  const cdEntryCount = buf.readUInt16LE(eocdOffset + 10);
  const cdOffset = buf.readUInt32LE(eocdOffset + 16);

  const entries = [];
  const CD_SIG = 0x02014b50;
  let p = cdOffset;
  for (let i = 0; i < cdEntryCount; i++) {
    if (buf.readUInt32LE(p) !== CD_SIG) break;
    const compressionMethod = buf.readUInt16LE(p + 10);
    const compressedSize = buf.readUInt32LE(p + 20);
    const nameLen = buf.readUInt16LE(p + 28);
    const extraLen = buf.readUInt16LE(p + 30);
    const commentLen = buf.readUInt16LE(p + 32);
    const localHeaderOffset = buf.readUInt32LE(p + 42);
    const name = buf.toString('utf8', p + 46, p + 46 + nameLen);
    entries.push({ name, compressionMethod, compressedSize, localHeaderOffset });
    p += 46 + nameLen + extraLen + commentLen;
  }
  return entries;
}
function zipExtractEntry(buf, entry) {
  const LOCAL_SIG = 0x04034b50;
  const p = entry.localHeaderOffset;
  if (buf.readUInt32LE(p) !== LOCAL_SIG) throw new Error(`Corrupt .xlsx entry: ${entry.name}`);
  const nameLen = buf.readUInt16LE(p + 26);
  const extraLen = buf.readUInt16LE(p + 28);
  const dataStart = p + 30 + nameLen + extraLen;
  const compressed = buf.subarray(dataStart, dataStart + entry.compressedSize);
  if (entry.compressionMethod === 0) return Buffer.from(compressed);
  if (entry.compressionMethod === 8) return zlib.inflateRawSync(compressed);
  throw new Error(`Unsupported .xlsx compression method: ${entry.compressionMethod}`);
}
function xmlUnescape(s) {
  return String(s)
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&amp;/g, '&');
}
function parseSharedStrings(xml) {
  if (!xml) return [];
  const strings = [];
  const siRe = /<si[^>]*>([\s\S]*?)<\/si>/g;
  let m;
  while ((m = siRe.exec(xml))) {
    const parts = [];
    const tRe = /<t[^>]*>([\s\S]*?)<\/t>/g;
    let tm;
    while ((tm = tRe.exec(m[1]))) parts.push(xmlUnescape(tm[1]));
    strings.push(parts.join(''));
  }
  return strings;
}
function colLetterToIndex(letters) {
  let n = 0;
  for (let i = 0; i < letters.length; i++) n = n * 26 + (letters.charCodeAt(i) - 64);
  return n - 1;
}
// Excel/Sheets store dates as a plain number of days since 1899-12-30 (that
// epoch, not 1/1/1900, is what makes the format's well-known "1900 was a
// leap year" bug line up correctly) — this is the standard conversion every
// spreadsheet app uses to read/write that serial.
function excelSerialToDateStr(serial) {
  const n = Number(serial);
  if (!isFinite(n)) return null;
  const d = new Date(Math.round((n - 25569) * 86400 * 1000));
  if (isNaN(d.getTime())) return null;
  return `${d.getUTCMonth() + 1}/${d.getUTCDate()}/${d.getUTCFullYear()}`;
}
function parseSheetRows(xml, sharedStrings) {
  const rows = [];
  const rowRe = /<row\b[^>]*>([\s\S]*?)<\/row>/g;
  let rm;
  while ((rm = rowRe.exec(xml))) {
    const cells = [];
    const cellRe = /<c\b([^>]*?)\/>|<c\b([^>]*?)>([\s\S]*?)<\/c>/g;
    let cm;
    while ((cm = cellRe.exec(rm[1]))) {
      const attrs = cm[2] !== undefined ? cm[2] : cm[1];
      const inner = cm[3] || '';
      const refMatch = attrs.match(/\br="([A-Z]+)\d+"/);
      const colIdx = refMatch ? colLetterToIndex(refMatch[1]) : cells.length;
      const typeMatch = attrs.match(/\bt="([^"]+)"/);
      const type = typeMatch ? typeMatch[1] : null;
      let value = '';
      if (type === 'inlineStr') {
        const tMatch = inner.match(/<t[^>]*>([\s\S]*?)<\/t>/);
        value = tMatch ? xmlUnescape(tMatch[1]) : '';
      } else {
        const vMatch = inner.match(/<v[^>]*>([\s\S]*?)<\/v>/);
        const raw = vMatch ? vMatch[1] : '';
        if (type === 's') value = sharedStrings[parseInt(raw, 10)] || '';
        else if (type === 'b') value = raw === '1' ? 'TRUE' : 'FALSE';
        else if (type === 'str') value = xmlUnescape(raw);
        else value = raw; // plain number, or a date serial — resolved once headers are known
      }
      cells[colIdx] = value;
    }
    rows.push(cells);
  }
  return rows;
}
// Converts an uploaded .xlsx file's first sheet into the same shape
// csvToObjects() produces (array of objects keyed by a normalized header
// name), so every existing import endpoint can accept either format without
// its own row-mapping/validation logic changing at all.
function parseXlsxToObjects(buf) {
  const entries = zipCentralDirectoryEntries(buf);
  const byName = {};
  entries.forEach((e) => { byName[e.name] = e; });
  const readXml = (name) => (byName[name] ? zipExtractEntry(buf, byName[name]).toString('utf8') : null);

  const workbookXml = readXml('xl/workbook.xml');
  const relsXml = readXml('xl/_rels/workbook.xml.rels');
  if (!workbookXml) throw new Error('That .xlsx file looks corrupted (no workbook found)');

  // The first <sheet> element in workbook.xml is the first tab, regardless
  // of what its underlying sheetN.xml file happens to be named.
  let sheetPath = 'xl/worksheets/sheet1.xml';
  const firstSheetTag = workbookXml.match(/<sheet\b[^>]*\/?>/);
  const rIdMatch = firstSheetTag && firstSheetTag[0].match(/r:id="([^"]+)"/);
  if (rIdMatch && relsXml) {
    const relRe = new RegExp(`<Relationship\\b[^>]*\\bId="${rIdMatch[1]}"[^>]*\\bTarget="([^"]+)"`);
    const relMatch = relsXml.match(relRe);
    if (relMatch) sheetPath = relMatch[1].replace(/^\.?\//, '').startsWith('xl/') ? relMatch[1].replace(/^\.?\//, '') : `xl/${relMatch[1].replace(/^\.?\//, '')}`;
  }

  const sharedStrings = parseSharedStrings(readXml('xl/sharedStrings.xml'));
  const sheetXml = readXml(sheetPath) || readXml('xl/worksheets/sheet1.xml');
  if (!sheetXml) throw new Error('Could not find a worksheet inside that .xlsx file');

  const rows = parseSheetRows(sheetXml, sharedStrings);
  if (!rows.length) return [];
  const headers = rows[0].map((h) => String(h || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''));
  return rows.slice(1).map((r) => {
    const obj = {};
    headers.forEach((h, idx) => {
      if (!h) return;
      let v = r[idx] !== undefined ? String(r[idx]) : '';
      // A purely-numeric value under a header mentioning "date" is almost
      // certainly an Excel date serial (spreadsheets store dates as numbers,
      // never as text) — convert it to the same M/D/YYYY shape a CSV export
      // would already be in, so parseFlexibleDate() handles either the same way.
      if (v && /date/.test(h) && /^\d+(\.\d+)?$/.test(v)) {
        const converted = excelSerialToDateStr(v);
        if (converted) v = converted;
      }
      obj[h] = v.trim();
    });
    return obj;
  });
}
// Shared by every bulk-import endpoint: accepts either `{ csv }` (raw CSV
// text, from a .csv upload) or `{ xlsx_base64 }` (a base64-encoded .xlsx
// upload — see readFileForImport() in app.js) and returns the same array of
// row objects either way.
function rowsFromImportBody(b) {
  if (b && b.xlsx_base64) return parseXlsxToObjects(Buffer.from(b.xlsx_base64, 'base64'));
  return csvToObjects((b && b.csv) || '');
}

// ---- Zero-dependency .xlsx template writer (the counterpart to the .xlsx
// import reader above) — builds a minimal single-sheet workbook containing
// just a header row, so "Download a blank Excel template" produces a real
// .xlsx a person can fill in directly in Excel/Google Sheets, not a .csv. ----
function xlsxCrc32(buf) {
  let crc = ~0;
  for (let i = 0; i < buf.length; i++) {
    crc ^= buf[i];
    for (let j = 0; j < 8; j++) crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1));
  }
  return (~crc) >>> 0;
}

// Builds a .zip (uncompressed/"stored" entries — simplest to get byte-exact
// and plenty small for a template file) from an array of {name, data:Buffer}.
function buildZipStored(files) {
  const dosTime = 0, dosDate = 0x0021; // fixed valid DOS date (1980-01-01); contents don't depend on it
  let offset = 0;
  const localParts = [], centralParts = [];
  for (const f of files) {
    const nameBuf = Buffer.from(f.name, 'utf8');
    const data = f.data;
    const crc = xlsxCrc32(data);
    const localHeader = Buffer.alloc(30);
    localHeader.writeUInt32LE(0x04034b50, 0);
    localHeader.writeUInt16LE(20, 4);
    localHeader.writeUInt16LE(0, 6);
    localHeader.writeUInt16LE(0, 8);
    localHeader.writeUInt16LE(dosTime, 10);
    localHeader.writeUInt16LE(dosDate, 12);
    localHeader.writeUInt32LE(crc, 14);
    localHeader.writeUInt32LE(data.length, 18);
    localHeader.writeUInt32LE(data.length, 22);
    localHeader.writeUInt16LE(nameBuf.length, 26);
    localHeader.writeUInt16LE(0, 28);
    const localEntry = Buffer.concat([localHeader, nameBuf, data]);
    localParts.push(localEntry);

    const centralHeader = Buffer.alloc(46);
    centralHeader.writeUInt32LE(0x02014b50, 0);
    centralHeader.writeUInt16LE(20, 4);
    centralHeader.writeUInt16LE(20, 6);
    centralHeader.writeUInt16LE(0, 8);
    centralHeader.writeUInt16LE(0, 10);
    centralHeader.writeUInt16LE(dosTime, 12);
    centralHeader.writeUInt16LE(dosDate, 14);
    centralHeader.writeUInt32LE(crc, 16);
    centralHeader.writeUInt32LE(data.length, 20);
    centralHeader.writeUInt32LE(data.length, 24);
    centralHeader.writeUInt16LE(nameBuf.length, 28);
    centralHeader.writeUInt16LE(0, 30);
    centralHeader.writeUInt16LE(0, 32);
    centralHeader.writeUInt16LE(0, 34);
    centralHeader.writeUInt16LE(0, 36);
    centralHeader.writeUInt32LE(0, 38);
    centralHeader.writeUInt32LE(offset, 42);
    centralParts.push(Buffer.concat([centralHeader, nameBuf]));

    offset += localEntry.length;
  }
  const localBuf = Buffer.concat(localParts);
  const centralBuf = Buffer.concat(centralParts);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(0, 4);
  end.writeUInt16LE(0, 6);
  end.writeUInt16LE(files.length, 8);
  end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(centralBuf.length, 12);
  end.writeUInt32LE(localBuf.length, 16);
  end.writeUInt16LE(0, 20);
  return Buffer.concat([localBuf, centralBuf, end]);
}

function xlsxXmlEscape(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function xlsxColLetter(n) {
  let s = '', num = n + 1;
  while (num > 0) {
    const rem = (num - 1) % 26;
    s = String.fromCharCode(65 + rem) + s;
    num = Math.floor((num - 1) / 26);
  }
  return s;
}

// Builds a one-row (header-only) .xlsx workbook a person can open directly
// in Excel/Google Sheets and fill in, then re-upload through the same
// importer that reads real .xlsx exports.
function buildXlsxTemplate(headers) {
  const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>`;
  const rootRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`;
  const workbook = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Sheet1" sheetId="1" r:id="rId1"/></sheets></workbook>`;
  const workbookRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`;
  const rowCells = headers.map((h, i) => `<c r="${xlsxColLetter(i)}1" t="inlineStr"><is><t>${xlsxXmlEscape(h)}</t></is></c>`).join('');
  const colWidths = headers.map((_, i) => `<col min="${i + 1}" max="${i + 1}" width="20" customWidth="1"/>`).join('');
  const sheet = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols>${colWidths}</cols><sheetData><row r="1">${rowCells}</row></sheetData></worksheet>`;
  const files = [
    { name: '[Content_Types].xml', data: Buffer.from(contentTypes, 'utf8') },
    { name: '_rels/.rels', data: Buffer.from(rootRels, 'utf8') },
    { name: 'xl/workbook.xml', data: Buffer.from(workbook, 'utf8') },
    { name: 'xl/_rels/workbook.xml.rels', data: Buffer.from(workbookRels, 'utf8') },
    { name: 'xl/worksheets/sheet1.xml', data: Buffer.from(sheet, 'utf8') },
  ];
  return buildZipStored(files);
}

function sendXlsx(res, filename, buf) {
  res.writeHead(200, {
    'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'Content-Length': buf.length,
    'Content-Disposition': `attachment; filename="${filename}"`,
    'Cache-Control': 'no-store',
  });
  res.end(buf);
}

function sendJson(res, status, data) {
  const body = JSON.stringify(data);
  res.writeHead(status, { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body), 'Cache-Control': 'no-store' });
  res.end(body);
}

async function readJsonBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => { data += chunk; if (data.length > 20_000_000) { req.destroy(); reject(new Error('Body too large')); } });
    req.on('end', () => { if (!data) return resolve({}); try { resolve(JSON.parse(data)); } catch (e) { reject(new Error('Invalid JSON body')); } });
    req.on('error', reject);
  });
}

// ---------------------------------------------------------------------------
// Auth (cookie sessions)
// ---------------------------------------------------------------------------
const SESSION_COOKIE = 'mf_session';
const sessions = new Map();

function parseCookies(req) {
  const header = req.headers.cookie;
  const out = {};
  if (!header) return out;
  header.split(';').forEach((pair) => {
    const idx = pair.indexOf('=');
    if (idx === -1) return;
    out[pair.slice(0, idx).trim()] = decodeURIComponent(pair.slice(idx + 1).trim());
  });
  return out;
}
function getSession(req) {
  const sid = parseCookies(req)[SESSION_COOKIE];
  return sid ? sessions.get(sid) || null : null;
}
function createSession(res, payload) {
  const sid = crypto.randomBytes(24).toString('hex');
  sessions.set(sid, { ...payload, createdAt: Date.now() });
  res.setHeader('Set-Cookie', `${SESSION_COOKIE}=${sid}; HttpOnly; Path=/; SameSite=Lax; Max-Age=2592000`);
  return sid;
}
function destroySession(req, res) {
  const sid = parseCookies(req)[SESSION_COOKIE];
  if (sid) sessions.delete(sid);
  res.setHeader('Set-Cookie', `${SESSION_COOKIE}=; HttpOnly; Path=/; SameSite=Lax; Max-Age=0`);
}
function hashPassword(plain) {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(String(plain), salt, 64).toString('hex');
  return { hash, salt };
}
function verifyPassword(plain, hash, salt) {
  if (!hash || !salt) return false;
  const candidate = crypto.scryptSync(String(plain), salt, 64).toString('hex');
  const a = Buffer.from(candidate, 'hex');
  const b = Buffer.from(hash, 'hex');
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

// ---------------------------------------------------------------------------
// Stripe (raw REST calls, no SDK)
// ---------------------------------------------------------------------------
function stripeConfigured() { return Boolean(STRIPE_SECRET_KEY); }
function toFormBody(obj, prefix) {
  const parts = [];
  for (const [key, value] of Object.entries(obj)) {
    const paramKey = prefix ? `${prefix}[${key}]` : key;
    if (value === undefined || value === null) continue;
    if (typeof value === 'object' && !Array.isArray(value)) parts.push(toFormBody(value, paramKey));
    else if (Array.isArray(value)) value.forEach((v, i) => {
      if (typeof v === 'object') parts.push(toFormBody(v, `${paramKey}[${i}]`));
      else parts.push(`${encodeURIComponent(`${paramKey}[${i}]`)}=${encodeURIComponent(v)}`);
    });
    else parts.push(`${encodeURIComponent(paramKey)}=${encodeURIComponent(value)}`);
  }
  return parts.join('&');
}
async function createCheckoutSession({ invoiceNumber, amountCents, customerName, description, successUrl, cancelUrl, invoiceId }) {
  if (!stripeConfigured()) throw new Error('STRIPE_SECRET_KEY is not set. Add it in Railway’s Variables tab to enable online payments.');
  const body = toFormBody({
    mode: 'payment', success_url: successUrl, cancel_url: cancelUrl,
    line_items: [{ quantity: 1, price_data: { currency: 'usd', unit_amount: amountCents, product_data: { name: `Invoice ${invoiceNumber}`, description: description || `Payment for ${customerName}` } } }],
    metadata: { invoice_id: String(invoiceId) },
  });
  const resp = await fetch(`${STRIPE_API}/checkout/sessions`, { method: 'POST', headers: { Authorization: `Bearer ${STRIPE_SECRET_KEY}`, 'Content-Type': 'application/x-www-form-urlencoded' }, body });
  const json = await resp.json();
  if (!resp.ok) throw new Error(json.error?.message || 'Stripe checkout session creation failed');
  return json;
}
function verifyWebhookSignature(rawBody, signatureHeader) {
  if (!STRIPE_WEBHOOK_SECRET || !signatureHeader) return false;
  const parts = Object.fromEntries(signatureHeader.split(',').map((p) => p.split('=')));
  if (!parts.t || !parts.v1) return false;
  const expected = crypto.createHmac('sha256', STRIPE_WEBHOOK_SECRET).update(`${parts.t}.${rawBody}`).digest('hex');
  try { return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(parts.v1)); } catch { return false; }
}

// ---------------------------------------------------------------------------
// Email-to-text (free alternative to Twilio) — sends SMS via carrier email
// gateways (e.g. number@vtext.com) using a raw SMTP client over TLS.
// ---------------------------------------------------------------------------
const CARRIER_GATEWAYS = {
  verizon: 'vtext.com',
  att: 'txt.att.net',
  tmobile: 'tmomail.net',
  sprint: 'messaging.sprintpcs.com',
  uscellular: 'email.uscc.net',
  boost: 'sms.myboostmobile.com',
  cricket: 'sms.cricketwireless.net',
  metro: 'mymetropcs.com',
  googlefi: 'msg.fi.google.com',
  visible: 'vtext.com',
  mint: 'tmomail.net',
  straighttalk: 'vtext.com',
};
function emailSmsConfigured() { return Boolean(SMTP_USER && SMTP_PASS); }
function gatewayAddressFor(recipient) {
  const digits = String(recipient.phone).replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
  if (!digits) throw new Error(`Recipient "${recipient.name}" has no usable phone number`);
  const domain = recipient.carrier === 'other' ? recipient.custom_gateway_domain : CARRIER_GATEWAYS[recipient.carrier];
  if (!domain) throw new Error(`Recipient "${recipient.name}" has no known carrier gateway (carrier: ${recipient.carrier || 'unset'})`);
  return `${digits}@${domain}`;
}
function readSmtpResponse(socket) {
  return new Promise((resolve, reject) => {
    let buffer = '';
    const onData = (chunk) => {
      buffer += chunk.toString('utf8');
      const lines = buffer.split('\r\n').filter(Boolean);
      const last = lines[lines.length - 1];
      if (last && /^\d{3} /.test(last)) { cleanup(); resolve(buffer); }
    };
    const onError = (err) => { cleanup(); reject(err); };
    const onEnd = () => { cleanup(); reject(new Error('SMTP connection closed unexpectedly')); };
    function cleanup() { socket.removeListener('data', onData); socket.removeListener('error', onError); socket.removeListener('end', onEnd); }
    socket.on('data', onData);
    socket.on('error', onError);
    socket.on('end', onEnd);
  });
}
function checkSmtpOk(response, step) {
  const code = Number(response.slice(0, 3));
  if (code >= 400) throw new Error(`SMTP error during ${step}: ${response.trim()}`);
}
function sendSmtpLine(socket, line) { socket.write(line + '\r\n'); }
async function sendEmailSms(recipients, subject, body) {
  if (!emailSmsConfigured()) throw new Error('Email-to-SMS is not configured (SMTP_USER / SMTP_PASS).');
  if (!recipients.length) return { sent: 0 };

  const addresses = [];
  const skipped = [];
  for (const r of recipients) {
    try { addresses.push({ name: r.name, address: gatewayAddressFor(r) }); }
    catch (e) { skipped.push({ name: r.name, error: e.message }); }
  }
  if (skipped.length) skipped.forEach((s) => console.error(`Skipping SMS recipient ${s.name}: ${s.error}`));
  if (!addresses.length) throw new Error('No recipients had a usable carrier gateway address.');

  const CONNECT_TIMEOUT_MS = 10_000;
  const COMMAND_TIMEOUT_MS = 15_000;
  const socket = tls.connect({ host: SMTP_HOST, port: SMTP_PORT, servername: SMTP_HOST });
  socket.setTimeout(COMMAND_TIMEOUT_MS, () => socket.destroy(new Error('SMTP connection timed out')));
  try {
    await new Promise((resolve, reject) => {
      const timer = setTimeout(() => { socket.destroy(); reject(new Error(`Could not reach ${SMTP_HOST}:${SMTP_PORT} (timed out)`)); }, CONNECT_TIMEOUT_MS);
      socket.once('secureConnect', () => { clearTimeout(timer); resolve(); });
      socket.once('error', (e) => { clearTimeout(timer); reject(e); });
    });
    checkSmtpOk(await readSmtpResponse(socket), 'greeting');

    sendSmtpLine(socket, `EHLO ${SMTP_HOST}`);
    checkSmtpOk(await readSmtpResponse(socket), 'EHLO');

    sendSmtpLine(socket, 'AUTH LOGIN');
    checkSmtpOk(await readSmtpResponse(socket), 'AUTH LOGIN');
    sendSmtpLine(socket, Buffer.from(SMTP_USER).toString('base64'));
    checkSmtpOk(await readSmtpResponse(socket), 'AUTH username');
    sendSmtpLine(socket, Buffer.from(SMTP_PASS).toString('base64'));
    checkSmtpOk(await readSmtpResponse(socket), 'AUTH password');

    sendSmtpLine(socket, `MAIL FROM:<${SMTP_FROM}>`);
    checkSmtpOk(await readSmtpResponse(socket), 'MAIL FROM');

    for (const a of addresses) {
      sendSmtpLine(socket, `RCPT TO:<${a.address}>`);
      checkSmtpOk(await readSmtpResponse(socket), `RCPT TO ${a.address}`);
    }

    sendSmtpLine(socket, 'DATA');
    checkSmtpOk(await readSmtpResponse(socket), 'DATA');
    const message = [
      `From: ${SMTP_FROM}`,
      `To: ${addresses.map((a) => a.address).join(', ')}`,
      `Subject: ${subject}`,
      'Content-Type: text/plain; charset=utf-8',
      '',
      body,
      '.',
    ].join('\r\n');
    sendSmtpLine(socket, message);
    checkSmtpOk(await readSmtpResponse(socket), 'message body');

    sendSmtpLine(socket, 'QUIT');
    socket.end();
    return { sent: addresses.length, skipped };
  } catch (e) {
    socket.destroy();
    throw e;
  }
}

// ---------------------------------------------------------------------------
// Real email (to an actual address, with an optional attachment) — same SMTP
// account as the email-to-SMS gateway above, just a normal MIME message.
// ---------------------------------------------------------------------------
function emailConfigured() { return Boolean(SMTP_USER && SMTP_PASS); }
function dotStuffMessage(message) {
  return message.split(/\r\n|\n/).map((line) => (line.startsWith('.') ? '.' + line : line)).join('\r\n');
}
function base64Wrap(buffer) {
  const b64 = buffer.toString('base64');
  const lines = [];
  for (let i = 0; i < b64.length; i += 76) lines.push(b64.slice(i, i + 76));
  return lines.join('\r\n');
}
async function sendMail({ to, subject, text, attachments = [] }) {
  if (!emailConfigured()) throw new Error('Email is not configured (SMTP_USER / SMTP_PASS).');
  if (!to) throw new Error('No recipient email address given.');

  const boundary = `----opd-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const parts = [];
  parts.push(`--${boundary}`, 'Content-Type: text/plain; charset=utf-8', '', text || '', '');
  for (const att of attachments) {
    parts.push(
      `--${boundary}`,
      `Content-Type: ${att.contentType || 'application/octet-stream'}; name="${att.filename}"`,
      'Content-Transfer-Encoding: base64',
      `Content-Disposition: attachment; filename="${att.filename}"`,
      '',
      base64Wrap(att.content),
      ''
    );
  }
  parts.push(`--${boundary}--`, '');

  const message = dotStuffMessage([
    `From: ${SMTP_FROM}`,
    `To: ${to}`,
    `Subject: ${subject}`,
    'MIME-Version: 1.0',
    `Content-Type: multipart/mixed; boundary="${boundary}"`,
    '',
    ...parts,
  ].join('\r\n'));

  const CONNECT_TIMEOUT_MS = 10_000;
  const COMMAND_TIMEOUT_MS = 20_000;
  const socket = tls.connect({ host: SMTP_HOST, port: SMTP_PORT, servername: SMTP_HOST });
  socket.setTimeout(COMMAND_TIMEOUT_MS, () => socket.destroy(new Error('SMTP connection timed out')));
  try {
    await new Promise((resolve, reject) => {
      const timer = setTimeout(() => { socket.destroy(); reject(new Error(`Could not reach ${SMTP_HOST}:${SMTP_PORT} (timed out)`)); }, CONNECT_TIMEOUT_MS);
      socket.once('secureConnect', () => { clearTimeout(timer); resolve(); });
      socket.once('error', (e) => { clearTimeout(timer); reject(e); });
    });
    checkSmtpOk(await readSmtpResponse(socket), 'greeting');

    sendSmtpLine(socket, `EHLO ${SMTP_HOST}`);
    checkSmtpOk(await readSmtpResponse(socket), 'EHLO');

    sendSmtpLine(socket, 'AUTH LOGIN');
    checkSmtpOk(await readSmtpResponse(socket), 'AUTH LOGIN');
    sendSmtpLine(socket, Buffer.from(SMTP_USER).toString('base64'));
    checkSmtpOk(await readSmtpResponse(socket), 'AUTH username');
    sendSmtpLine(socket, Buffer.from(SMTP_PASS).toString('base64'));
    checkSmtpOk(await readSmtpResponse(socket), 'AUTH password');

    sendSmtpLine(socket, `MAIL FROM:<${SMTP_FROM}>`);
    checkSmtpOk(await readSmtpResponse(socket), 'MAIL FROM');
    sendSmtpLine(socket, `RCPT TO:<${to}>`);
    checkSmtpOk(await readSmtpResponse(socket), 'RCPT TO');

    sendSmtpLine(socket, 'DATA');
    checkSmtpOk(await readSmtpResponse(socket), 'DATA');
    sendSmtpLine(socket, message + '\r\n.');
    checkSmtpOk(await readSmtpResponse(socket), 'message body');

    sendSmtpLine(socket, 'QUIT');
    socket.end();
    return { sent: true };
  } catch (e) {
    socket.destroy();
    throw e;
  }
}

// ---------------------------------------------------------------------------
// Minimal zero-dependency PDF writer — see lib/pdf.js in the source repo for
// the full explanation. Builds a single-page Letter PDF using only the
// standard built-in Helvetica fonts (no embedding needed), enough for a
// simple one-order invoice/receipt to email a customer.
// ---------------------------------------------------------------------------
const PDF_PAGE_WIDTH = 612;
const PDF_PAGE_HEIGHT = 792;
function toAsciiSafe(s) {
  return String(s ?? '').replace(/[–—]/g, '-').replace(/[‘’]/g, "'").replace(/[“”]/g, '"');
}
function escapePdfText(s) {
  return toAsciiSafe(s).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
}
class PdfDoc {
  constructor() { this.pages = []; this.ops = []; this.images = []; }
  newPage() { this.pages.push(this.ops); this.ops = []; }
  text(x, y, str, { font = 'F1', size = 10 } = {}) {
    this.ops.push(`BT /${font} ${size} Tf ${x} ${y} Td (${escapePdfText(str)}) Tj ET`);
  }
  hline(x, y, w, lineWidth = 0.75) { this.ops.push(`${lineWidth} w ${x} ${y} m ${x + w} ${y} l S`); }
  filledRect(x, y, w, h, gray = 0.9) { this.ops.push(`${gray} g ${x} ${y} ${w} ${h} re f 0 g`); }
  strokeRect(x, y, w, h, lineWidth = 0.75) { this.ops.push(`${lineWidth} w ${x} ${y} ${w} ${h} re S`); }
  // Images (PNG/JPEG already converted by pngToPdfImage/jpegToPdfImage).
  addImage(img) { this.images.push(img); return this.images.length - 1; }
  image(x, y, w, h, idx) { this.ops.push(`q ${w} 0 0 ${h} ${x} ${y} cm /Im${idx} Do Q`); }
  pageCount() { return this.pages.length + 1; }
  // Draw on an already-finished page (used for "Page 2 of 5" footers).
  textOnPage(pageIdx, x, y, str, { font = 'F1', size = 10 } = {}) {
    const target = pageIdx < this.pages.length ? this.pages[pageIdx] : this.ops;
    target.push(`BT /${font} ${size} Tf ${x} ${y} Td (${escapePdfText(str)}) Tj ET`);
  }
  toBuffer() {
    this.pages.push(this.ops);
    const contents = this.pages;
    const N = contents.length;
    const pageObjNums = Array.from({ length: N }, (_, i) => 3 + i);
    const contentObjNums = Array.from({ length: N }, (_, i) => 3 + N + i);
    const f1Num = 3 + 2 * N;
    const f2Num = f1Num + 1;
    const xobj = this.images.length ? ` /XObject << ${this.images.map((_, k) => `/Im${k} ${f2Num + 1 + k} 0 R`).join(' ')} >>` : '';
    const objects = [];
    objects.push('<< /Type /Catalog /Pages 2 0 R >>');
    objects.push(`<< /Type /Pages /Kids [${pageObjNums.map((n) => `${n} 0 R`).join(' ')}] /Count ${N} >>`);
    for (let i = 0; i < N; i++) {
      objects.push(`<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 ${f1Num} 0 R /F2 ${f2Num} 0 R >>${xobj} >> /MediaBox [0 0 ${PDF_PAGE_WIDTH} ${PDF_PAGE_HEIGHT}] /Contents ${contentObjNums[i]} 0 R >>`);
    }
    for (let i = 0; i < N; i++) {
      const content = contents[i].join('\n');
      const contentBytes = Buffer.byteLength(content, 'utf8');
      objects.push(`<< /Length ${contentBytes} >>\nstream\n${content}\nendstream`);
    }
    objects.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
    objects.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
    this.images.forEach((img) => {
      objects.push({ dict: `<< /Type /XObject /Subtype /Image /Width ${img.w} /Height ${img.h} /ColorSpace ${img.cs} /BitsPerComponent 8 /Filter /${img.filter}${img.extra ? ' ' + img.extra : ''} /Length ${img.data.length} >>`, stream: img.data });
    });
    const chunks = [Buffer.from('%PDF-1.4\n', 'utf8')];
    let total = chunks[0].length;
    const offsets = [0];
    const push = (b) => { chunks.push(b); total += b.length; };
    objects.forEach((body, i) => {
      offsets.push(total);
      if (typeof body === 'string') push(Buffer.from(`${i + 1} 0 obj\n${body}\nendobj\n`, 'utf8'));
      else { push(Buffer.from(`${i + 1} 0 obj\n${body.dict}\nstream\n`, 'utf8')); push(body.stream); push(Buffer.from('\nendstream\nendobj\n', 'utf8')); }
    });
    const xrefStart = total;
    let tail = `xref\n0 ${objects.length + 1}\n`;
    tail += '0000000000 65535 f \n';
    for (let i = 1; i <= objects.length; i++) tail += `${String(offsets[i]).padStart(10, '0')} 00000 n \n`;
    tail += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`;
    push(Buffer.from(tail, 'utf8'));
    return Buffer.concat(chunks);
  }
}
function buildOrderInvoicePdf(order, customer, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  let y = PDF_PAGE_HEIGHT - 60;
  doc.filledRect(0, PDF_PAGE_HEIGHT - 90, PDF_PAGE_WIDTH, 90, 0.93);
  doc.text(50, y, companyName, { font: 'F2', size: 20 });
  y -= 22;
  doc.text(50, y, 'Delivery Invoice', { font: 'F1', size: 12 });
  y = PDF_PAGE_HEIGHT - 110;

  doc.text(50, y, `Invoice for Order ${order.order_number}`, { font: 'F2', size: 13 });
  const orderDate = formatEasternDate(order.created_at);
  doc.text(PDF_PAGE_WIDTH - 200, y, `Date: ${orderDate}`, { size: 10 });
  y -= 28;

  doc.text(50, y, 'Bill To:', { font: 'F2', size: 10 });
  y -= 14;
  doc.text(50, y, order.customer_name || customer.name || '', { size: 10 });
  y -= 14;
  wrapPdfText(order.delivery_address || '', 60).forEach((line) => { doc.text(50, y, line, { size: 10 }); y -= 14; });
  if (customer.phone) { doc.text(50, y, customer.phone, { size: 10 }); y -= 14; }
  y -= 10;

  doc.hline(50, y, PDF_PAGE_WIDTH - 100);
  y -= 16;
  doc.text(50, y, 'Description', { font: 'F2', size: 10 });
  doc.text(300, y, 'Qty', { font: 'F2', size: 10 });
  doc.text(360, y, 'Unit Price', { font: 'F2', size: 10 });
  doc.text(460, y, 'Amount', { font: 'F2', size: 10 });
  y -= 8;
  doc.hline(50, y, PDF_PAGE_WIDTH - 100);
  y -= 18;

  const qty = Number(order.quantity || 0);
  const price = Number(order.price_per_unit || 0);
  const materialAmount = qty * price;
  doc.text(50, y, truncatePdfText(`${order.material_name || 'Material'} — delivered to ${order.delivery_address || ''}`, 'F1', 10, 242), { size: 10 });
  doc.text(300, y, `${qty} ${order.unit || ''}`, { size: 10 });
  doc.text(360, y, `$${price.toFixed(2)}`, { size: 10 });
  doc.text(460, y, `$${materialAmount.toFixed(2)}`, { size: 10 });
  y -= 18;

  const deliveryFee = Number(order.delivery_fee || 0);
  if (deliveryFee > 0) {
    const label = order.distance_miles ? `Delivery Fee (${order.distance_miles} mi)` : 'Delivery Fee';
    doc.text(50, y, label, { size: 10 });
    doc.text(460, y, `$${deliveryFee.toFixed(2)}`, { size: 10 });
    y -= 18;
  }

  doc.hline(300, y + 6, PDF_PAGE_WIDTH - 350);
  y -= 4;
  doc.text(360, y, 'Subtotal', { size: 10 });
  doc.text(460, y, `$${(materialAmount + deliveryFee).toFixed(2)}`, { size: 10 });
  y -= 16;

  const salesTax = Number(order.sales_tax_amount || 0);
  if (salesTax) {
    doc.text(360, y, `Sales Tax${order.sales_tax_rate ? ` (${order.sales_tax_rate}%)` : ''}`, { size: 10 });
    doc.text(460, y, `$${salesTax.toFixed(2)}`, { size: 10 });
    y -= 16;
  }

  doc.hline(300, y + 8, PDF_PAGE_WIDTH - 350);
  y -= 4;
  const total = Number(order.total_amount || (materialAmount + deliveryFee + salesTax));
  doc.text(360, y, 'Total', { font: 'F2', size: 12 });
  doc.text(460, y, `$${total.toFixed(2)}`, { font: 'F2', size: 12 });
  y -= 26;

  if (order.payment_collected) {
    const collected = Number(order.payment_collected_amount || 0);
    const method = order.payment_collected_method || 'other';
    doc.text(50, y, `Payment received at delivery: $${collected.toFixed(2)} (${method}). Thank you!`, { font: 'F2', size: 10 });
    y -= 20;
  } else {
    doc.text(50, y, 'Please remit payment at your earliest convenience.', { size: 10 });
    y -= 20;
  }

  if (order.notes) {
    y -= 6;
    doc.text(50, y, 'Notes:', { font: 'F2', size: 9 });
    y -= 13;
    wrapPdfText(order.notes, 95).forEach((line) => { doc.text(50, y, line, { size: 9 }); y -= 13; });
  }

  doc.text(50, 50, `Thank you for your business — ${companyName}`, { size: 9 });
  return doc.toBuffer();
}
function buildFinancialReportPdf(summary, orders, opts = {}) {
  const companyName = opts.companyName || 'OPD Development Corp';
  const periodLabel = opts.periodLabel || 'All Time';
  const doc = new PdfDoc();
  const marginX = 50;
  const pageBottom = 60;
  let y;
  function header(title) {
    doc.filledRect(0, PDF_PAGE_HEIGHT - 70, PDF_PAGE_WIDTH, 70, 0.93);
    doc.text(marginX, PDF_PAGE_HEIGHT - 40, companyName, { font: 'F2', size: 18 });
    doc.text(marginX, PDF_PAGE_HEIGHT - 58, title, { size: 11 });
    doc.text(PDF_PAGE_WIDTH - 200, PDF_PAGE_HEIGHT - 40, `Generated ${formatEasternDate(new Date())}`, { size: 9 });
    doc.text(PDF_PAGE_WIDTH - 200, PDF_PAGE_HEIGHT - 54, `Period: ${periodLabel}`, { size: 9 });
    return PDF_PAGE_HEIGHT - 95;
  }
  y = header('Financial Summary');
  doc.text(marginX, y, 'Key Figures', { font: 'F2', size: 12 }); y -= 18;
  const s = summary.stats;
  [
    ['Combined Revenue', `$${Number(s.combinedRevenue).toFixed(2)}`],
    ['Materials Revenue', `$${Number(s.materialsRevenueAllTime).toFixed(2)}`],
    ['Jobs Revenue (Won)', `$${Number(s.jobsRevenueWon).toFixed(2)}`],
    ['Jobs Pipeline Value', `$${Number(s.jobsPipelineValue).toFixed(2)}`],
    ['Orders (all time)', `${s.orderCount}`],
    ['Avg Order Value', `$${Number(s.avgOrderValue).toFixed(2)}`],
  ].forEach(([label, value]) => { doc.text(marginX, y, label, { size: 10 }); doc.text(marginX + 220, y, value, { size: 10 }); y -= 15; });
  y -= 10;
  doc.text(marginX, y, 'Invoices', { font: 'F2', size: 12 }); y -= 18;
  const inv = summary.invoices;
  [
    ['Paid', `$${Number(inv.paidInvoicesTotal).toFixed(2)}`],
    ['Outstanding', `$${Number(inv.outstandingInvoices).toFixed(2)}`],
    ['Overdue Invoices', `${inv.overdueCount}`],
    ['Draft', `$${Number(inv.draftTotal).toFixed(2)}`],
  ].forEach(([label, value]) => { doc.text(marginX, y, label, { size: 10 }); doc.text(marginX + 220, y, value, { size: 10 }); y -= 15; });
  y -= 10;
  doc.text(marginX, y, 'Monthly Revenue', { font: 'F2', size: 12 }); y -= 16;
  doc.text(marginX, y, 'Month', { font: 'F2', size: 9 });
  doc.text(marginX + 120, y, 'Materials', { font: 'F2', size: 9 });
  doc.text(marginX + 220, y, 'Jobs', { font: 'F2', size: 9 });
  doc.text(marginX + 300, y, 'Total', { font: 'F2', size: 9 });
  y -= 6; doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2); y -= 13;
  (summary.monthlyRevenue || []).forEach((r) => {
    doc.text(marginX, y, r.month, { size: 9 });
    doc.text(marginX + 120, y, `$${Number(r.materials).toFixed(2)}`, { size: 9 });
    doc.text(marginX + 220, y, `$${Number(r.jobs).toFixed(2)}`, { size: 9 });
    doc.text(marginX + 300, y, `$${Number(r.total).toFixed(2)}`, { size: 9 });
    y -= 13;
  });
  y -= 8;
  doc.text(marginX, y, 'Revenue by Material', { font: 'F2', size: 12 }); y -= 16;
  (summary.revenueByMaterial || []).slice(0, 12).forEach((r) => {
    doc.text(marginX, y, truncatePdfText(r.material_name, 'F1', 9, 290), { size: 9 });
    doc.text(marginX + 300, y, `$${Number(r.revenue).toFixed(2)}`, { size: 9 });
    y -= 13;
  });
  y -= 8;
  doc.text(marginX, y, 'Top Customers', { font: 'F2', size: 12 }); y -= 16;
  (summary.topCustomers || []).slice(0, 12).forEach((r) => {
    doc.text(marginX, y, truncatePdfText(r.customer_name, 'F1', 9, 290), { size: 9 });
    doc.text(marginX + 300, y, `$${Number(r.revenue).toFixed(2)}`, { size: 9 });
    y -= 13;
  });
  doc.newPage();
  y = header('Order Ledger');
  const cols = [
    { label: 'Date', x: marginX, w: 50 }, { label: 'Order #', x: marginX + 55, w: 88 }, { label: 'Customer', x: marginX + 148, w: 108 },
    { label: 'Material', x: marginX + 261, w: 78 }, { label: 'Qty', x: marginX + 344, w: 42 }, { label: 'Amount', x: marginX + 391, w: 55 }, { label: 'Status', x: marginX + 451, w: 61 },
  ];
  function ledgerTableHeader() {
    cols.forEach((c) => doc.text(c.x, y, c.label, { font: 'F2', size: 9 }));
    y -= 6; doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2); y -= 13;
  }
  ledgerTableHeader();
  (orders || []).forEach((o) => {
    if (y < pageBottom + 20) { doc.newPage(); y = header('Order Ledger (cont.)'); ledgerTableHeader(); }
    doc.text(cols[0].x, y, formatEasternDateShort(o.created_at), { size: 8 });
    doc.text(cols[1].x, y, truncatePdfText(o.order_number || '', 'F1', 8, cols[1].w - 4), { size: 8 });
    doc.text(cols[2].x, y, truncatePdfText(o.customer_name || '', 'F1', 8, cols[2].w - 4), { size: 8 });
    doc.text(cols[3].x, y, truncatePdfText(o.material_name || '', 'F1', 8, cols[3].w - 4), { size: 8 });
    doc.text(cols[4].x, y, truncatePdfText(`${o.quantity} ${o.unit || ''}`, 'F1', 8, cols[4].w - 4), { size: 8 });
    doc.text(cols[5].x, y, truncatePdfText(`$${Number(o.total_amount || 0).toFixed(2)}`, 'F1', 8, cols[5].w - 4), { size: 8 });
    doc.text(cols[6].x, y, truncatePdfText(o.status || '', 'F1', 8, cols[6].w - 4), { size: 8 });
    y -= 12;
  });
  return doc.toBuffer();
}

// Builds a one-page end-of-shift report for a driver's time clock —
// clock in/out times, hours worked, loads delivered, and a payment
// breakdown ending in the cash figure the driver owes the office.
function buildDriverShiftReportPdf(shift, driver, stats, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  const marginX = 50;
  let y = PDF_PAGE_HEIGHT - 60;

  doc.filledRect(0, PDF_PAGE_HEIGHT - 90, PDF_PAGE_WIDTH, 90, 0.93);
  doc.text(marginX, y, companyName, { font: 'F2', size: 20 });
  y -= 22;
  doc.text(marginX, y, 'Driver Shift Report', { font: 'F1', size: 12 });
  y = PDF_PAGE_HEIGHT - 110;

  const shiftDate = formatEasternDate(shift.clock_in);
  doc.text(marginX, y, `${driver.name}${driver.truck_label ? ' — ' + driver.truck_label : ''}`, { font: 'F2', size: 13 });
  doc.text(PDF_PAGE_WIDTH - 200, y, `Date: ${shiftDate}`, { size: 10 });
  y -= 22;

  doc.text(marginX, y, `Clocked in:  ${formatEasternDateTime(shift.clock_in)}`, { size: 10 });
  y -= 15;
  doc.text(marginX, y, `Clocked out: ${shift.clock_out ? formatEasternDateTime(shift.clock_out) : 'still clocked in'}`, { size: 10 });
  y -= 15;
  doc.text(marginX, y, `Hours worked: ${Number(stats.hours || 0).toFixed(2)}`, { size: 10 });
  y -= 24;

  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 18;
  doc.text(marginX, y, 'Deliveries This Shift', { font: 'F2', size: 12 });
  y -= 18;
  doc.text(marginX, y, `Completed: ${stats.deliveredCount}   Total Quantity: ${Number(stats.totalQuantity || 0)}`, { size: 10 });
  y -= 20;

  if ((stats.deliveries || []).length) {
    doc.text(marginX, y, 'Order', { font: 'F2', size: 9 });
    doc.text(marginX + 90, y, 'Customer', { font: 'F2', size: 9 });
    doc.text(marginX + 240, y, 'Material', { font: 'F2', size: 9 });
    doc.text(marginX + 340, y, 'Qty', { font: 'F2', size: 9 });
    doc.text(marginX + 400, y, 'Amount', { font: 'F2', size: 9 });
    y -= 6;
    doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
    y -= 13;
    stats.deliveries.forEach((d) => {
      if (y < 140) { doc.newPage(); y = PDF_PAGE_HEIGHT - 60; }
      doc.text(marginX, y, truncatePdfText(d.order_number || '', 'F1', 8, 86), { size: 8 });
      doc.text(marginX + 90, y, truncatePdfText(d.customer_name || '', 'F1', 8, 144), { size: 8 });
      doc.text(marginX + 240, y, truncatePdfText(d.material_name || '', 'F1', 8, 94), { size: 8 });
      doc.text(marginX + 340, y, truncatePdfText(`${d.quantity} ${d.unit || ''}`, 'F1', 8, 54), { size: 8 });
      doc.text(marginX + 400, y, d.amount != null ? `$${Number(d.amount).toFixed(2)}` : '—', { size: 8 });
      y -= 12;
    });
    y -= 8;
  }

  if (y < 180) { doc.newPage(); y = PDF_PAGE_HEIGHT - 60; }
  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 18;
  doc.text(marginX, y, 'Payments Collected', { font: 'F2', size: 12 });
  y -= 20;
  [
    ['Cash', stats.cashTotal],
    ['Check', stats.checkTotal],
    ['Other', stats.otherTotal],
  ].forEach(([label, value]) => {
    doc.text(marginX, y, label, { size: 10 });
    doc.text(marginX + 200, y, `$${Number(value || 0).toFixed(2)}`, { size: 10 });
    y -= 16;
  });
  y -= 6;
  doc.hline(marginX + 180, y + 6, 150);
  y -= 4;
  doc.text(marginX, y, 'Total Collected', { font: 'F2', size: 11 });
  doc.text(marginX + 200, y, `$${Number(stats.grandCollected || 0).toFixed(2)}`, { font: 'F2', size: 11 });
  y -= 30;

  doc.filledRect(marginX - 10, y - 10, PDF_PAGE_WIDTH - marginX * 2 + 20, 34, 0.88);
  doc.text(marginX, y + 6, 'CASH TO TURN IN TO OFFICE:', { font: 'F2', size: 13 });
  doc.text(marginX + 260, y + 6, `$${Number(stats.cashTotal || 0).toFixed(2)}`, { font: 'F2', size: 13 });

  return doc.toBuffer();
}

// One-page delivery slip for a single truckload — meant to be downloaded and
// sent straight to the customer (see GET /api/deliveries/:id/slip.pdf), not
// just filed internally like the removal/material slips. Shows what this one
// load carried and its own price, never the whole order's other loads or
// internal driver-pay detail, and ends in a "Received By" signature line for
// the customer rather than "Driver Signature"/"Office Signature" — this
// document is going out the door, not coming back in.
function buildDeliverySlipPdf(delivery, company = {}) {
  const doc = new PdfDoc();
  appendDeliverySlipPage(doc, delivery, company);
  return doc.toBuffer();
}
// Draws one delivery's slip onto whatever page `doc` is currently on — split
// out from buildDeliverySlipPdf so GET /api/orders/:id/slips.pdf can call
// this once per load onto a shared multi-page PdfDoc instead of building (and
// throwing away) a separate one-page PDF per load.
function appendDeliverySlipPage(doc, delivery, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const isTrucking = delivery.order_type === 'trucking';
  const marginX = 50;
  let y = PDF_PAGE_HEIGHT - 60;

  doc.filledRect(0, PDF_PAGE_HEIGHT - 90, PDF_PAGE_WIDTH, 90, 0.93);
  doc.text(marginX, y, companyName, { font: 'F2', size: 20 });
  y -= 22;
  doc.text(marginX, y, 'Delivery Slip', { font: 'F1', size: 12 });
  y = PDF_PAGE_HEIGHT - 110;

  const loadLabel = delivery.total_deliveries > 1 ? `Load ${delivery.sequence} of ${delivery.total_deliveries} — Order ${delivery.order_number}` : `Order ${delivery.order_number}`;
  doc.text(marginX, y, loadLabel, { font: 'F2', size: 13 });
  const dateLabel = delivery.status === 'delivered'
    ? `Delivered: ${formatEasternDate(delivery.delivered_at || delivery.updated_at)}`
    : `Scheduled: ${delivery.scheduled_date ? formatEasternDateShort(delivery.scheduled_date) : 'TBD'}`;
  doc.text(PDF_PAGE_WIDTH - 220, y, dateLabel, { size: 10 });
  y -= 24;

  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 20;

  const rows = [['Customer', delivery.customer_name]];
  if (isTrucking) {
    rows.push(['Pickup Address', delivery.delivery_address || '—']);
    if (delivery.trucking_dropoff_address) rows.push(['Dropoff Address', delivery.trucking_dropoff_address]);
    rows.push(['Service', 'Trucking (hourly)']);
    rows.push(['Hours', `${Number(delivery.quantity || 0)} hr`]);
    rows.push(['Rate', `$${Number(delivery.order_price_per_unit || 0).toFixed(2)}/hr`]);
  } else {
    rows.push(['Delivery Address', delivery.delivery_address || '—']);
    rows.push(['Material', delivery.material_name]);
    rows.push(['Quantity', `${delivery.quantity} ${delivery.unit}`]);
    rows.push(['Price per Unit', `$${Number(delivery.order_price_per_unit || 0).toFixed(2)}`]);
  }
  rows.push(['Amount', delivery.amount != null ? `$${Number(delivery.amount).toFixed(2)}` : '—']);
  rows.push(['Driver', delivery.driver_name || '—']);
  if (delivery.payment_collected) {
    rows.push(['Payment', `$${Number(delivery.payment_collected_amount || 0).toFixed(2)} collected (${delivery.payment_collected_method || 'other'})`]);
  }
  rows.forEach(([label, value]) => {
    doc.text(marginX, y, label, { font: 'F2', size: 10 });
    doc.text(marginX + 140, y, truncatePdfText(String(value || ''), 'F1', 10, PDF_PAGE_WIDTH - marginX * 2 - 140), { size: 10 });
    y -= 18;
  });

  const notes = delivery.driver_notes || delivery.order_notes;
  if (notes) {
    y -= 4;
    doc.text(marginX, y, 'Notes:', { font: 'F2', size: 9 });
    y -= 13;
    wrapPdfText(notes, 100).forEach((line) => { doc.text(marginX, y, line, { size: 9 }); y -= 13; });
  }

  y = Math.min(y - 30, 160);
  doc.hline(marginX, y, 220);
  doc.text(marginX, y - 14, 'Received By (Print Name)', { size: 9 });
  doc.hline(marginX + 260, y, 100);
  doc.text(marginX + 260, y - 14, 'Date', { size: 9 });
  y -= 50;
  doc.hline(marginX, y, 220);
  doc.text(marginX, y - 14, 'Signature', { size: 9 });
  doc.hline(marginX + 260, y, 100);
  doc.text(marginX + 260, y - 14, 'Date', { size: 9 });
}

// One-page, printable record of a single load hauled away from a job site —
// meant to be printed and filed in that job's paperwork (see
// GET /api/removal-slips/:id/report.pdf). Signature lines at the bottom are
// deliberately blank — this is a paper form once it's off the printer, not
// just a screenshot of the database row.
function buildRemovalSlipReportPdf(slip, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  const marginX = 50;
  let y = PDF_PAGE_HEIGHT - 60;

  doc.filledRect(0, PDF_PAGE_HEIGHT - 90, PDF_PAGE_WIDTH, 90, 0.93);
  doc.text(marginX, y, companyName, { font: 'F2', size: 20 });
  y -= 22;
  doc.text(marginX, y, 'Job Site Material Removal Slip', { font: 'F1', size: 12 });
  y = PDF_PAGE_HEIGHT - 110;

  doc.text(marginX, y, `Slip #${slip.id}`, { font: 'F2', size: 13 });
  doc.text(PDF_PAGE_WIDTH - 220, y, `Logged: ${formatEasternDateTime(slip.created_at)}`, { size: 10 });
  y -= 24;

  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 20;

  const jobLabel = slip.job_customer_name ? `${slip.job_number} — ${slip.job_customer_name}` : slip.job_number;
  [
    ['Job', jobLabel],
    ['Site Address', slip.job_site_address || '—'],
    ['Driver', slip.driver_name],
    ['Material / Debris', slip.material],
    ['Quantity', `${slip.quantity} ${slip.unit}${slip.quantity === 1 ? '' : 's'}`],
    ['Destination', slip.destination || '—'],
  ].forEach(([label, value]) => {
    doc.text(marginX, y, label, { font: 'F2', size: 10 });
    doc.text(marginX + 140, y, truncatePdfText(String(value || ''), 'F1', 10, PDF_PAGE_WIDTH - marginX * 2 - 140), { size: 10 });
    y -= 18;
  });

  if (slip.notes) {
    y -= 4;
    doc.text(marginX, y, 'Driver Notes:', { font: 'F2', size: 9 });
    y -= 13;
    wrapPdfText(slip.notes, 100).forEach((line) => { doc.text(marginX, y, line, { size: 9 }); y -= 13; });
  }
  if (slip.photo_data) {
    y -= 4;
    doc.text(marginX, y, `A photo of the ticket is on file in MaterialFlow (Slip #${slip.id}).`, { size: 9 });
    y -= 13;
  }

  y -= 12;
  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 20;

  doc.text(marginX, y, 'Office Review', { font: 'F2', size: 12 });
  y -= 20;
  if (slip.status === 'reviewed') {
    doc.text(marginX, y, `Cost: $${Number(slip.cost || 0).toFixed(2)}`, { font: 'F2', size: 11 });
    y -= 18;
    doc.text(marginX, y, `Reviewed by ${slip.reviewed_by || 'office'} on ${formatEasternDate(slip.reviewed_at)}`, { size: 10 });
    y -= 18;
    if (slip.review_notes) {
      doc.text(marginX, y, 'Office Notes:', { font: 'F2', size: 9 });
      y -= 13;
      wrapPdfText(slip.review_notes, 100).forEach((line) => { doc.text(marginX, y, line, { size: 9 }); y -= 13; });
    }
  } else {
    doc.filledRect(marginX - 6, y - 8, 220, 22, 0.9);
    doc.text(marginX, y, 'PENDING OFFICE REVIEW', { font: 'F2', size: 11 });
    y -= 26;
  }

  y = Math.min(y - 30, 160);
  doc.hline(marginX, y, 220);
  doc.text(marginX, y - 14, 'Driver Signature', { size: 9 });
  doc.hline(marginX + 260, y, 100);
  doc.text(marginX + 260, y - 14, 'Date', { size: 9 });
  y -= 50;
  doc.hline(marginX, y, 220);
  doc.text(marginX, y - 14, 'Office Signature', { size: 9 });
  doc.hline(marginX + 260, y, 100);
  doc.text(marginX + 260, y - 14, 'Date', { size: 9 });

  return doc.toBuffer();
}

// Multi-page ledger of removal slips matching whatever filters the office
// had applied on removal-slips.html when they hit "Print" — for batch
// filing/review rather than one load at a time (see
// GET /api/removal-slips/report.pdf).
function buildRemovalSlipsBatchPdf(slips, opts = {}) {
  const companyName = opts.companyName || 'OPD Development Corp';
  const periodLabel = opts.periodLabel || 'All Time';
  const doc = new PdfDoc();
  const marginX = 50;
  const pageBottom = 60;
  let y;
  function header(title) {
    doc.filledRect(0, PDF_PAGE_HEIGHT - 70, PDF_PAGE_WIDTH, 70, 0.93);
    doc.text(marginX, PDF_PAGE_HEIGHT - 40, companyName, { font: 'F2', size: 18 });
    doc.text(marginX, PDF_PAGE_HEIGHT - 58, title, { size: 11 });
    doc.text(PDF_PAGE_WIDTH - 200, PDF_PAGE_HEIGHT - 40, `Generated ${formatEasternDate(new Date())}`, { size: 9 });
    doc.text(PDF_PAGE_WIDTH - 200, PDF_PAGE_HEIGHT - 54, `Period: ${periodLabel}`, { size: 9 });
    return PDF_PAGE_HEIGHT - 95;
  }
  y = header('Materials In/Disposal From Job Sites');

  const needsReview = slips.filter((s) => s.status !== 'reviewed').length;
  const totalCost = slips.reduce((sum, s) => sum + Number(s.cost || 0), 0);
  doc.text(marginX, y, `Total slips: ${slips.length}`, { size: 10 });
  doc.text(marginX + 160, y, `Needs review: ${needsReview}`, { size: 10 });
  doc.text(marginX + 320, y, `Total reviewed cost: $${totalCost.toFixed(2)}`, { size: 10 });
  y -= 20;
  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 18;

  const cols = [
    { label: 'Date', x: marginX, w: 48 },
    { label: 'Job', x: marginX + 52, w: 110 },
    { label: 'Driver', x: marginX + 166, w: 78 },
    { label: 'Material', x: marginX + 248, w: 82 },
    { label: 'Qty', x: marginX + 334, w: 50 },
    { label: 'Destination', x: marginX + 388, w: 90 },
    { label: 'Cost', x: marginX + 482, w: 50 },
  ];
  function tableHeader() {
    cols.forEach((c) => doc.text(c.x, y, c.label, { font: 'F2', size: 9 }));
    y -= 6;
    doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
    y -= 13;
  }
  tableHeader();
  if (!slips.length) {
    doc.text(marginX, y, 'No removal slips match this range.', { size: 10 });
    y -= 14;
  }
  slips.forEach((s) => {
    if (y < pageBottom + 20) { doc.newPage(); y = header('Materials In/Disposal From Job Sites (cont.)'); tableHeader(); }
    const jobLabel = s.job_customer_name ? `${s.job_number} — ${s.job_customer_name}` : s.job_number;
    doc.text(cols[0].x, y, formatEasternDateShort(s.created_at), { size: 8 });
    doc.text(cols[1].x, y, truncatePdfText(jobLabel || '', 'F1', 8, cols[1].w - 4), { size: 8 });
    doc.text(cols[2].x, y, truncatePdfText(s.driver_name || '', 'F1', 8, cols[2].w - 4), { size: 8 });
    doc.text(cols[3].x, y, truncatePdfText(s.material || '', 'F1', 8, cols[3].w - 4), { size: 8 });
    doc.text(cols[4].x, y, truncatePdfText(`${s.quantity} ${s.unit}`, 'F1', 8, cols[4].w - 4), { size: 8 });
    doc.text(cols[5].x, y, truncatePdfText(s.destination || '', 'F1', 8, cols[5].w - 4), { size: 8 });
    doc.text(cols[6].x, y, s.status === 'reviewed' ? `$${Number(s.cost || 0).toFixed(2)}` : 'pending', { size: 8 });
    y -= 12;
  });
  return doc.toBuffer();
}

const OPEN_ORDER_STATUS_LABELS = {
  new: 'New', scheduled: 'Scheduled', out_for_delivery: 'Out for Delivery', delivered: 'Delivered (awaiting invoice)',
};

// A snapshot of every order still needing action — not yet invoiced,
// cancelled, or refused — for a quick printable "what's still open" report.
function buildOpenOrdersReportPdf(orders, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  const marginX = 50;
  const pageBottom = 60;
  let y;

  function header(title) {
    doc.filledRect(0, PDF_PAGE_HEIGHT - 70, PDF_PAGE_WIDTH, 70, 0.93);
    doc.text(marginX, PDF_PAGE_HEIGHT - 40, companyName, { font: 'F2', size: 18 });
    doc.text(marginX, PDF_PAGE_HEIGHT - 58, title, { size: 11 });
    doc.text(PDF_PAGE_WIDTH - 200, PDF_PAGE_HEIGHT - 40, `Generated ${formatEasternDate(new Date())}`, { size: 9 });
    return PDF_PAGE_HEIGHT - 95;
  }

  y = header('Open Orders Report');

  const counts = {};
  let totalValue = 0;
  orders.forEach((o) => { counts[o.status] = (counts[o.status] || 0) + 1; totalValue += Number(o.total_amount || 0); });

  doc.text(marginX, y, 'Summary', { font: 'F2', size: 12 });
  y -= 18;
  doc.text(marginX, y, `Total open orders: ${orders.length}`, { size: 10 });
  doc.text(marginX + 220, y, `Total value: $${totalValue.toFixed(2)}`, { size: 10 });
  y -= 16;
  Object.keys(OPEN_ORDER_STATUS_LABELS).forEach((status) => {
    if (!counts[status]) return;
    doc.text(marginX, y, `${OPEN_ORDER_STATUS_LABELS[status]}: ${counts[status]}`, { size: 10 });
    y -= 14;
  });
  y -= 10;

  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 18;

  const cols = [
    { label: 'Order #', x: marginX, w: 78 },
    { label: 'Status', x: marginX + 78, w: 95 },
    { label: 'Customer', x: marginX + 173, w: 75 },
    { label: 'Material', x: marginX + 248, w: 65 },
    { label: 'Qty', x: marginX + 313, w: 42 },
    { label: 'Driver', x: marginX + 355, w: 55 },
    { label: 'Sched.', x: marginX + 410, w: 42 },
    { label: 'Amount', x: marginX + 452, w: 48 },
  ];
  function tableHeader() {
    cols.forEach((c) => doc.text(c.x, y, c.label, { font: 'F2', size: 9 }));
    y -= 6;
    doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
    y -= 13;
  }
  tableHeader();
  if (!orders.length) {
    doc.text(marginX, y, 'Nothing open right now — every order is invoiced, cancelled, or refused.', { size: 10 });
  }
  orders.forEach((o) => {
    // wrapPdfText's own char-count wrapping is just a starting guess — it can
    // still hand back a line too wide for the Status column's real point
    // width (e.g. a long word), so each wrapped line goes through
    // truncatePdfText too as a hard backstop.
    const statusLines = wrapPdfText(OPEN_ORDER_STATUS_LABELS[o.status] || o.status || '', 18)
      .map((line) => truncatePdfText(line, 'F1', 8, cols[1].w - 4));
    const rowHeight = Math.max(12, statusLines.length * 10);
    if (y - rowHeight < pageBottom) {
      doc.newPage();
      y = header('Open Orders Report (cont.)');
      tableHeader();
    }
    doc.text(cols[0].x, y, truncatePdfText(o.order_number || '', 'F1', 8, cols[0].w - 4), { size: 8 });
    statusLines.forEach((line, i) => doc.text(cols[1].x, y - i * 10, line, { size: 8 }));
    doc.text(cols[2].x, y, truncatePdfText(o.customer_name || '', 'F1', 8, cols[2].w - 4), { size: 8 });
    doc.text(cols[3].x, y, truncatePdfText(o.material_name || '', 'F1', 8, cols[3].w - 4), { size: 8 });
    doc.text(cols[4].x, y, truncatePdfText(`${o.quantity}${o.unit ? ' ' + o.unit : ''}`, 'F1', 8, cols[4].w - 4), { size: 8 });
    doc.text(cols[5].x, y, truncatePdfText(o.driver_name || 'Unassign.', 'F1', 8, cols[5].w - 4), { size: 8 });
    doc.text(cols[6].x, y, o.scheduled_date ? formatDateOnlyShort(o.scheduled_date) : '—', { size: 8 });
    doc.text(cols[7].x, y, truncatePdfText(`$${Number(o.total_amount || 0).toFixed(2)}`, 'F1', 8, cols[7].w - 4), { size: 8 });
    y -= rowHeight;
  });

  return doc.toBuffer();
}

// A printable per-driver rundown of one day's stops — one page per driver.
function buildDriverDayReportPdf(dateStr, deliveries, company = {}, collectedElsewhere = []) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  const marginX = 50;
  const dateObj = new Date(`${dateStr}T00:00:00`);
  const dateLabel = isNaN(dateObj.getTime())
    ? dateStr
    : dateObj.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  function pageHeader(driverName, truckLabel) {
    let py = PDF_PAGE_HEIGHT - 60;
    doc.filledRect(0, PDF_PAGE_HEIGHT - 90, PDF_PAGE_WIDTH, 90, 0.93);
    doc.text(marginX, py, companyName, { font: 'F2', size: 20 });
    py -= 22;
    doc.text(marginX, py, 'Driver Schedule', { font: 'F1', size: 12 });
    py = PDF_PAGE_HEIGHT - 110;
    doc.text(marginX, py, `${driverName}${truckLabel ? ' — ' + truckLabel : ''}`, { font: 'F2', size: 14 });
    doc.text(PDF_PAGE_WIDTH - 230, py, dateLabel, { size: 10 });
    return py - 26;
  }

  // Stops this driver collected payment on but delivered by someone else —
  // kept visually separate from the stops they actually ran, so the report
  // never reads as if they delivered loads that weren't theirs.
  function renderCollectedElsewhere(y) {
    if (!collectedElsewhere.length) return y;
    if (y < 150) { doc.newPage(); y = PDF_PAGE_HEIGHT - 60; }
    y -= 12;
    doc.text(marginX, y, 'Payments You Collected', { font: 'F2', size: 12 });
    y -= 14;
    doc.text(marginX, y, 'Stops delivered by someone else, where you collected the payment', { size: 9 });
    y -= 18;
    collectedElsewhere.forEach((d, i) => {
      if (y < 100) { doc.newPage(); y = PDF_PAGE_HEIGHT - 60; }
      doc.text(marginX, y, `${i + 1}. ${d.delivery_address}`, { font: 'F2', size: 11 });
      y -= 15;
      doc.text(marginX + 14, y, `${d.quantity} ${d.unit} ${d.material_name} for ${d.customer_name} — Order #${d.order_number} — delivered by ${d.driver_name || 'another driver'}`, { size: 10 });
      y -= 15;
      doc.text(marginX + 14, y, `$${Number(d.payment_collected_amount || 0).toFixed(2)} collected (${d.payment_collected_method || 'other'})`, { size: 9 });
      y -= 20;
    });
    return y;
  }

  const byDriver = new Map();
  const unassigned = [];
  deliveries.forEach((d) => {
    if (!d.driver_id) { unassigned.push(d); return; }
    if (!byDriver.has(d.driver_id)) byDriver.set(d.driver_id, { name: d.driver_name || 'Driver', truck: d.driver_truck, items: [] });
    byDriver.get(d.driver_id).items.push(d);
  });
  const groups = Array.from(byDriver.values()).sort((a, b) => a.name.localeCompare(b.name));
  if (unassigned.length) groups.push({ name: 'Unassigned', truck: null, items: unassigned });

  if (!groups.length) {
    // No stops delivered that day, but may still have collected payment on
    // someone else's stop — that still deserves a page rather than nothing.
    const headerName = collectedElsewhere.length ? (collectedElsewhere[0].payment_collected_by_name || 'Driver') : 'No Deliveries';
    let y = pageHeader(headerName, null);
    if (collectedElsewhere.length) {
      renderCollectedElsewhere(y);
    } else {
      doc.text(marginX, y, 'Nothing scheduled for this day.', { size: 11 });
    }
    return doc.toBuffer();
  }

  groups.forEach((g, gi) => {
    if (gi > 0) doc.newPage();
    let y = pageHeader(g.name, g.truck);
    doc.text(marginX, y, `${g.items.length} stop${g.items.length === 1 ? '' : 's'} today`, { font: 'F2', size: 10 });
    y -= 22;
    const items = g.items.slice().sort((a, b) => (a.slot_index ?? 99) - (b.slot_index ?? 99));
    items.forEach((d, i) => {
      if (y < 100) { doc.newPage(); y = PDF_PAGE_HEIGHT - 60; }
      const asap = d.requested_window === 'ASAP' ? '  (ASAP)' : '';
      const load = d.total_deliveries > 1 ? ` (load ${d.sequence}/${d.total_deliveries})` : '';
      doc.text(marginX, y, `${i + 1}. ${d.delivery_address}${asap}`, { font: 'F2', size: 11 });
      y -= 15;
      doc.text(marginX + 14, y, `${d.quantity} ${d.unit} ${d.material_name} for ${d.customer_name} — Order #${d.order_number}${load}`, { size: 10 });
      y -= 15;
      if (d.customer_phone) { doc.text(marginX + 14, y, `Phone: ${d.customer_phone}`, { size: 9 }); y -= 13; }
      if (d.order_notes) {
        wrapPdfText(`Note: ${d.order_notes}`, 90).forEach((line) => { doc.text(marginX + 14, y, line, { size: 9 }); y -= 12; });
      }
      y -= 10;
    });
    // Only one group exists when this report is scoped to a single driver
    // (the only case collectedElsewhere is ever populated), but guard on
    // "last group" regardless so it can never render more than once.
    if (gi === groups.length - 1) renderCollectedElsewhere(y);
  });

  return doc.toBuffer();
}

// ---------------------------------------------------------------------------
// Twilio (raw REST calls, no SDK) — SMS order alerts
// ---------------------------------------------------------------------------
function twilioConfigured() { return Boolean(TWILIO_ACCOUNT_SID && TWILIO_AUTH_TOKEN && TWILIO_FROM_NUMBER); }
async function sendSms(to, body) {
  if (!twilioConfigured()) throw new Error('Twilio is not configured.');
  const url = `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`;
  const params = new URLSearchParams({ To: to, From: TWILIO_FROM_NUMBER, Body: body });
  const auth = Buffer.from(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`).toString('base64');
  const resp = await fetch(url, { method: 'POST', headers: { Authorization: `Basic ${auth}`, 'Content-Type': 'application/x-www-form-urlencoded' }, body: params.toString() });
  const json = await resp.json();
  if (!resp.ok) throw new Error(json.message || 'Twilio send failed');
  return json;
}
async function broadcastSms(recipients, body) {
  const results = await Promise.allSettled(recipients.map((r) => sendSms(r.phone, body)));
  results.forEach((r, i) => { if (r.status === 'rejected') console.error(`SMS to ${recipients[i].name} (${recipients[i].phone}) failed:`, r.reason?.message || r.reason); });
  return results;
}

// ---------------------------------------------------------------------------
// ClickSend (raw REST calls, no SDK) — primary SMS channel. Carrier
// email-to-text gateways (AT&T/Verizon/T-Mobile) were shut down
// industry-wide in 2025 to fight spam abuse, so a real SMS API is needed.
// ---------------------------------------------------------------------------
function clicksendConfigured() { return Boolean(CLICKSEND_USERNAME && CLICKSEND_API_KEY); }
function clicksendE164(phone) {
  const raw = String(phone || '').trim();
  if (raw.startsWith('+')) return raw;
  const digits = raw.replace(/\D/g, '');
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith('1')) return `+${digits}`;
  return `+${digits}`;
}
async function sendClickSendSms(to, body) {
  if (!clicksendConfigured()) throw new Error('ClickSend is not configured (CLICKSEND_USERNAME / CLICKSEND_API_KEY).');
  const auth = Buffer.from(`${CLICKSEND_USERNAME}:${CLICKSEND_API_KEY}`).toString('base64');
  const message = { source: 'materialflow', to: clicksendE164(to), body };
  if (CLICKSEND_FROM) message.from = CLICKSEND_FROM;
  const resp = await fetch('https://rest.clicksend.com/v3/sms/send', {
    method: 'POST',
    headers: { Authorization: `Basic ${auth}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ messages: [message] }),
  });
  let json = null;
  try { json = await resp.json(); } catch (e) { /* no body */ }
  const firstResult = json?.data?.messages?.[0];
  const ok = resp.ok && json && json.response_code === 'SUCCESS' && (!firstResult || firstResult.status !== 'FAILED');
  if (!ok) {
    const detail = firstResult?.status_text || firstResult?.status || json?.response_msg || `HTTP ${resp.status}`;
    throw new Error(`ClickSend send failed: ${detail}`);
  }
  return json;
}
async function broadcastClickSendSms(recipients, body) {
  const results = await Promise.allSettled(recipients.map((r) => sendClickSendSms(r.phone, body)));
  results.forEach((r, i) => { if (r.status === 'rejected') console.error(`ClickSend to ${recipients[i].name} (${recipients[i].phone}) failed:`, r.reason?.message || r.reason); });
  return results;
}

// ---------------------------------------------------------------------------
// Anthropic (raw REST calls, no SDK) — powers "paste a paragraph, get a
// pre-filled order" on New Order. Never creates anything on its own; only
// ever returns best-guess fields for the office to review.
// ---------------------------------------------------------------------------
function anthropicConfigured() { return Boolean(ANTHROPIC_API_KEY); }
async function anthropicExtractJson(systemPrompt, userText, { maxTokens = 700 } = {}) {
  if (!anthropicConfigured()) {
    throw new Error("AI order parsing isn't configured yet — add an ANTHROPIC_API_KEY variable in Railway.");
  }
  const resp = await fetch(ANTHROPIC_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
    body: JSON.stringify({ model: ANTHROPIC_MODEL, max_tokens: maxTokens, system: systemPrompt, messages: [{ role: 'user', content: userText }] }),
  });
  const json = await resp.json().catch(() => null);
  if (!resp.ok) {
    const detail = (json && json.error && json.error.message) || resp.statusText;
    throw new Error(`AI parsing failed (${resp.status}): ${detail}. If this model has been retired, set ORDER_PARSE_MODEL in Railway to a current one.`);
  }
  const textBlock = (json.content || []).find((b) => b.type === 'text');
  if (!textBlock) throw new Error('AI parsing failed: empty response from the model.');
  const raw = textBlock.text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '');
  try { return JSON.parse(raw); } catch (e) { throw new Error("AI parsing failed: the model's response wasn't valid JSON."); }
}

function formatOrderSms(order) {
  const materialCost = Number(order.quantity || 0) * Number(order.price_per_unit || 0);
  const salesTax = order.sales_tax_amount !== undefined && order.sales_tax_amount !== null
    ? Number(order.sales_tax_amount) : materialCost * (Number(order.sales_tax_rate || 0) / 100);
  const total = order.total_amount !== undefined && order.total_amount !== null
    ? Number(order.total_amount) : materialCost + salesTax + Number(order.delivery_fee || 0);
  const orderDate = (order.created_at || '').slice(0, 10) || todayStr();
  const lines = [
    `NEW ORDER - ${order.order_number}`,
    `- Date: ${orderDate}`,
    `- Name: ${order.customer_name}`,
    `- Address: ${order.delivery_address}`,
    `- Material: ${order.material_name}`,
    `- Amount: ${order.quantity} ${order.unit}`,
    `- Total: $${total.toFixed(2)} (incl. $${salesTax.toFixed(2)} sales tax)`,
  ];
  if (order.customer_phone) lines.push(`- Phone: ${order.customer_phone}`);
  if (order.requested_window === 'ASAP') lines.push('- Requested: ASAP');
  else if (order.requested_date) lines.push(`- Requested: ${order.requested_date}${order.requested_window ? ' ' + order.requested_window : ''}`);
  if (order.deliveries && order.deliveries.length > 1) {
    lines.push(`- Split into ${order.deliveries.length} truckloads (${MAX_YARDS_PER_DELIVERY}yd max each):`);
    order.deliveries.forEach((d) => {
      lines.push(`  ${d.sequence}) ${d.quantity} ${order.unit} — ${d.driver_name ? d.driver_name : 'unassigned'}${d.scheduled_date ? ' on ' + d.scheduled_date : ''}`);
    });
  } else if (order.driver_name) {
    lines.push(`- Driver: ${order.driver_name}${order.scheduled_date ? ' on ' + order.scheduled_date : ''}`);
  }
  if (order.delivery_fee) lines.push(`- Delivery fee: $${Number(order.delivery_fee).toFixed(2)}${order.distance_miles ? ` (${order.distance_miles} mi)` : ''}`);
  if (order.notes) lines.push(`- Notes: ${order.notes}`);
  return lines.join('\n');
}
async function notifyNewOrder(order) {
  try {
    const recipients = all('SELECT * FROM sms_recipients WHERE active = 1');
    if (!recipients.length) return;
    const body = formatOrderSms(order);
    if (clicksendConfigured()) {
      await broadcastClickSendSms(recipients, body);
    } else if (twilioConfigured()) {
      await broadcastSms(recipients, body);
    } else if (emailSmsConfigured()) {
      await sendEmailSms(recipients, `New Order ${order.order_number}`, body);
    }
  } catch (e) { console.error('notifyNewOrder failed:', e && e.stack ? e.stack : e); }
}

// ---------------------------------------------------------------------------
// Route table
// ---------------------------------------------------------------------------
const routes = [];

// ---- Audit log -------------------------------------------------------
function clientIp(req) {
  const fwd = req.headers['x-forwarded-for'];
  if (fwd) return String(fwd).split(',')[0].trim();
  return (req.socket && req.socket.remoteAddress) || '';
}
function recordAudit(req, opts) {
  const {
    role = null, name = null, userId = null, driverId = null, superAdmin = false,
    action, method, path, status = null, detail = null,
  } = opts || {};
  try {
    run(
      `INSERT INTO audit_log (actor_role, actor_name, actor_user_id, actor_driver_id, is_super_admin, action, method, path, status, detail, ip)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [role, name, userId || null, driverId || null, superAdmin ? 1 : 0, action, method, path, status, detail, clientIp(req)]
    );
  } catch (e) {
    console.error('audit log write failed:', e && e.stack ? e.stack : e);
  }
}
const AUDIT_SELF_LOGGED = new Set(['/api/login', '/api/logout']);

function on(method, pattern, handler) {
  const paramNames = [];
  const regexStr = pattern.replace(/:([A-Za-z]+)/g, (_, name) => { paramNames.push(name); return '([^/]+)'; });
  const autoLog = method !== 'GET' && !AUDIT_SELF_LOGGED.has(pattern);
  const wrapped = !autoLog ? handler : async (req, res, params, query) => {
    await handler(req, res, params, query);
    const session = getSession(req);
    recordAudit(req, {
      role: session && session.role,
      name: session && session.name,
      userId: session && session.userId,
      driverId: session && session.driverId,
      superAdmin: isSuperAdmin(session),
      action: req._leadOverride ? 'driver_admin_override' : 'request',
      method,
      path: req.url.split('?')[0],
      status: res.statusCode,
      detail: req._leadOverride ? `Lead driver override by ${req._leadOverride}` : null,
    });
  };
  routes.push({ method, regex: new RegExp(`^${regexStr}$`), paramNames, handler: wrapped });
}

function requireAuth(req, res) {
  const session = getSession(req);
  if (!session) { sendJson(res, 401, { error: 'Not logged in' }); return null; }
  return session;
}
function requireOffice(req, res) {
  const session = requireAuth(req, res);
  if (!session) return null;
  if (session.role !== 'office') { sendJson(res, 403, { error: 'Office access required' }); return null; }
  return session;
}

function isSuperAdmin(session) {
  return !!(session && session.role === 'office' && !session.userId && !session.lead);
}

// ---- Lead driver ("driver admin") ------------------------------------------
// A lead driver keeps a normal driver login. On the specific endpoints that
// the Override tab uses, requireOfficeOrLead() lets them through as a limited
// stand-in for the office: a synthetic session flagged `lead`, with no
// financial/admin/asset/real-estate access and never a super admin. Their
// name shows as "<name> (driver admin)" anywhere the office edit is credited.
function isLeadDriver(session) {
  if (!session || session.role !== 'driver' || !session.driverId) return false;
  const d = get('SELECT is_lead, active FROM drivers WHERE id = ?', [session.driverId]);
  return !!(d && d.is_lead && d.active);
}
function leadSessionFor(session) {
  if (!isLeadDriver(session)) return null;
  return { role: 'office', lead: true, driverId: session.driverId, name: `${session.name || 'Lead driver'} (driver admin)`, userId: null };
}
function requireOfficeOrLead(req, res) {
  const session = requireAuth(req, res);
  if (!session) return null;
  if (session.role === 'office') return session;
  const lead = leadSessionFor(session);
  if (lead) { req._leadOverride = lead.name; return lead; }
  sendJson(res, 403, { error: 'Office access required' });
  return null;
}
// For the driver-style delivery actions (start/deliver/cancel/...): a driver
// may only act on a stop that is theirs or still unassigned. Other drivers'
// stops are view-only. A lead driver acting from the Override tab (which
// sends the X-Lead-Override header) is allowed through without taking the
// stop over. Returns true when it already sent the 403.
function leadOverrideActive(req, session) {
  return req.headers['x-lead-override'] === '1' && isLeadDriver(session);
}
function blockOtherDriverStop(req, res, existing, session) {
  if (!session || session.role !== 'driver') return false;
  if (!existing.driver_id || existing.driver_id === session.driverId) return false;
  if (leadOverrideActive(req, session)) { req._leadOverride = `${session.name} (driver admin)`; return false; }
  const owner = get('SELECT name FROM drivers WHERE id = ?', [existing.driver_id]);
  sendJson(res, 403, { error: `This stop is assigned to ${owner ? owner.name : 'another driver'}. You can view it, but only they — or the lead driver — can change it.` });
  return true;
}

function getAccess(session) {
  if (session && session.lead) return { full: false, can_view_financials: false, can_view_assets: false, can_view_realestate: false, can_access_admin: false };
  if (!session || session.role !== 'office') return null;
  if (!session.userId) return { full: true };
  const user = get('SELECT access_level, can_view_financials, can_view_assets, can_view_realestate, can_access_admin FROM users WHERE id = ?', [session.userId]);
  if (!user || user.access_level === 'full') return { full: true };
  return {
    full: false,
    can_view_financials: !!user.can_view_financials,
    can_view_assets: !!user.can_view_assets,
    can_view_realestate: !!user.can_view_realestate,
    can_access_admin: !!user.can_access_admin,
  };
}

function requireSection(req, res, flag) {
  const session = requireOffice(req, res);
  if (!session) return null;
  const access = getAccess(session);
  if (access.full || access[flag]) return session;
  sendJson(res, 403, { error: "You don't have permission to access this." });
  return null;
}

function requireSuperAdmin(req, res) {
  const session = requireOffice(req, res);
  if (!session) return null;
  if (isSuperAdmin(session)) return session;
  sendJson(res, 403, { error: 'Only the main office account can do this.' });
  return null;
}

const ORDER_SELECT = `
  SELECT o.*, c.name as customer_name, c.phone as customer_phone, c.billing_address as customer_address,
         m.name as material_name, d.name as driver_name, d.truck_label as driver_truck,
         j.job_number as job_number, rd.name as requested_by_driver_name
  FROM orders o JOIN customers c ON c.id = o.customer_id JOIN materials m ON m.id = o.material_id
  LEFT JOIN drivers d ON d.id = o.driver_id
  LEFT JOIN jobs j ON j.id = o.job_id
  LEFT JOIN drivers rd ON rd.id = o.requested_by_driver_id
`;
// Orders the drivers put in themselves (job-site orders, repeat/add-ons, and
// the Materials Out slip placeholders all carry requested_by_driver_id) can't
// just sit at $0: the office is prompted to price them, and the only way one
// stays at $0 is a super user approving it with the override PIN. Trucking
// orders are $0 until the driver punches out, so they only count once delivered.
const NEEDS_PRICE_SQL = `(o.requested_by_driver_id IS NOT NULL AND COALESCE(o.total_amount, 0) <= 0 AND o.zero_price_approved_at IS NULL
  AND o.status NOT IN ('cancelled', 'invoiced', 'paid') AND NOT (o.order_type = 'trucking' AND o.status != 'delivered'))`;
function orderNeedsPrice(o) {
  return !!(o && o.requested_by_driver_id && Number(o.total_amount || 0) <= 0 && !o.zero_price_approved_at
    && !['cancelled', 'invoiced', 'paid'].includes(o.status) && !(o.order_type === 'trucking' && o.status !== 'delivered'));
}
// Override PIN: the dedicated PIN a super user sets in Admin, or the main
// office password. Wrong tries are throttled (5 in 10 minutes).
const zeroOverrideFails = new Map();
function safeStringEq(a, b) {
  const ha = crypto.createHash('sha256').update(String(a)).digest();
  const hb = crypto.createHash('sha256').update(String(b)).digest();
  return crypto.timingSafeEqual(ha, hb);
}
function checkZeroPriceOverride(session, pin) {
  const key = session.userId ? `u${session.userId}` : 'main';
  const rec = zeroOverrideFails.get(key) || { n: 0, until: 0 };
  if (rec.until > Date.now()) return { ok: false, error: 'Too many wrong PIN tries. Wait a few minutes and try again.' };
  const stored = getSetting('zero_price_override_pin', '');
  const good = pin && ((stored && safeStringEq(pin, stored)) || safeStringEq(pin, OFFICE_PASSWORD));
  if (good) { zeroOverrideFails.delete(key); return { ok: true }; }
  rec.n += 1;
  if (rec.n >= 5) { rec.until = Date.now() + 10 * 60 * 1000; rec.n = 0; }
  zeroOverrideFails.set(key, rec);
  return { ok: false, error: 'That override PIN is not right.' };
}
const INTERNAL_JOB_CUSTOMER_NAME = 'OPD Job Sites (Internal)';
function getOrCreateInternalJobCustomer() {
  const existing = get('SELECT * FROM customers WHERE name = ?', [INTERNAL_JOB_CUSTOMER_NAME]);
  if (existing) return existing;
  const result = run('INSERT INTO customers (name, notes) VALUES (?, ?)', [
    INTERNAL_JOB_CUSTOMER_NAME,
    "Auto-created placeholder — groups material loads delivered to OPD's own job sites. Not a real customer; see each order's linked Project for the actual destination.",
  ]);
  return get('SELECT * FROM customers WHERE id = ?', [result.lastInsertRowid]);
}
// Placeholder customer for an order auto-created from a driver's
// self-initiated Materials Out slip (see POST /api/driver/material-slips) —
// unlike the internal-job customer above, we genuinely don't know yet
// whether the load was headed to one of OPD's own sites or a paying
// customer, so it's filed here with $0 pricing instead of guessing either
// way. Shows up plainly in the Customer column on orders-database.html /
// the dashboard's Needs Attention panel so the office knows to open it,
// confirm the real customer, and set a price before it's ever invoiced.
const REVIEW_PLACEHOLDER_CUSTOMER_NAME = 'Needs Review — Unconfirmed Customer';
function getOrCreateReviewPlaceholderCustomer() {
  const existing = get('SELECT * FROM customers WHERE name = ?', [REVIEW_PLACEHOLDER_CUSTOMER_NAME]);
  if (existing) return existing;
  const result = run('INSERT INTO customers (name, notes) VALUES (?, ?)', [
    REVIEW_PLACEHOLDER_CUSTOMER_NAME,
    "Auto-created placeholder — groups orders created automatically from a driver's self-initiated Materials Out slip, before the office has confirmed the real customer and price. Open each order, fix the customer and pricing, then move on.",
  ]);
  return get('SELECT * FROM customers WHERE id = ?', [result.lastInsertRowid]);
}
const TRUCKING_MATERIAL_NAME = 'For-Hire Trucking (Hourly)';
// A for-hire trucking order still needs a material_id (orders.material_id is
// NOT NULL and every order listing/invoice/CSV export already displays
// material_name + quantity + unit generically) — so it points at this one
// auto-created placeholder material instead of a real yard/ton material.
// unit 'hour' and default_price 0 are just there for completeness; a
// trucking order always sets its own price_per_unit (the hourly rate) and
// computes its own quantity (hours) from the driver's punch clock.
function getOrCreateTruckingMaterial() {
  const existing = get('SELECT * FROM materials WHERE name = ?', [TRUCKING_MATERIAL_NAME]);
  if (existing) return existing;
  const result = run('INSERT INTO materials (name, unit, default_price, active) VALUES (?, ?, ?, 1)', [TRUCKING_MATERIAL_NAME, 'hour', 0]);
  return get('SELECT * FROM materials WHERE id = ?', [result.lastInsertRowid]);
}
function nextOrderNumberForDate(date) {
  const prefix = `ORD-${date.getFullYear()}${String(date.getMonth() + 1).padStart(2, '0')}${String(date.getDate()).padStart(2, '0')}`;
  const rows = all('SELECT order_number FROM orders WHERE order_number LIKE ?', [`${prefix}%`]);
  let max = 0;
  rows.forEach((r) => {
    const n = parseInt(r.order_number.slice(prefix.length + 1), 10);
    if (!isNaN(n) && n > max) max = n;
  });
  return `${prefix}-${String(max + 1).padStart(3, '0')}`;
}
function nextOrderNumber() { return nextOrderNumberForDate(new Date()); }
function computeOrderTotals(quantity, pricePerUnit, deliveryFee, taxRatePercent, taxEnabled = true) {
  const materialCost = Number(quantity || 0) * Number(pricePerUnit || 0);
  const rate = Number(taxRatePercent || 0);
  const salesTaxAmount = taxEnabled === false ? 0 : money(materialCost * (rate / 100));
  const totalAmount = money(materialCost + salesTaxAmount + Number(deliveryFee || 0));
  return { salesTaxRate: rate, salesTaxAmount, totalAmount };
}
// A 'lump_sum' order (see the orders.pricing_mode column comment) bills one
// flat number no matter how many yards or loads the job actually takes —
// tax/delivery-fee are deliberately not layered on top, since the point of
// a lump sum is that this one number IS the whole bill.
function computeLumpSumTotals(lumpSumAmount) {
  return { salesTaxRate: 0, salesTaxAmount: 0, totalAmount: money(lumpSumAmount || 0) };
}
// Dispatches to the right total calculation for an order's pricing_mode.
// 'per_load' needs no special case here — it reuses quantity/price_per_unit
// (quantity = number of loads instead of yards), so plain computeOrderTotals
// already does the right multiplication; recomputeOrderRollup is what keeps
// that "quantity" in sync with real delivered loads.
function computeOrderTotalsForMode(pricingMode, { quantity, pricePerUnit, deliveryFee, taxRatePercent, taxEnabled, lumpSumAmount }) {
  if (pricingMode === 'lump_sum') return computeLumpSumTotals(lumpSumAmount);
  return computeOrderTotals(quantity, pricePerUnit, deliveryFee, taxRatePercent, taxEnabled);
}
function nextInvoiceNumber() {
  const prefix = `INV-${new Date().getFullYear()}`;
  const count = get('SELECT COUNT(*) as c FROM invoices WHERE invoice_number LIKE ?', [`${prefix}%`]).c;
  return `${prefix}-${String(count + 1).padStart(4, '0')}`;
}

// ---- DELIVERY SPLITTING & AUTO-SCHEDULING ---------------------------------
// A delivery is one truckload — max 20 yards. Orders over that get split
// into multiple deliveries. slot_index/SLOTS_PER_DAY are only used now to
// keep a driver's own day in a sensible order (see schedule.html's manual
// reorder arrows) — they are no longer a hard per-driver booking cap.
const MAX_YARDS_PER_DELIVERY = 20;
// A trailer-equipped rig (the Peterbilt, when it's pulling its trailer
// instead of running tri-axle) holds more per load — see the Load Type
// toggle on order-detail.html (PUT /api/orders/:id) and
// maxYardsForLoadType below. Only ever applies when an order is explicitly
// tagged load_type = 'trailer'; every other order keeps the standard
// MAX_YARDS_PER_DELIVERY cap, unchanged.
const TRAILER_MAX_YARDS_PER_DELIVERY = 30;
function maxYardsForLoadType(loadType) {
  return loadType === 'trailer' ? TRAILER_MAX_YARDS_PER_DELIVERY : MAX_YARDS_PER_DELIVERY;
}
const SLOTS_PER_DAY = 9;
const WORKDAY_START_HOUR = 8; // slot 0 = 8:00am, for display only
// The auto-scheduler fills each day's shared list up to this many
// deliveries — across every driver AND the unassigned pool combined —
// before rolling on to the next day on its own. This is a soft default, not
// a hard limit: a person can still deliberately put more than this on one
// day (schedule.html's Assign/Reassign, or picking a date by hand in New
// Order) when it makes sense — e.g. a run of stops that are all close
// together — see scheduledCountForDate/autoAssignDelivery below.
const DAILY_DELIVERY_SOFT_CAP = 16;

function splitIntoDeliveryChunks(quantity, maxPerDelivery = MAX_YARDS_PER_DELIVERY) {
  const qty = Number(quantity || 0);
  if (qty <= 0) return [];
  const count = Math.ceil(qty / maxPerDelivery);
  const chunks = [];
  let remaining = qty;
  for (let i = 0; i < count; i++) {
    const chunk = i === count - 1 ? money(remaining) : maxPerDelivery;
    chunks.push(chunk);
    remaining = money(remaining - maxPerDelivery);
  }
  return chunks;
}
function slotTimeLabel(slotIndex) {
  if (slotIndex === null || slotIndex === undefined) return null;
  const hour = WORKDAY_START_HOUR + Number(slotIndex);
  const period = hour >= 12 ? 'PM' : 'AM';
  const h12 = ((hour + 11) % 12) + 1;
  return `${h12}:00 ${period}`;
}
function addDays(dateStr, days) {
  const d = new Date(`${dateStr}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}
// Saturday/Sunday scheduling policy ("soft default", per the office's own
// choice): the SYSTEM picking a date on its own — the auto-scheduler below,
// the one-time weekend cleanup, and the daily rollover of unfinished loads —
// skips weekends: Sunday always, Saturday unless the order's own
// allow_saturday flag opts it in. A human explicitly choosing a date
// anywhere in the app (New Order's optional Delivery Date field, a per-row
// edit on order-detail.html, the schedule board's assign/reassign picker)
// is a deliberate choice and is never blocked by this — see `force` below.
function isBlockedWeekendDay(dateStr, allowSaturday) {
  const day = new Date(`${dateStr}T00:00:00Z`).getUTCDay();
  if (day === 0) return true;
  if (day === 6) return !allowSaturday;
  return false;
}
function nextEligibleWeekday(dateStr, allowSaturday) {
  let d = dateStr;
  while (isBlockedWeekendDay(d, allowSaturday)) d = addDays(d, 1);
  return d;
}
function usedSlots(driverId, dateStr) {
  return all(`SELECT slot_index FROM deliveries WHERE driver_id = ? AND scheduled_date = ? AND status != 'cancelled'`, [driverId, dateStr])
    .map((r) => r.slot_index).filter((s) => s !== null && s !== undefined);
}
// Total deliveries on the books for one day, regardless of driver (or lack
// of one) — the number the shared daily cap is measured against.
function scheduledCountForDate(dateStr) {
  return get(`SELECT COUNT(*) as c FROM deliveries WHERE scheduled_date = ? AND status != 'cancelled'`, [dateStr]).c;
}
// ---- Driver time off ---------------------------------------------------
// Drivers block off days they aren't working (Time Off page on their side);
// the office is told, and booking them anyway needs a confirmation.
function timeOffForDate(dateStr) {
  return all(`SELECT t.*, d.name AS driver_name FROM driver_time_off t JOIN drivers d ON d.id = t.driver_id
              WHERE t.start_date <= ? AND t.end_date >= ? ORDER BY d.name`, [dateStr, dateStr]);
}
function driverTimeOffOn(driverId, dateStr) {
  if (!driverId || !dateStr) return null;
  return get('SELECT * FROM driver_time_off WHERE driver_id = ? AND start_date <= ? AND end_date >= ? ORDER BY id DESC LIMIT 1', [driverId, dateStr, dateStr]) || null;
}
function fmtShortDate(d) {
  return new Date(`${d}T12:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
}
function timeOffRangeLabel(t) {
  return t.start_date === t.end_date ? fmtShortDate(t.start_date) : `${fmtShortDate(t.start_date)} – ${fmtShortDate(t.end_date)}`;
}
// pairs: [{ driverId, date }]. If any is off and the caller hasn't confirmed,
// answers 409 (the front end's api() helper asks the user and retries with
// confirm_time_off) and returns true.
function timeOffGuard(res, body, pairs) {
  if (body && (body.confirm_time_off === true || body.confirm_time_off === 1 || body.confirm_time_off === '1')) return false;
  const hits = [];
  for (const p of pairs) {
    const t = driverTimeOffOn(p.driverId, p.date);
    if (!t) continue;
    const d = get('SELECT name FROM drivers WHERE id = ?', [p.driverId]);
    hits.push({ driver_id: p.driverId, driver_name: d ? d.name : 'Driver', date: p.date, label: timeOffRangeLabel(t), reason: t.reason || '' });
  }
  if (!hits.length) return false;
  const text = hits.map((h) => `${h.driver_name} marked ${h.label} off${h.reason ? ` (${h.reason})` : ''}`).join('; ');
  sendJson(res, 409, { error: `${text}.`, time_off_conflict: true, conflicts: hits });
  return true;
}
function dailyCapWarning(dateStr) {
  const count = scheduledCountForDate(dateStr);
  const parts = [];
  if (count > DAILY_DELIVERY_SOFT_CAP) parts.push(`Heads up — ${dateStr} now has ${count} deliveries scheduled (the usual max is ${DAILY_DELIVERY_SOFT_CAP}).`);
  const off = timeOffForDate(dateStr);
  if (off.length) parts.push(`${off.map((t) => t.driver_name).join(', ')} ${off.length === 1 ? 'is' : 'are'} off that day.`);
  return parts.length ? parts.join(' ') : null;
}
// Schedules a delivery onto the shared board. Normally this does NOT pick a
// driver — the load just lands on the one shared list every driver can see
// and claim for themselves (see GET /api/driver/board and POST
// /api/deliveries/:id/claim), instead of being pre-assigned to whoever's
// turn it was in a rotation, and it silently rolls to the next day once
// DAILY_DELIVERY_SOFT_CAP is hit — that's just the default pacing, not
// something that needs anyone's permission.
//
// Two things make a placement deliberate instead of automatic, and either
// one is enough to skip the day-search and just warn instead of rolling
// over: a specific driver (preferredDriverId — New Order's optional "Assign
// Driver" field, or a repeat/add-on request tied to the driver who asked
// for it), or a specific date the office actually typed in (force — New
// Order's optional "Delivery Date" field). A person picking a day by hand
// already knows what they're doing — e.g. a run of stops that are all close
// together and can be squeezed onto an already-busy day.
function autoAssignDelivery(deliveryId, opts) {
  const { startDate, preferredDriverId, force, allowSaturday } = opts || {};
  if (preferredDriverId || force) {
    // `force` is a human-typed date (New Order's Delivery Date field) —
    // always honored exactly as entered, weekend or not. preferredDriverId
    // alone (no force) still lets the system land on the actual date, so it
    // respects the same weekend-skip as fully-automatic placement below.
    const date = force ? (startDate || todayStr()) : nextEligibleWeekday(startDate || todayStr(), allowSaturday);
    if (preferredDriverId) {
      const driver = get('SELECT * FROM drivers WHERE id = ? AND active = 1', [preferredDriverId]);
      if (!driver) return { scheduled: false, warning: null };
      run(`UPDATE deliveries SET driver_id = ?, scheduled_date = ?, slot_index = NULL, status = 'scheduled', updated_at = datetime('now') WHERE id = ?`,
        [driver.id, date, deliveryId]);
    } else {
      run(`UPDATE deliveries SET driver_id = NULL, scheduled_date = ?, slot_index = NULL, status = 'scheduled', updated_at = datetime('now') WHERE id = ?`,
        [date, deliveryId]);
    }
    return { scheduled: true, warning: dailyCapWarning(date) };
  }
  let date = startDate || todayStr();
  for (let i = 0; i < 120; i++) {
    if (!isBlockedWeekendDay(date, allowSaturday) && scheduledCountForDate(date) < DAILY_DELIVERY_SOFT_CAP) {
      run(`UPDATE deliveries SET driver_id = NULL, scheduled_date = ?, slot_index = NULL, status = 'scheduled', updated_at = datetime('now') WHERE id = ?`,
        [date, deliveryId]);
      return { scheduled: true, warning: null };
    }
    date = addDays(date, 1);
  }
  return { scheduled: false, warning: null };
}
// Splits an order's total dollar amount across its truckload chunks in
// proportion to each chunk's share of the total quantity, so a multi-load
// order's loads each show their own slice instead of the full order total.
// The last chunk absorbs the rounding remainder so the loads sum exactly to
// totalAmount.
function splitAmountByChunks(chunks, totalAmount) {
  const totalQty = chunks.reduce((s, q) => s + q, 0) || 1;
  let assigned = 0;
  return chunks.map((qty, idx) => {
    if (idx === chunks.length - 1) return money(totalAmount - assigned);
    const amt = money(totalAmount * (qty / totalQty));
    assigned += amt;
    return amt;
  });
}
// Reconciles an order's truckload(s) after the order itself is edited
// (quantity, price, or delivery fee changed) — including changing HOW MANY
// loads it should take, not just resizing the ones that already exist. A
// load that has already left the yard is untouchable: 'delivered', 'refused'
// (the truck still made the attempt), and 'out_for_delivery' (already
// loaded/en route) all keep their original quantity/amount no matter what
// the order changes to — there's real material already committed to them.
// Everything still "open" ('unscheduled' or 'scheduled' — hasn't gone out
// yet) is fair game: the remaining quantity (order total minus whatever's
// already locked in) gets re-chunked at the usual 20-yard max and handed
// back to those open loads in sequence order. If that's fewer loads than
// before (the office lowered the quantity), the excess open loads are
// deleted outright — they were never going to happen, so there's nothing to
// preserve by leaving them dangling on the schedule/board. If it's MORE
// loads than before (the office raised the quantity past what's already
// scheduled), new ones are created and auto-placed the same way a brand-new
// order's overflow loads are. A trucking (hourly) order is always exactly
// one delivery and its hours are only ever known after punch-out (see
// syncTruckingDeliveryToOrder) — this never touches those.
function syncDeliveriesToOrder(orderId, quantity, totalAmount, orderType, allowSaturday, loadType, pricingMode) {
  if (orderType === 'trucking') return;
  const deliveries = all('SELECT * FROM deliveries WHERE order_id = ? ORDER BY sequence', [orderId]);
  if (!deliveries.length) return;
  const lockedStatuses = ['delivered', 'refused', 'out_for_delivery'];
  const locked = deliveries.filter((d) => lockedStatuses.includes(d.status));
  const open = deliveries.filter((d) => !lockedStatuses.includes(d.status) && d.status !== 'cancelled');
  const lockedQty = locked.reduce((s, d) => s + Number(d.quantity || 0), 0);
  const lockedAmount = locked.reduce((s, d) => s + Number(d.amount || 0), 0);
  const remainingQty = Math.max(0, money(quantity - lockedQty));
  const remainingAmount = Math.max(0, money(totalAmount - lockedAmount));
  // A 'per_load' order's quantity IS the load count — one delivery per
  // load, never yard-chunked (see orders.pricing_mode / generateDeliveriesForOrder).
  const maxPerDelivery = pricingMode === 'per_load' ? 1 : maxYardsForLoadType(loadType);
  const chunks = splitIntoDeliveryChunks(remainingQty, maxPerDelivery);
  const amounts = splitAmountByChunks(chunks, remainingAmount);
  const keep = Math.min(open.length, chunks.length);
  for (let i = 0; i < keep; i++) {
    run(`UPDATE deliveries SET quantity = ?, amount = ?, updated_at = datetime('now') WHERE id = ?`, [chunks[i], amounts[i], open[i].id]);
  }
  if (open.length > chunks.length) {
    open.slice(chunks.length).forEach((d) => run('DELETE FROM deliveries WHERE id = ?', [d.id]));
  } else if (chunks.length > open.length) {
    let seq = deliveries[deliveries.length - 1].sequence;
    chunks.slice(open.length).forEach((qty, idx) => {
      seq += 1;
      const result = run(`INSERT INTO deliveries (order_id, sequence, quantity, amount, status) VALUES (?, ?, ?, ?, 'unscheduled')`,
        [orderId, seq, qty, amounts[open.length + idx]]);
      autoAssignDelivery(result.lastInsertRowid, { allowSaturday });
    });
  }
}
// The reverse direction, for a for-hire trucking order: the hours are only
// known AFTER the driver punches out (see PUT /api/deliveries/:id/deliver),
// so once its one delivery's quantity/amount are computed from the punch
// clock, this rolls them back up into the order's own quantity/
// sales_tax_amount/total_amount — the numbers invoicing actually reads.
function syncTruckingDeliveryToOrder(orderId) {
  const order = get('SELECT * FROM orders WHERE id = ?', [orderId]);
  if (!order) return;
  const delivery = get('SELECT * FROM deliveries WHERE order_id = ? ORDER BY sequence LIMIT 1', [orderId]);
  if (!delivery) return;
  const hours = Number(delivery.quantity || 0);
  const { salesTaxAmount, totalAmount } = computeOrderTotals(hours, order.price_per_unit, 0, order.sales_tax_rate, Boolean(order.sales_tax_enabled));
  run(`UPDATE orders SET quantity = ?, sales_tax_amount = ?, total_amount = ?, updated_at = datetime('now') WHERE id = ?`,
    [hours, salesTaxAmount, totalAmount, orderId]);
}

// Returns { warning } — the first daily-cap heads-up hit across this
// order's truckload(s), if any, so the caller can pass it back to whoever
// just created the order (see POST /api/orders, /api/driver/order-requests).
function generateDeliveriesForOrder(order, opts) {
  const { preferredDriverId, startDate, force, allowSaturday } = opts || {};
  // A 'per_load' order's quantity IS the load count, not yards — one
  // delivery per load, never yard-chunked (see orders.pricing_mode).
  const maxPerDelivery = order.pricing_mode === 'per_load' ? 1 : maxYardsForLoadType(order.load_type);
  const chunks = splitIntoDeliveryChunks(order.quantity, maxPerDelivery);
  const amounts = splitAmountByChunks(chunks, order.total_amount || 0);
  let warning = null;
  chunks.forEach((qty, idx) => {
    const result = run(`INSERT INTO deliveries (order_id, sequence, quantity, amount, status) VALUES (?, ?, ?, ?, 'unscheduled')`, [order.id, idx + 1, qty, amounts[idx]]);
    const outcome = autoAssignDelivery(result.lastInsertRowid, { startDate, preferredDriverId, force, allowSaturday });
    if (outcome && outcome.warning && !warning) warning = outcome.warning;
  });
  return { warning };
}
function recomputeOrderRollup(orderId) {
  const order = get('SELECT * FROM orders WHERE id = ?', [orderId]);
  // 'paid' is a terminal state too (an order marked paid directly, no
  // invoice — see POST /api/orders/:id/mark-paid-direct) — a delivery-level
  // change underneath it must never bounce the order status back to
  // 'delivered' and lose that.
  if (!order || order.status === 'invoiced' || order.status === 'paid') return;
  const deliveries = all('SELECT * FROM deliveries WHERE order_id = ? ORDER BY sequence', [orderId]);
  const notCancelled = deliveries.filter((d) => d.status !== 'cancelled');
  let status;
  let deliveredAt = order.delivered_at;
  if (!notCancelled.length) {
    status = deliveries.length ? 'cancelled' : 'new';
  } else if (notCancelled.every((d) => d.status === 'refused')) {
    status = 'refused';
  } else {
    const active = notCancelled.filter((d) => d.status !== 'refused');
    if (active.every((d) => d.status === 'delivered')) {
      status = 'delivered';
      const dates = active.map((d) => d.delivered_at).filter(Boolean).sort();
      if (dates.length) deliveredAt = dates[dates.length - 1];
    } else if (active.some((d) => d.scheduled_date)) {
      // A date alone is enough — this app's whole shared-board model
      // (see autoAssignDelivery) deliberately schedules a load onto a date
      // with NO driver yet, for any driver to claim later. Requiring
      // driver_id here too used to mean an order with only unassigned-but-
      // dated loads rolled up to 'new' instead of 'scheduled', and worse,
      // revertDeliveryToScheduled below used the same wrong test — so
      // undoing an out-for-delivery/delivered/refused load that had never
      // had a specific driver dropped it all the way to 'unscheduled' and
      // off the board, even though its date was sitting right there in the
      // column the whole time.
      status = 'scheduled';
    } else {
      status = 'new';
    }
  }
  const scheduledOnes = notCancelled.filter((d) => d.status !== 'refused' && d.scheduled_date)
    .sort((a, b) => (a.scheduled_date === b.scheduled_date ? a.sequence - b.sequence : (a.scheduled_date < b.scheduled_date ? -1 : 1)));
  const driverId = scheduledOnes.length ? scheduledOnes[0].driver_id : null;
  const scheduledDate = scheduledOnes.length ? scheduledOnes[0].scheduled_date : null;
  run(`UPDATE orders SET status = ?, driver_id = ?, scheduled_date = ?, delivered_at = ?, updated_at = datetime('now') WHERE id = ?`,
    [status, driverId, scheduledDate, deliveredAt, orderId]);
  // 'per_load' pricing (see orders.pricing_mode) bills price_per_unit times
  // however many loads actually happened — every time a load is added,
  // cancelled, etc. this runs again and keeps quantity (= load count) and
  // the bill in sync with the real, current set of non-cancelled loads, the
  // same way syncTruckingDeliveryToOrder rolls up punched hours.
  if (order.pricing_mode === 'per_load') {
    const loadCount = notCancelled.length;
    const { salesTaxAmount, totalAmount } = computeOrderTotals(loadCount, order.price_per_unit, order.delivery_fee, order.sales_tax_rate, Boolean(order.sales_tax_enabled));
    run(`UPDATE orders SET quantity = ?, sales_tax_amount = ?, total_amount = ? WHERE id = ?`, [loadCount, salesTaxAmount, totalAmount, orderId]);
  }
}
function revertDeliveryToScheduled(deliveryId) {
  const d = get('SELECT * FROM deliveries WHERE id = ?', [deliveryId]);
  if (!d) return;
  // A date is enough to count as scheduled, same reasoning as
  // recomputeOrderRollup above — a load can sit on the shared board with a
  // date and no driver yet. This used to also require driver_id, which
  // meant reverting an unassigned-but-dated load (the common case for a
  // multi-load order nobody's hand-assigned to one driver) wrongly dropped
  // it to 'unscheduled' and off the board, even with its date untouched in
  // the column right next to it.
  const newStatus = d.scheduled_date ? 'scheduled' : 'unscheduled';
  const order = get('SELECT order_type FROM orders WHERE id = ?', [d.order_id]);
  if (order && order.order_type === 'trucking') {
    // Reopening a trucking job clears its punch clock and computed
    // hours/amount too — punching in and out again produces the real bill
    // rather than leaving stale numbers from the previous attempt. Any
    // payment already collected against the old (now-zeroed) hours is
    // cleared too, so the driver isn't shown "Paid $X" for a job that no
    // longer has hours or an amount behind it.
    run(`UPDATE deliveries SET status = ?, delivered_at = NULL, punch_in_at = NULL, punch_out_at = NULL, quantity = 0, amount = 0, payment_collected = 0, payment_collected_method = NULL, payment_collected_amount = NULL, payment_collected_at = NULL, payment_collected_by = NULL, updated_at = datetime('now') WHERE id = ?`, [newStatus, deliveryId]);
    syncTruckingDeliveryToOrder(d.order_id);
  } else {
    run(`UPDATE deliveries SET status = ?, delivered_at = NULL, updated_at = datetime('now') WHERE id = ?`, [newStatus, deliveryId]);
  }
}
function appendDriverNote(orderId, note) {
  if (!note) return;
  const order = get('SELECT driver_notes FROM orders WHERE id = ?', [orderId]);
  const combined = order && order.driver_notes ? `${order.driver_notes}\n${note}` : note;
  run(`UPDATE orders SET driver_notes = ?, updated_at = datetime('now') WHERE id = ?`, [combined, orderId]);
}

// One-time seed of the company truck fleet into Assets, so drivers have real
// trucks to choose from at clock-in (GET /api/driver/trucks reads only from
// here — the mileage-log picker, separate from each driver's free-text
// truck_label used on PDF reports). Guarded by a settings flag so it only
// ever runs once — after that, office staff can rename, retire, or add
// trucks from the Assets screen without a later deploy re-adding what they
// removed, and skips any name that's already there (so re-running after a
// partial failure can't double up).
function seedFleetTrucks() {
  if (get(`SELECT value FROM settings WHERE key = 'fleet_trucks_seeded_v1'`)) return;
  const trucks = [
    ['Kenworth T880', 'Kenworth', 'T880'],
    ['Mack RD688', 'Mack', 'RD688'],
    ['Peterbilt 388', 'Peterbilt', '388'],
    ['International', 'International', null],
  ];
  trucks.forEach(([name, make, model]) => {
    const existing = get(`SELECT id FROM assets WHERE category = 'truck' AND name = ?`, [name]);
    if (!existing) run(`INSERT INTO assets (name, category, make, model, active) VALUES (?, 'truck', ?, ?, 1)`, [name, make, model]);
  });
  run(`INSERT INTO settings (key, value) VALUES ('fleet_trucks_seeded_v1', '1')`);
}

// One-time cleanup: push every currently open (still 'scheduled' or
// 'out_for_delivery') load that's sitting on a Saturday or Sunday forward
// onto the next day that isn't blocked — Sunday always, Saturday unless the
// order's own allow_saturday opts it in. Uses the exact same cap-aware
// day-search autoAssignDelivery already uses, so this doesn't just dump
// everything on Monday: if Monday's already at the daily soft cap, the
// overflow spills to Tuesday, and so on, the same way any other new load
// would. Guarded by a settings flag so it only ever runs once — after that,
// a human deliberately putting a specific load back on a weekend (allowed,
// see isBlockedWeekendDay's own comment) is never silently undone by a
// later deploy.
function migrateWeekendDeliveriesForward() {
  if (get(`SELECT value FROM settings WHERE key = 'weekend_deliveries_migrated_v1'`)) return;
  const rows = all(`
    SELECT d.id, d.order_id, d.scheduled_date, o.allow_saturday
    FROM deliveries d JOIN orders o ON o.id = d.order_id
    WHERE d.status IN ('scheduled', 'out_for_delivery') AND d.scheduled_date IS NOT NULL
  `);
  const touchedOrders = new Set();
  rows.forEach((d) => {
    const allowSaturday = Boolean(d.allow_saturday);
    if (!isBlockedWeekendDay(d.scheduled_date, allowSaturday)) return;
    let date = d.scheduled_date;
    for (let i = 0; i < 120; i++) {
      date = addDays(date, 1);
      if (!isBlockedWeekendDay(date, allowSaturday) && scheduledCountForDate(date) < DAILY_DELIVERY_SOFT_CAP) break;
    }
    run(`UPDATE deliveries SET scheduled_date = ?, updated_at = datetime('now') WHERE id = ?`, [date, d.id]);
    touchedOrders.add(d.order_id);
  });
  touchedOrders.forEach((oid) => recomputeOrderRollup(oid));
  run(`INSERT INTO settings (key, value) VALUES ('weekend_deliveries_migrated_v1', '1')`);
  if (rows.length) console.log(`One-time weekend cleanup: moved ${rows.length} load(s) off Saturday/Sunday.`);
}

// Any load still 'scheduled' or 'out_for_delivery' whose date has already
// passed gets pulled forward — "no matter what", so nobody has to come in
// and manually drag yesterday's unfinished loads forward every morning.
// The workday is treated as over at 6pm Eastern: before that cutoff, only
// genuinely past-due loads (yesterday or earlier) get swept onto today;
// from 6pm until midnight, today's own still-undelivered loads are treated
// the same way and swept onto tomorrow, since by 6pm "today" is effectively
// done. Landing day skips Saturday/Sunday the same as everywhere else
// (unless the order's own allow_saturday opts it in) — a load left over
// from Friday lands on Monday, not Saturday. Deliberately ignores the daily
// soft cap (unlike normal auto-placement): the whole point of this is that
// nothing gets stuck, so it always lands on the reference date regardless
// of how full that day already is — a person can still move it by hand
// afterward if they want it elsewhere. A load that was still
// 'out_for_delivery' resets to 'scheduled' first (same as tapping Undo on
// it), since a fresh landing day means starting that stop over. Checked at
// most twice per calendar day — once before the 6pm cutoff, once after (see
// rolloverPastDueDeliveriesIfNeeded) — so this never re-queries on every
// single request.
function rolloverCutoffPassed() {
  const hour = Number(new Intl.DateTimeFormat('en-US', { timeZone: BUSINESS_TZ, hour: 'numeric', hourCycle: 'h23' }).format(new Date()));
  return hour >= 18;
}
function rolloverPastDueDeliveries(referenceDate) {
  const rows = all(`
    SELECT d.id, d.order_id, d.status, o.allow_saturday
    FROM deliveries d JOIN orders o ON o.id = d.order_id
    WHERE d.status IN ('scheduled', 'out_for_delivery') AND d.scheduled_date IS NOT NULL AND d.scheduled_date < ?
  `, [referenceDate]);
  if (!rows.length) return;
  const touchedOrders = new Set();
  rows.forEach((d) => {
    if (d.status === 'out_for_delivery') revertDeliveryToScheduled(d.id);
    const landing = nextEligibleWeekday(referenceDate, Boolean(d.allow_saturday));
    run(`UPDATE deliveries SET scheduled_date = ?, status = 'scheduled', updated_at = datetime('now') WHERE id = ?`, [landing, d.id]);
    touchedOrders.add(d.order_id);
  });
  touchedOrders.forEach((oid) => recomputeOrderRollup(oid));
  console.log(`Daily rollover: moved ${rows.length} unfinished load(s) forward (landing on/after ${referenceDate}).`);
}
let lastRolloverCheckKey = null;
function rolloverPastDueDeliveriesIfNeeded() {
  const today = todayStr();
  const pastCutoff = rolloverCutoffPassed();
  // Before 6pm: sweep anything older than today onto today. From 6pm on:
  // treat today itself as done too, sweeping onto tomorrow instead.
  const referenceDate = pastCutoff ? addDays(today, 1) : today;
  const key = `${today}_${pastCutoff ? 'pm' : 'am'}`;
  if (lastRolloverCheckKey === key) return;
  lastRolloverCheckKey = key;
  try { rolloverPastDueDeliveries(referenceDate); } catch (e) { console.error('Daily rollover failed:', e); }
}

// ---- AUTH ----
on('POST', '/api/login', async (req, res) => {
  const body = await readJsonBody(req);
  if (body.role === 'office') {
    const username = (body.username || '').trim().toLowerCase();
    if (username) {
      const user = get('SELECT * FROM users WHERE username = ? AND active = 1', [username]);
      if (user && verifyPassword(body.password || '', user.password_hash, user.password_salt)) {
        createSession(res, { role: 'office', name: user.name, userId: user.id });
        recordAudit(req, { role: 'office', name: user.name, userId: user.id, action: 'login_success', method: 'POST', path: '/api/login', status: 200, detail: `Logged in as ${user.name}` });
        return sendJson(res, 200, { ok: true, role: 'office', name: user.name });
      }
      recordAudit(req, { role: 'office', name: username, action: 'login_failed', method: 'POST', path: '/api/login', status: 401, detail: `Failed office login for username "${username}"` });
      return sendJson(res, 401, { error: 'Incorrect username or password' });
    }
    if (body.password === OFFICE_PASSWORD) {
      createSession(res, { role: 'office', name: 'Dispatch' });
      recordAudit(req, { role: 'office', name: 'Dispatch', superAdmin: true, action: 'login_success', method: 'POST', path: '/api/login', status: 200, detail: 'Logged in as the main office account' });
      return sendJson(res, 200, { ok: true, role: 'office', name: 'Dispatch' });
    }
    recordAudit(req, { role: 'office', action: 'login_failed', method: 'POST', path: '/api/login', status: 401, detail: 'Failed main office login attempt (wrong password)' });
    return sendJson(res, 401, { error: 'Incorrect password' });
  }
  if (body.role === 'driver') {
    if (!body.driverId) return sendJson(res, 400, { error: 'Pick a driver.' });
    const driver = get('SELECT * FROM drivers WHERE id = ? AND active = 1', [body.driverId]);
    if (driver && driver.pin === String(body.pin || '')) {
      createSession(res, { role: 'driver', driverId: driver.id, name: driver.name });
      recordAudit(req, { role: 'driver', name: driver.name, driverId: driver.id, action: 'login_success', method: 'POST', path: '/api/login', status: 200, detail: `Driver logged in: ${driver.name}` });
      return sendJson(res, 200, { ok: true, role: 'driver', name: driver.name, driverId: driver.id });
    }
    recordAudit(req, { role: 'driver', name: driver ? driver.name : null, driverId: body.driverId, action: 'login_failed', method: 'POST', path: '/api/login', status: 401, detail: 'Failed driver login attempt (wrong PIN)' });
    return sendJson(res, 401, { error: 'Incorrect PIN' });
  }
  recordAudit(req, { action: 'login_failed', method: 'POST', path: '/api/login', status: 400, detail: `Unknown login role "${body.role}"` });
  return sendJson(res, 400, { error: 'Unknown role' });
});
on('POST', '/api/logout', async (req, res) => {
  const session = getSession(req);
  if (session) {
    recordAudit(req, {
      role: session.role, name: session.name, userId: session.userId, driverId: session.driverId,
      superAdmin: isSuperAdmin(session), action: 'logout', method: 'POST', path: '/api/logout', status: 200, detail: 'Logged out',
    });
  }
  destroySession(req, res);
  sendJson(res, 200, { ok: true });
});
on('GET', '/api/me', async (req, res) => {
  const session = getSession(req);
  if (!session) return sendJson(res, 200, { loggedIn: false });
  const access = getAccess(session);
  let canRequestOrders = false;
  if (session.role === 'driver' && session.driverId) {
    const driver = get('SELECT can_request_orders FROM drivers WHERE id = ?', [session.driverId]);
    canRequestOrders = !!(driver && driver.can_request_orders);
  }
  const isLead = isLeadDriver(session);
  sendJson(res, 200, { loggedIn: true, ...session, access, isSuperAdmin: isSuperAdmin(session), isLead, canRequestOrders, materialsTruckingMode: getSetting('materials_trucking_mode', '0') === '1' });
});
on('GET', '/api/audit-log', async (req, res, params, query) => {
  if (!requireSuperAdmin(req, res)) return;
  const limit = Math.min(Number(query.limit) || 100, 500);
  const offset = Math.max(Number(query.offset) || 0, 0);
  const conditions = [];
  const args = [];
  if (query.who === 'super_admin') { conditions.push("actor_role = 'office' AND is_super_admin = 1"); }
  else if (query.who === 'named_user') { conditions.push("actor_role = 'office' AND is_super_admin = 0"); }
  else if (query.who === 'driver') { conditions.push("actor_role = 'driver'"); }
  if (query.action) { conditions.push('action = ?'); args.push(query.action); }
  if (query.q) {
    const like = `%${query.q}%`;
    conditions.push('(actor_name LIKE ? OR path LIKE ? OR detail LIKE ?)');
    args.push(like, like, like);
  }
  const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  const rows = all(`SELECT * FROM audit_log ${where} ORDER BY id DESC LIMIT ? OFFSET ?`, [...args, limit, offset]);
  rows.forEach((r) => { r.created_at_display = formatEasternDateTime(r.created_at); });
  const total = get(`SELECT COUNT(*) as count FROM audit_log ${where}`, args).count;
  sendJson(res, 200, { rows, total });
});

// ---- FORGOT / RESET PASSWORD ----
const RESET_TOKEN_TTL_MS = 60 * 60 * 1000;
function hashResetToken(token) { return crypto.createHash('sha256').update(token).digest('hex'); }
on('POST', '/api/forgot-password', async (req, res) => {
  const b = await readJsonBody(req);
  const username = (b.username || '').trim().toLowerCase();
  const genericMsg = { ok: true, message: 'If that account exists and has an email on file, a reset link has been sent.' };
  if (!username) return sendJson(res, 200, genericMsg);
  const user = get('SELECT * FROM users WHERE username = ? AND active = 1', [username]);
  if (user && user.email && emailConfigured()) {
    const token = crypto.randomBytes(32).toString('hex');
    const expires = new Date(Date.now() + RESET_TOKEN_TTL_MS).toISOString();
    run('UPDATE users SET reset_token_hash = ?, reset_token_expires = ? WHERE id = ?', [hashResetToken(token), expires, user.id]);
    const baseUrl = `${req.headers['x-forwarded-proto'] || 'http'}://${req.headers.host}`;
    try {
      await sendMail({
        to: user.email,
        subject: 'Reset your OPD Development Corp password',
        text: `Hi ${user.name},\n\nSomeone requested a password reset for your account (${user.username}).\n\nReset your password here (link expires in 1 hour):\n${baseUrl}/reset-password.html?token=${token}\n\nIf you didn't request this, you can safely ignore this email — your password will stay the same.`,
      });
    } catch (err) {}
  }
  sendJson(res, 200, genericMsg);
});
on('POST', '/api/reset-password', async (req, res) => {
  const b = await readJsonBody(req);
  const token = (b.token || '').trim();
  const password = b.password || '';
  if (!token) return sendJson(res, 400, { error: 'Missing reset token.' });
  if (password.length < 6) return sendJson(res, 400, { error: 'Password must be at least 6 characters' });
  const tokenHash = hashResetToken(token);
  const user = get('SELECT * FROM users WHERE reset_token_hash = ? AND active = 1', [tokenHash]);
  if (!user || !user.reset_token_expires || new Date(user.reset_token_expires).getTime() < Date.now()) {
    return sendJson(res, 400, { error: 'This reset link is invalid or has expired. Request a new one.' });
  }
  const { hash, salt } = hashPassword(password);
  run('UPDATE users SET password_hash = ?, password_salt = ?, reset_token_hash = NULL, reset_token_expires = NULL WHERE id = ?',
    [hash, salt, user.id]);
  sendJson(res, 200, { ok: true });
});

// ---- DASHBOARD ----
on('GET', '/api/dashboard/summary', async (req, res) => {
  const session = requireOffice(req, res);
  if (!session) return;
  const access = getAccess(session);
  const counts = get(`SELECT SUM(CASE WHEN status='new' THEN 1 ELSE 0 END) as new_orders, SUM(CASE WHEN status='scheduled' THEN 1 ELSE 0 END) as scheduled_orders, SUM(CASE WHEN status='delivered' THEN 1 ELSE 0 END) as delivered_orders, SUM(CASE WHEN status='invoiced' THEN 1 ELSE 0 END) as invoiced_orders FROM orders`);
  const invoiceCounts = get(`SELECT SUM(CASE WHEN status IN ('sent','partial') THEN total - amount_paid ELSE 0 END) as outstanding, SUM(CASE WHEN status='paid' THEN total ELSE 0 END) as paid_total FROM invoices`);
  const todaysDeliveries = all(`${DELIVERY_SELECT} WHERE del.scheduled_date = ? AND del.status != 'cancelled' ORDER BY del.driver_id, del.slot_index IS NULL, del.slot_index`, [todayStr()])
    .map((r) => ({ ...r, slot_time: slotTimeLabel(r.slot_index) }));
  // Alongside genuinely unscheduled ('new') orders, also surface anything
  // still billed to the Materials-Out-slip review placeholder customer
  // (see getOrCreateReviewPlaceholderCustomer / POST /api/driver/material-slips)
  // regardless of status — those get auto-scheduled right away so they
  // don't sit at 'new', but the office still needs to open each one and
  // confirm a real customer and price before it's ever invoiced.
  const needsAttention = all(
    `${ORDER_SELECT} WHERE o.status = 'new' OR (o.status NOT IN ('invoiced', 'cancelled', 'paid') AND o.customer_id = (SELECT id FROM customers WHERE name = ?)) ORDER BY o.created_at ASC LIMIT 25`,
    [REVIEW_PLACEHOLDER_CUSTOMER_NAME]
  ).map((o) => {
    const created = parseUtcSqlDate(o.created_at);
    const hoursWaiting = created ? Math.max(0, Math.round((Date.now() - created.getTime()) / 3600000)) : null;
    return { id: o.id, order_number: o.order_number, customer_name: o.customer_name, material_name: o.material_name, quantity: o.quantity, unit: o.unit, job_number: o.job_number, created_at: o.created_at, hours_waiting: hoursWaiting };
  });
  const customerCount = get('SELECT COUNT(*) as c FROM customers').c;
  const driverRows = all('SELECT id, active FROM drivers');
  const activeDriverCount = driverRows.filter((d) => d.active).length;
  const deliveriesByDriverToday = all(`SELECT d.name as driver_name, COUNT(*) as count FROM deliveries del JOIN drivers d ON d.id = del.driver_id WHERE del.scheduled_date = ? AND del.status != 'cancelled' GROUP BY del.driver_id ORDER BY count DESC`, [todayStr()]);
  const recentDriverRequests = get(`SELECT COUNT(*) as c FROM orders WHERE requested_by_driver_id IS NOT NULL AND created_at >= datetime('now', '-7 days')`).c;
  const result = { counts, invoiceCounts, todaysDeliveries, needsAttention, customerCount, driverActivity: { activeDriverCount, deliveriesByDriverToday, recentDriverRequests } };
  if (access.full || access.can_view_assets) {
    const a = computeAssetsSummary();
    result.assetsSummary = { total_assets: a.total_assets, net_worth: a.net_worth };
  }
  if (access.full || access.can_view_realestate) {
    const p = computePropertiesSummary();
    result.propertiesSummary = { total_properties: p.total_properties, net_equity: p.net_equity, monthly_net: p.monthly_net };
  }
  if (access.full || access.can_view_financials) {
    const fin = computeFinancialSummary(1);
    const thisMonth = fin.monthlyRevenue[fin.monthlyRevenue.length - 1] || { total: 0 };
    result.financialSnapshot = { revenue_this_month: thisMonth.total, outstanding_invoices: fin.invoices.outstandingInvoices, overdue_invoices: fin.invoices.overdueCount };
  }
  sendJson(res, 200, result);
});

// ---- OFFICE TASKS POPUP ----
// Aggregates four "needs attention" categories into one call so a lightweight
// popup can greet office staff with what's waiting on them right after they
// log in, instead of them having to go check four separate pages. Read-only —
// this never changes anything, it just points at the pages that do (the
// dashboard's Needs Attention list, the Materials In/Disposal inbox, the Job
// Tracker's follow-ups, and Invoices). Overdue invoices are only included for
// accounts with financial access, matching the dashboard's own gating.
on('GET', '/api/office-tasks', async (req, res) => {
  const session = requireOffice(req, res);
  if (!session) return;
  const access = getAccess(session);
  const today = todayStr();

  // Same "needs attention" rule as the dashboard panel (see GET
  // /api/dashboard/summary): genuinely unscheduled orders, PLUS anything
  // still billed to the Materials-Out-slip review placeholder customer
  // regardless of status — those auto-schedule (and even auto-deliver)
  // themselves right away, so 'new' alone would miss them here.
  const newOrders = all(
    `${ORDER_SELECT} WHERE o.status = 'new' OR (o.status NOT IN ('invoiced', 'cancelled', 'paid') AND o.customer_id = (SELECT id FROM customers WHERE name = ?)) ORDER BY o.created_at ASC LIMIT 8`,
    [REVIEW_PLACEHOLDER_CUSTOMER_NAME]
  ).map((o) => ({
    id: o.id, order_number: o.order_number, customer_name: o.customer_name, material_name: o.material_name,
    quantity: o.quantity, unit: o.unit, job_number: o.job_number, created_at: o.created_at,
  }));
  const newOrdersCount = get(
    `SELECT COUNT(*) as c FROM orders WHERE status = 'new' OR (status NOT IN ('invoiced', 'cancelled', 'paid') AND customer_id = (SELECT id FROM customers WHERE name = ?))`,
    [REVIEW_PLACEHOLDER_CUSTOMER_NAME]
  ).c;

  const removalSlips = all(`${REMOVAL_SLIP_SELECT} WHERE r.status = 'needs_review' ORDER BY r.created_at ASC LIMIT 8`).map((r) => ({
    id: r.id, driver_name: r.driver_name, job_number: r.job_number, customer_name: r.job_customer_name,
    material: r.material, quantity: r.quantity, unit: r.unit, created_at: r.created_at,
  }));
  const removalSlipsCount = get(`SELECT COUNT(*) as c FROM removal_slips WHERE status = 'needs_review'`).c;

  const followups = all(`${JOB_SELECT} WHERE j.next_followup_date IS NOT NULL AND j.next_followup_date <= ? AND j.status NOT IN ('complete','cancelled') ORDER BY j.next_followup_date LIMIT 8`, [today]).map((j) => ({
    id: j.id, job_number: j.job_number, customer_name: j.customer_name, next_followup_date: j.next_followup_date, status: j.status,
  }));
  const followupsCount = get(`SELECT COUNT(*) as c FROM jobs WHERE next_followup_date IS NOT NULL AND next_followup_date <= ? AND status NOT IN ('complete','cancelled')`, [today]).c;

  const result = {
    newOrders, newOrdersCount,
    removalSlips, removalSlipsCount,
    followups, followupsCount,
    overdueInvoices: [], overdueInvoicesCount: 0,
    deliveredNotInvoiced: [], deliveredNotInvoicedCount: 0,
    outstandingInvoices: [], outstandingInvoicesCount: 0, outstandingTotal: 0,
    canViewInvoices: !!(access.full || access.can_view_financials),
    haulBilling: [], haulBillingTotal: 0, haulDayDue: [],
    zeroPriceOrders: [], zeroPriceCount: 0,
    pretripIssues: [], pretripIssueCount: 0, pretripOpenCount: 0, timeOffNew: [], timeOffNewCount: 0,
  };
  result.pretripIssues = all(`${PRETRIP_SELECT} WHERE p.has_issue = 1 AND p.resolved_at IS NULL AND p.acknowledged_at IS NULL ORDER BY p.created_at DESC LIMIT 8`).map((p) => ({
    id: p.id, driver_name: p.driver_name, truck_name: p.truck_name, date: p.date, issue_notes: p.issue_notes,
  }));
  result.pretripIssueCount = get('SELECT COUNT(*) as c FROM pretrip_inspections WHERE has_issue = 1 AND resolved_at IS NULL AND acknowledged_at IS NULL').c;
  result.pretripOpenCount = get('SELECT COUNT(*) as c FROM pretrip_inspections WHERE has_issue = 1 AND resolved_at IS NULL').c;
  result.timeOffNew = timeOffUnseen();
  result.timeOffNewCount = result.timeOffNew.length;
  result.zeroPriceOrders = all(`${ORDER_SELECT} WHERE ${NEEDS_PRICE_SQL} ORDER BY o.created_at ASC LIMIT 8`).map((o) => ({
    id: o.id, order_number: o.order_number, customer_name: o.customer_name, material_name: o.material_name,
    quantity: o.quantity, unit: o.unit, driver_name: o.requested_by_driver_name || o.driver_name, created_at: o.created_at,
  }));
  result.zeroPriceCount = get(`SELECT COUNT(*) as c FROM orders o WHERE ${NEEDS_PRICE_SQL}`).c;
  if (access.full || access.can_view_financials) {
    result.haulDayDue = haulDayCloseoutsDue();
    result.haulBilling = haulBillingSummary();
    result.haulBillingTotal = money(result.haulBilling.reduce((a, v) => a + (v.amount || 0), 0));
  }

  if (access.full || access.can_view_financials) {
    result.overdueInvoices = all(
      `SELECT i.id, i.invoice_number, i.total, i.amount_paid, i.due_date, c.name as customer_name
       FROM invoices i JOIN customers c ON c.id = i.customer_id
       WHERE i.status IN ('sent','partial') AND i.due_date IS NOT NULL AND i.due_date < ?
       ORDER BY i.due_date ASC LIMIT 8`, [today]
    );
    result.overdueInvoicesCount = get(`SELECT COUNT(*) as c FROM invoices WHERE status IN ('sent','partial') AND due_date IS NOT NULL AND due_date < ?`, [today]).c;

    // "Delivered — ready to invoice": same rule as GET /api/orders-ready-to-invoice
    // (status='delivered', excluding anything still billed to the Materials-Out-slip
    // review placeholder customer, which needs a real customer/price set first).
    const reviewCustomer = get('SELECT id FROM customers WHERE name = ?', [REVIEW_PLACEHOLDER_CUSTOMER_NAME]);
    const readyClauses = ["o.status = 'delivered'", `NOT ${NEEDS_PRICE_SQL}`], readyArgs = [];
    if (reviewCustomer) { readyClauses.push('o.customer_id != ?'); readyArgs.push(reviewCustomer.id); }
    result.deliveredNotInvoiced = all(
      `${ORDER_SELECT} WHERE ${readyClauses.join(' AND ')} ORDER BY o.delivered_at ASC LIMIT 8`, readyArgs
    ).map((o) => ({
      id: o.id, order_number: o.order_number, customer_name: o.customer_name, material_name: o.material_name,
      quantity: o.quantity, unit: o.unit, amount: (o.quantity || 0) * (o.price_per_unit || 0), delivered_at: o.delivered_at,
    }));
    result.deliveredNotInvoicedCount = get(
      `SELECT COUNT(*) as c FROM orders o WHERE ${readyClauses.join(' AND ')}`, readyArgs
    ).c;

    // "Outstanding money owed": every sent/partial invoice with a remaining
    // balance — broader than just overdue, since the office wants to see all
    // money owed, not only what's already past its due date.
    result.outstandingInvoices = all(
      `SELECT i.id, i.invoice_number, i.total, i.amount_paid, i.due_date, c.name as customer_name
       FROM invoices i JOIN customers c ON c.id = i.customer_id
       WHERE i.status IN ('sent','partial') AND (i.total - i.amount_paid) > 0
       ORDER BY i.due_date IS NULL, i.due_date ASC LIMIT 8`
    );
    const outstandingAgg = get(
      `SELECT COUNT(*) as c, SUM(total - amount_paid) as sum FROM invoices WHERE status IN ('sent','partial') AND (total - amount_paid) > 0`
    );
    result.outstandingInvoicesCount = outstandingAgg.c || 0;
    result.outstandingTotal = outstandingAgg.sum || 0;
  }

  result.totalCount = newOrdersCount + removalSlipsCount + followupsCount + result.overdueInvoicesCount + result.timeOffNewCount;
  sendJson(res, 200, result);
});

// ---- OFFICE TO-DO ----
// One list of everything the office still has to do, grouped the same way the
// dashboard "needs attention" panel and the login pop-ups are. It backs the
// To-Do page and the flashing red count on the To-Do tab in the top bar, so
// the count is simply "how many things are on the list" (each row = one kind of
// task, with `count` items inside it). Money rows are only included for
// accounts allowed to see financials.
on('GET', '/api/office-todo', async (req, res) => {
  const session = requireOffice(req, res);
  if (!session) return;
  const access = getAccess(session);
  const fin = !!(access.full || access.can_view_financials);
  const today = todayStr();
  const items = [];
  const add = (key, urgency, count, title, detail, href, samples) => {
    if (!count) return;
    items.push({ key, urgency, count, title, detail, href, samples: (samples || []).filter(Boolean).slice(0, 5) });
  };
  const qty = (o) => (o.quantity != null ? ` ${o.quantity}${o.unit ? ' ' + o.unit : ''}` : '');

  const pretrip = all(`${PRETRIP_SELECT} WHERE p.has_issue = 1 AND p.resolved_at IS NULL ORDER BY p.created_at DESC LIMIT 5`);
  add('pretrip', 'urgent', get('SELECT COUNT(*) as c FROM pretrip_inspections WHERE has_issue = 1 AND resolved_at IS NULL').c,
    'Pre-trip problems reported', 'A driver flagged an issue on their truck that is not resolved yet.', '/pretrip.html',
    pretrip.map((p) => `${p.driver_name} · ${p.truck_name || 'truck'}${p.issue_notes ? ' — ' + p.issue_notes : ''}`));

  const newOrdersWhere = `o.status = 'new' OR (o.status NOT IN ('invoiced', 'cancelled', 'paid') AND o.customer_id = (SELECT id FROM customers WHERE name = ?))`;
  const newOrders = all(`${ORDER_SELECT} WHERE ${newOrdersWhere} ORDER BY o.created_at ASC LIMIT 5`, [REVIEW_PLACEHOLDER_CUSTOMER_NAME]);
  add('orders-to-schedule', 'urgent', get(`SELECT COUNT(*) as c FROM orders o WHERE ${newOrdersWhere}`, [REVIEW_PLACEHOLDER_CUSTOMER_NAME]).c,
    'Orders waiting to be scheduled', 'New orders nobody has put on the schedule yet.', '/schedule.html',
    newOrders.map((o) => `${o.order_number} · ${o.customer_name || 'No customer'} · ${o.material_name || ''}${qty(o)}`));

  const unseen = all(`${HAUL_ASSIGNMENT_SELECT} WHERE a.date = ? AND a.ack_at IS NULL AND a.created_by NOT IN ('Driver', 'Office (moved)') ORDER BY a.start_time, v.name`, [today]);
  add('vendor-unseen', 'urgent', unseen.length, 'Vendor orders not seen yet today',
    'A driver has not opened their vendor order for today.', '/vendor-orders.html',
    unseen.map((a) => `${a.driver_name} · ${a.vendor_name}`));

  const timeOff = timeOffUnseen();
  add('time-off', 'urgent', timeOff.length, 'New driver time-off notices',
    'Look them over so nothing gets booked on those days.', '/schedule.html#time-off',
    timeOff.map((t) => `${t.driver_name} · ${fmtShortDate(t.start_date)}${t.end_date !== t.start_date ? ' – ' + fmtShortDate(t.end_date) : ''}${t.reason ? ' — ' + t.reason : ''}`));

  const needPrice = all(`${ORDER_SELECT} WHERE ${NEEDS_PRICE_SQL} ORDER BY o.created_at ASC LIMIT 5`);
  add('needs-price', 'normal', get(`SELECT COUNT(*) as c FROM orders o WHERE ${NEEDS_PRICE_SQL}`).c,
    'Orders needing a price', 'Driver-entered orders sitting at $0.', '/needs-price.html',
    needPrice.map((o) => `${o.order_number} · ${o.customer_name || 'No customer'} · ${o.material_name || ''}${qty(o)}`));

  const slips = all(`${REMOVAL_SLIP_SELECT} WHERE r.status = 'needs_review' ORDER BY r.created_at ASC LIMIT 5`);
  add('removal-slips', 'normal', get(`SELECT COUNT(*) as c FROM removal_slips WHERE status = 'needs_review'`).c,
    'Materials In / Disposal slips to review', 'Slips drivers filed that the office has not reviewed.', '/removal-slips.html',
    slips.map((r) => `${r.driver_name || 'Driver'} · ${r.job_customer_name || r.job_number || ''} · ${r.material || ''}`));

  const fups = all(`${JOB_SELECT} WHERE j.next_followup_date IS NOT NULL AND j.next_followup_date <= ? AND j.status NOT IN ('complete','cancelled') ORDER BY j.next_followup_date LIMIT 5`, [today]);
  add('followups', 'normal', get(`SELECT COUNT(*) as c FROM jobs WHERE next_followup_date IS NOT NULL AND next_followup_date <= ? AND status NOT IN ('complete','cancelled')`, [today]).c,
    'Project follow-ups due', 'Projects whose follow-up date is today or earlier.', '/jobs.html',
    fups.map((j) => `${j.job_number} · ${j.customer_name || ''} · due ${fmtShortDate(j.next_followup_date)}`));

  if (fin) {
    const due = haulDayCloseoutsDue();
    add('haul-closeout', 'urgent', due.length, 'Hauling to print & bill in Square',
      'Print each vendor\'s day report, bill it in Square, then mark it billed.', '/vendor-orders.html#reports',
      due.map((d) => `${d.vendor_name} · ${fmtShortDate(d.date)} · ${d.entries} load${d.entries === 1 ? '' : 's'}${d.amount != null ? ' · ' + fmtMoneyServer(d.amount) : ''}`));

    const od = all(`SELECT i.invoice_number, i.total, i.amount_paid, i.due_date, c.name as customer_name FROM invoices i JOIN customers c ON c.id = i.customer_id
      WHERE i.status IN ('sent','partial') AND i.due_date IS NOT NULL AND i.due_date < ? ORDER BY i.due_date ASC LIMIT 5`, [today]);
    add('overdue-invoices', 'urgent', get(`SELECT COUNT(*) as c FROM invoices WHERE status IN ('sent','partial') AND due_date IS NOT NULL AND due_date < ?`, [today]).c,
      'Overdue invoices', 'Past their due date and not paid in full.', '/invoices.html',
      od.map((i) => `${i.invoice_number} · ${i.customer_name} · ${fmtMoneyServer((i.total || 0) - (i.amount_paid || 0))} owed since ${fmtShortDate(i.due_date)}`));

    const reviewCustomer = get('SELECT id FROM customers WHERE name = ?', [REVIEW_PLACEHOLDER_CUSTOMER_NAME]);
    const rc = ["o.status = 'delivered'", `NOT ${NEEDS_PRICE_SQL}`], ra = [];
    if (reviewCustomer) { rc.push('o.customer_id != ?'); ra.push(reviewCustomer.id); }
    const dni = all(`${ORDER_SELECT} WHERE ${rc.join(' AND ')} ORDER BY o.delivered_at ASC LIMIT 5`, ra);
    add('delivered-not-invoiced', 'normal', get(`SELECT COUNT(*) as c FROM orders o WHERE ${rc.join(' AND ')}`, ra).c,
      'Delivered, not yet invoiced', 'Finished deliveries that still need an invoice.', '/invoices.html',
      dni.map((o) => `${o.order_number} · ${o.customer_name || ''} · ${o.material_name || ''}${qty(o)}`));

    const hb = haulBillingSummary();
    add('haul-billing', 'normal', hb.length, 'Hauling statements ready to bill',
      'Vendor hauling that has been completed and not billed yet.', '/hauling.html#billing',
      hb.map((v) => `${v.vendor_name} · ${v.entries} entr${v.entries === 1 ? 'y' : 'ies'}${v.amount != null ? ' · ' + fmtMoneyServer(v.amount) : ' · no rate set'}`));
  }

  const total = items.length;
  const itemCount = items.reduce((a, i) => a + i.count, 0);
  sendJson(res, 200, { items, total, itemCount, urgent: items.filter((i) => i.urgency === 'urgent').length, canViewMoney: fin });
});

// ---- GLOBAL SEARCH ----
// One box, four tables — customers, orders, invoices, and projects — each
// matched on the field an office user would actually type (name/phone,
// order number/address, invoice number, job number/customer). Capped at 6
// rows per category so the dropdown stays short; this is a jump-to-record
// tool, not a reporting query.
on('GET', '/api/search', async (req, res, params, query) => {
  if (!requireOffice(req, res)) return;
  const q = String((query && query.q) || '').trim();
  if (q.length < 2) return sendJson(res, 200, { results: [] });
  const like = `%${q}%`;
  const customers = all(`SELECT id, name, phone FROM customers WHERE name LIKE ? OR phone LIKE ? ORDER BY name LIMIT 6`, [like, like]);
  const orders = all(`SELECT o.id, o.order_number, c.name as customer_name FROM orders o LEFT JOIN customers c ON c.id = o.customer_id WHERE o.order_number LIKE ? OR o.delivery_address LIKE ? ORDER BY o.created_at DESC LIMIT 6`, [like, like]);
  const invoices = all(`SELECT i.id, i.invoice_number, c.name as customer_name FROM invoices i JOIN customers c ON c.id = i.customer_id WHERE i.invoice_number LIKE ? ORDER BY i.created_at DESC LIMIT 6`, [like]);
  const jobs = all(`SELECT id, job_number, customer_name FROM jobs WHERE job_number LIKE ? OR customer_name LIKE ? ORDER BY created_at DESC LIMIT 6`, [like, like]);
  const results = [
    ...customers.map((c) => ({ type: 'Customer', label: c.name, sub: c.phone || '', href: `/customer-detail.html?id=${c.id}` })),
    ...orders.map((o) => ({ type: 'Order', label: o.order_number, sub: o.customer_name || '', href: `/order-detail.html?id=${o.id}` })),
    ...invoices.map((i) => ({ type: 'Invoice', label: i.invoice_number, sub: i.customer_name || '', href: `/invoice-detail.html?id=${i.id}` })),
    ...jobs.map((j) => ({ type: 'Project', label: j.job_number, sub: j.customer_name || '', href: `/job-detail.html?id=${j.id}` })),
  ];
  sendJson(res, 200, { results });
});

