    hL += kv(mx, 'Pickup', [v.pickup_name, v.pickup_address].filter(Boolean).join(' - '), 290, r); y -= hL + 3;
    hL += 3; hL += kv(mx, 'Drop-off', v.dropoff_address, 290, r); y -= 14;
    hL += 14; hL += kv(mx, 'Material', v.material_name, 290, r); y -= 14;
    const billing = ton ? `Per ton${showPrices && d.hasRate ? ` - $${Number(d.rate).toFixed(2)}/ton` : ''}` : `Hourly${showPrices && d.hasRate ? ` - $${Number(d.rate).toFixed(2)}/hr` : ''}${Number(v.tolls_enabled) && v.toll_amount != null && showPrices ? ` + $${Number(v.toll_amount).toFixed(2)}/toll` : ''}`;
    kv(mx, 'Billing', billing, 290, r);
    const yLeftEnd = y;
    y = startY;
    const rxn = mx + 310;
    const rightLines = [['Date', dateLabel], ['Report #', r.reportNo], ['Drivers', `${d.drivers.length}`], ['Entries logged', `${d.calc.entries}`], ['Orders sent', `${d.orders.length}`]];
    rightLines.forEach(([k, val]) => { doc.text(rxn, y, k, { font: 'F2', size: 9 }); doc.text(rxn + 78, y, truncatePdfText(val, 'F1', 9.5, cw - 310 - 78), { size: 9.5 }); y -= 14; });
    y = Math.min(y, yLeftEnd) - 12;

    // ---- Dispatch
