        doc.text(mx + cols[0][1], y, truncatePdfText(o.driver_name, 'F1', 9.5, cols[0][2] - 6), { size: 9.5 });
        doc.text(mx + cols[1][1], y, truncatePdfText(drv.truck || '--', 'F1', 9.5, cols[1][2] - 6), { size: 9.5 });
        doc.text(mx + cols[2][1], y, vdrClock(o.start_time), { size: 9.5 });
        doc.text(mx + cols[3][1], y, o.ack_at ? formatEasternDateTime(o.ack_at).replace(/^[A-Za-z]{3} \d+, \d{4}, /, '') : 'Not opened', { size: 9 });
