      if (!dr.lines.length) { doc.text(mx + 6, y, ton ? 'No loads logged by this driver.' : 'No time entries logged by this driver.', { size: 9.5 }); y -= 18; return; }
      const tblHead = () => { cols.forEach(([lab, x]) => doc.text(mx + x, y, lab, { font: 'F2', size: 8.5 })); y -= 5; doc.hline(mx, y, cw, 0.5); y -= 11; };
      need(40, r); tblHead();
