// ---- DELIVERY DISTANCE ESTIMATOR ----
on('POST', '/api/estimate-distance', async (req, res) => {
  if (!requireOffice(req, res)) return;
  const b = await readJsonBody(req);
  if (!b.address) return sendJson(res, 400, { error: 'address is required' });
  const shopAddress = getSetting('shop_address');
  if (!shopAddress) return sendJson(res, 400, { error: 'Shop address is not set. Set it on the Admin page first.' });
  try {
    let shopLat = getSetting('shop_lat'), shopLng = getSetting('shop_lng');
    if (!shopLat || !shopLng) {
      const shopGeo = await geocodeAddress(shopAddress);
      shopLat = shopGeo.lat; shopLng = shopGeo.lng;
      setSetting('shop_lat', String(shopLat)); setSetting('shop_lng', String(shopLng));
    }
    const dest = await geocodeAddress(b.address);
    const { miles, method } = await drivingMiles({ lat: Number(shopLat), lng: Number(shopLng) }, dest);
    const bands = all('SELECT * FROM mileage_bands ORDER BY min_miles');
    const band = bands.find((bd) => miles >= bd.min_miles && (bd.max_miles === null || miles < bd.max_miles));
    sendJson(res, 200, {
      miles: Math.round(miles * 10) / 10,
      fee: band ? band.fee : null,
      band_label: band ? band.label : 'Outside defined mileage ranges — quote manually',
      method,
    });
  } catch (e) {
    sendJson(res, 502, { error: e.message || 'Could not estimate distance right now.' });
  }
});

// ---- ADDRESS AUTOCOMPLETE ----
// Real-world address suggestions as the office/a driver types — backed by
// Photon (komoot.io's free, keyless geocoder over OpenStreetMap data),
// which — unlike Nominatim above — is explicitly built for search-as-you-
// type use. Soft-biased toward the shop's own area (reusing the shop_lat/
// shop_lng cached by the estimator above, if already known) so "123 Main"
// surfaces nearby towns first without hard-restricting to them — an
// out-of-area customer's address still matches fine.
function formatPhotonFeature(f) {
  const p = (f && f.properties) || {};
  const streetPart = [p.housenumber, p.street].filter(Boolean).join(' ');
  const line1 = streetPart || p.name || '';
  if (!line1) return null;
  const cityPart = p.city || p.town || p.village || p.county || '';
  const tail = [cityPart, p.state].filter(Boolean).join(', ');
  const label = [line1, [tail, p.postcode].filter(Boolean).join(' ')].filter(Boolean).join(', ');
  const coords = f.geometry && Array.isArray(f.geometry.coordinates) ? f.geometry.coordinates : null;
  return { label, lat: coords ? coords[1] : null, lng: coords ? coords[0] : null };
}
on('GET', '/api/address-suggest', async (req, res, params, query) => {
  if (!requireAuth(req, res)) return;
  const q = (query.q || '').trim();
  if (q.length < 3) return sendJson(res, 200, []);
  try {
    const url = new URL('https://photon.komoot.io/api/');
    url.searchParams.set('q', q);
    url.searchParams.set('limit', '6');
    url.searchParams.set('lang', 'en');
    const shopLat = getSetting('shop_lat'), shopLng = getSetting('shop_lng');
    if (shopLat && shopLng) {
      url.searchParams.set('lat', shopLat);
      url.searchParams.set('lon', shopLng);
    }
    const r = await fetch(url.toString());
    if (!r.ok) return sendJson(res, 200, []);
    const data = await r.json();
    const suggestions = (data.features || []).map(formatPhotonFeature).filter(Boolean);
    // De-dupe identical labels (Photon can return the same address as both
    // a POI and a plain address point).
    const seen = new Set();
    const deduped = suggestions.filter((s) => (seen.has(s.label) ? false : (seen.add(s.label), true)));
    sendJson(res, 200, deduped);
  } catch (e) {
    // Suggestions are a nicety, not a requirement — a flaky/unreachable
    // geocoder should never block someone from just typing the address out
    // by hand, so this fails soft to an empty list instead of an error.
    sendJson(res, 200, []);
  }
});

