on('GET', '/api/templates/tracker.xlsx', async (req, res) => {
  if (!requireOffice(req, res)) return;
  sendXlsx(res, 'job-tracker-template.xlsx', buildXlsxTemplate(['Job Number', 'Job Address/Scope', 'Type of Job', 'Status', 'Billed', 'Paid', 'Notes']));
});

// Upsert-by-job-number import for the office's own Job Tracker spreadsheet —
// re-importing the same file (with updated statuses) just updates existing
// rows rather than duplicating them, unlike the older bulk /api/jobs/import
// (which always creates new Projects and has no concept of a stable job
// number to match on). customer_name is required by the jobs table but the
// tracker has no such column, so it falls back to the address/scope text —
// cosmetic-only in the regular Projects list for a tracker-only job.
on('POST', '/api/jobs/tracker-import', async (req, res) => {
  if (!requireOffice(req, res)) return;
  const b = await readJsonBody(req);
  if (!b.csv && !b.xlsx_base64) return sendJson(res, 400, { error: 'A CSV or Excel file is required' });
  let rows;
  try { rows = rowsFromImportBody(b); } catch (e) { return sendJson(res, 400, { error: e.message || 'Could not parse that file — check it’s a .csv or .xlsx export' }); }
  if (!rows.length) return sendJson(res, 400, { error: 'No rows found in that file' });
  const STATUS_ALIASES = {
    'planning stage': 'planning_stage', 'in progress': 'in_progress', 'overdue balance': 'overdue_balance',
    awarded: 'awarded', 'for bid': 'for_bid', 'job completed': 'job_completed', completed: 'job_completed',
    complete: 'job_completed', trash: 'trash',
  };
  const errors = []; let created = 0; let updated = 0;
  rows.forEach((row, idx) => {
    const lineNum = idx + 2;
    const jobNumber = (row.job_number || row.job || '').trim();
    if (!jobNumber) { errors.push({ row: lineNum, reason: 'Missing Job Number — row skipped' }); return; }
    const scope = row.job_address_scope || row.job_address || row.address_scope || row.scope || '';
    const jobTypeRaw = (row.type_of_job || row.type || '').trim();
    if (jobTypeRaw) ensureJobType(jobTypeRaw);
    const statusRaw = (row.status || '').trim().toLowerCase();
    const boardStatus = STATUS_ALIASES[statusRaw] || (BOARD_STATUSES.includes(statusRaw.replace(/\s+/g, '_')) ? statusRaw.replace(/\s+/g, '_') : null);
    if (statusRaw && !boardStatus) errors.push({ row: lineNum, reason: `Unrecognized status "${row.status}" — left as-is/Planning Stage` });
    const billed = /^(y|yes|true|1|x)$/i.test((row.billed || '').trim());
    const paid = /^(y|yes|true|1|x)$/i.test((row.paid || '').trim());
    const notes = row.notes || null;
    const existing = get('SELECT * FROM jobs WHERE job_number = ?', [jobNumber]);
    if (existing) {
      run(
        `UPDATE jobs SET scope = ?, job_type = ?, board_status = ?, billed = ?, paid = ?, notes = ?, updated_at = datetime('now') WHERE id = ?`,
        [scope || existing.scope, jobTypeRaw || existing.job_type, boardStatus || existing.board_status, billed ? 1 : 0, paid ? 1 : 0, notes !== null ? notes : existing.notes, existing.id]
      );
      updated += 1;
    } else {
      const resolvedBoardStatus = boardStatus || 'planning_stage';
      const status = BOARD_TO_JOB_STATUS[resolvedBoardStatus] || 'inquiry';
      run(
        `INSERT INTO jobs (job_number, customer_name, scope, job_type, board_status, billed, paid, notes, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [jobNumber, scope || jobNumber, scope || null, jobTypeRaw || null, resolvedBoardStatus, billed ? 1 : 0, paid ? 1 : 0, notes, status]
      );
      created += 1;
    }
  });
  sendJson(res, 200, { created, updated, errors });
});

on('GET', '/api/jobs/:id', async (req, res, params) => {
  if (!requireAuth(req, res)) return;
  const row = get(`${JOB_SELECT} WHERE j.id = ?`, [params.id]);
  if (!row) return sendJson(res, 404, { error: 'Job not found' });
  sendJson(res, 200, row);
});

on('POST', '/api/jobs', async (req, res) => {
  if (!requireOffice(req, res)) return;
  const b = await readJsonBody(req);
  let customerName = b.customer_name || null;
  let customerPhone = b.customer_phone || null;
  if (b.customer_id) {
    const cust = get('SELECT * FROM customers WHERE id = ?', [b.customer_id]);
    if (cust) { customerName = customerName || cust.name; customerPhone = customerPhone || cust.phone; }
  }
  if (!customerName) return sendJson(res, 400, { error: 'Customer name is required' });
  const status = b.status && JOB_STATUSES.includes(b.status) ? b.status : 'inquiry';
  const boardStatus = b.board_status && BOARD_STATUSES.includes(b.board_status) ? b.board_status : 'planning_stage';
  if (b.job_type) ensureJobType(b.job_type);
  const jobNumber = b.job_number || nextJobNumber();
  const result = run(
    `INSERT INTO jobs (job_number, customer_id, customer_name, customer_phone, site_address, scope, price, target_start_date, duration_days, crew_id, status, permit_number, next_followup_date, followup_note, notes, job_type, board_status, billed, paid) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [jobNumber, b.customer_id || null, customerName, customerPhone, b.site_address || null, b.scope || null,
     b.price !== undefined && b.price !== '' ? money(b.price) : null, b.target_start_date || null,
     b.duration_days !== undefined && b.duration_days !== '' ? Number(b.duration_days) : null,
     b.crew_id || null, status, b.permit_number || null, b.next_followup_date || null, b.followup_note || null, b.notes || null,
     b.job_type || null, boardStatus, b.billed ? 1 : 0, b.paid ? 1 : 0]
  );
  sendJson(res, 201, get(`${JOB_SELECT} WHERE j.id = ?`, [result.lastInsertRowid]));
});

on('PUT', '/api/jobs/:id', async (req, res, params) => {
  if (!requireOffice(req, res)) return;
  const b = await readJsonBody(req);
  const existing = get('SELECT * FROM jobs WHERE id = ?', [params.id]);
  if (!existing) return sendJson(res, 404, { error: 'Job not found' });
  if (b.status !== undefined && !JOB_STATUSES.includes(b.status)) return sendJson(res, 400, { error: 'Invalid status' });
  if (b.board_status !== undefined && !BOARD_STATUSES.includes(b.board_status)) return sendJson(res, 400, { error: 'Invalid board status' });
  if (b.job_type) ensureJobType(b.job_type);
  const fields = ['customer_id', 'customer_name', 'customer_phone', 'site_address', 'scope', 'price', 'target_start_date', 'duration_days', 'crew_id', 'status', 'permit_number', 'next_followup_date', 'followup_note', 'notes', 'job_type', 'board_status'];
  const next = { ...existing };
  fields.forEach((f) => { if (b[f] !== undefined) next[f] = b[f] === '' ? null : b[f]; });
  if (b.billed !== undefined) next.billed = b.billed ? 1 : 0;
  if (b.paid !== undefined) next.paid = b.paid ? 1 : 0;
  if (next.price !== null && next.price !== undefined) next.price = money(next.price);
  if (next.duration_days !== null && next.duration_days !== undefined) next.duration_days = Number(next.duration_days);
  run(
    `UPDATE jobs SET customer_id = ?, customer_name = ?, customer_phone = ?, site_address = ?, scope = ?, price = ?, target_start_date = ?, duration_days = ?, crew_id = ?, status = ?, permit_number = ?, next_followup_date = ?, followup_note = ?, notes = ?, job_type = ?, board_status = ?, billed = ?, paid = ?, updated_at = datetime('now') WHERE id = ?`,
    [next.customer_id, next.customer_name, next.customer_phone, next.site_address, next.scope, next.price, next.target_start_date, next.duration_days, next.crew_id, next.status, next.permit_number, next.next_followup_date, next.followup_note, next.notes, next.job_type, next.board_status, next.billed, next.paid, params.id]
  );
  sendJson(res, 200, get(`${JOB_SELECT} WHERE j.id = ?`, [params.id]));
});

on('DELETE', '/api/jobs/:id', async (req, res, params) => {
  if (!requireSuperAdmin(req, res)) return;
  const existing = get('SELECT * FROM jobs WHERE id = ?', [params.id]);
  if (!existing) return sendJson(res, 404, { error: 'Job not found' });
  run('DELETE FROM job_checklist_items WHERE job_id = ?', [params.id]);
  run('DELETE FROM job_todos WHERE job_id = ?', [params.id]);
  run('DELETE FROM job_permits WHERE job_id = ?', [params.id]);
  run('DELETE FROM job_equipment WHERE job_id = ?', [params.id]);
  run('DELETE FROM jobs WHERE id = ?', [params.id]);
  sendJson(res, 200, { ok: true });
});

