on('POST', '/api/jobs/import', async (req, res) => {
  if (!requireOffice(req, res)) return;
  const b = await readJsonBody(req);
  if (!b.csv && !b.xlsx_base64) return sendJson(res, 400, { error: 'A CSV or Excel file is required' });
  let rows;
  try { rows = rowsFromImportBody(b); } catch (e) { return sendJson(res, 400, { error: e.message || 'Could not parse that file — check it’s a .csv or .xlsx export' }); }
  if (!rows.length) return sendJson(res, 400, { error: 'No rows found in that file' });
  const errors = []; const crewsCreated = new Set(); let imported = 0;
  rows.forEach((row, idx) => {
    const lineNum = idx + 2;
    const customerName = row.customer_name || row.customer || row.client || row.client_name;
    if (!customerName) { errors.push({ row: lineNum, reason: 'Missing customer name — row skipped' }); return; }
    const scope = row.scope || row.scope_of_work || row.description || row.job_description || null;
    const price = parseMoneyLoose(row.price || row.job_price || row.amount || row.contract_price);
    const startRaw = row.target_start_date || row.start_date || row.date;
    const targetStart = parseFlexibleDate(startRaw);
    if (startRaw && !targetStart) errors.push({ row: lineNum, reason: `Couldn't read date "${startRaw}" (use YYYY-MM-DD or MM/DD/YYYY) — job imported without a start date` });
    const durationRaw = row.duration_days || row.duration || row.days;
    const durationDays = durationRaw ? (Number(String(durationRaw).replace(/[^0-9.]/g, '')) || null) : null;
    const crewName = row.crew || row.crew_name;
    let crewId = null;
    if (crewName) {
      const existingCrew = get('SELECT id FROM crews WHERE LOWER(name) = LOWER(?)', [crewName]);
      if (existingCrew) { crewId = existingCrew.id; } else { crewId = run('INSERT INTO crews (name) VALUES (?)', [crewName]).lastInsertRowid; crewsCreated.add(crewName); }
    }
    let status = (row.status || '').toLowerCase().trim().replace(/\s+/g, '_');
    if (!JOB_STATUSES.includes(status)) status = 'inquiry';
    const jobNumber = nextJobNumber();
    run(
      `INSERT INTO jobs (job_number, customer_name, customer_phone, site_address, scope, price, target_start_date, duration_days, crew_id, status, permit_number, notes) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [jobNumber, customerName, row.customer_phone || row.phone || null, row.site_address || row.address || null, scope, price, targetStart, durationDays, crewId, status, row.permit_number || row.permit || null, row.notes || null]
    );
    imported += 1;
  });
  sendJson(res, 200, { imported, crewsCreated: [...crewsCreated], errors });
});

on('POST', '/api/assets/import', async (req, res) => {
  if (!requireSection(req, res, 'can_view_assets')) return;
  const b = await readJsonBody(req);
  if (!b.csv && !b.xlsx_base64) return sendJson(res, 400, { error: 'A CSV or Excel file is required' });
  let rows;
  try { rows = rowsFromImportBody(b); } catch (e) { return sendJson(res, 400, { error: e.message || 'Could not parse that file — check it’s a .csv or .xlsx export' }); }
  if (!rows.length) return sendJson(res, 400, { error: 'No rows found in that file' });
  const ASSET_CATEGORIES = ['equipment', 'truck', 'vehicle', 'tool', 'other'];
  const ASSET_CONDITIONS = ['excellent', 'good', 'fair', 'poor'];
  const errors = [];
  let imported = 0;
  rows.forEach((row, idx) => {
    const lineNum = idx + 2;
    const name = row.name || row.asset_name || row.equipment_name || row.description;
    if (!name) { errors.push({ row: lineNum, reason: 'Missing name — row skipped' }); return; }
    const purchaseDateRaw = row.purchase_date || row.date_purchased || row.acquired_date || row.acquired;
    const purchaseDate = parseFlexibleDate(purchaseDateRaw);
    if (purchaseDateRaw && !purchaseDate) errors.push({ row: lineNum, reason: `Couldn't read date "${purchaseDateRaw}" (use YYYY-MM-DD or MM/DD/YYYY) — imported without a purchase date` });
    const yearRaw = row.year || row.model_year;
    const year = yearRaw ? (Number(String(yearRaw).replace(/[^0-9]/g, '')) || null) : null;
    const purchasePrice = parseMoneyLoose(row.purchase_price || row.cost || row.price);
    const estimatedValue = parseMoneyLoose(row.estimated_value || row.current_value || row.value);
    const debtBalance = parseMoneyLoose(row.debt_balance || row.loan_balance || row.balance_owed) || 0;
    let category = (row.category || '').toLowerCase().trim();
    if (!ASSET_CATEGORIES.includes(category)) category = 'equipment';
    let condition = (row.condition || '').toLowerCase().trim();
    if (!ASSET_CONDITIONS.includes(condition)) condition = 'good';
    run(
      `INSERT INTO assets (name, category, make, model, year, serial_vin, purchase_date, purchase_price, condition, location, notes, estimated_value, value_updated_at, debt_balance, debt_lender, debt_notes) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [name, category, row.make || null, row.model || null, year, row.serial_vin || row.vin || row.serial_number || row.serial || null, purchaseDate, purchasePrice, condition, row.location || null, row.notes || null, estimatedValue, estimatedValue !== null ? todayStr() : null, debtBalance, row.debt_lender || row.lender || null, row.debt_notes || null]
    );
    imported += 1;
  });
  sendJson(res, 200, { imported, errors });
});

on('POST', '/api/orders/import', async (req, res) => {
  if (!requireOffice(req, res)) return;
  const b = await readJsonBody(req);
  if (!b.csv && !b.xlsx_base64) return sendJson(res, 400, { error: 'A CSV or Excel file is required' });
  let rows;
  try { rows = rowsFromImportBody(b); } catch (e) { return sendJson(res, 400, { error: e.message || 'Could not parse that file — check it’s a .csv or .xlsx export' }); }
  if (!rows.length) return sendJson(res, 400, { error: 'No rows found in that file' });
  const errors = []; const customersCreated = new Set(); const materialsCreated = new Set(); let imported = 0;
  rows.forEach((row, idx) => {
    const lineNum = idx + 2;
    const customerName = row.customer_name || row.customer || row.client || row.client_name;
    const materialName = row.material_name || row.material;
    const dateRaw = row.order_date || row.date || row.delivery_date;
    const orderDate = parseFlexibleDate(dateRaw);
    const quantity = parseMoneyLoose(row.quantity || row.qty);
    if (!customerName) { errors.push({ row: lineNum, reason: 'Missing customer name — row skipped' }); return; }
    if (!materialName) { errors.push({ row: lineNum, reason: 'Missing material name — row skipped' }); return; }
    if (!orderDate) { errors.push({ row: lineNum, reason: `Missing or unreadable date "${dateRaw || ''}" (use YYYY-MM-DD or MM/DD/YYYY) — row skipped` }); return; }
    if (!quantity) { errors.push({ row: lineNum, reason: 'Missing or invalid quantity — row skipped' }); return; }
    let customer = get('SELECT * FROM customers WHERE LOWER(name) = LOWER(?)', [customerName]);
    if (!customer) {
      const cid = run('INSERT INTO customers (name, phone) VALUES (?, ?)', [customerName, row.customer_phone || row.phone || null]).lastInsertRowid;
      customer = get('SELECT * FROM customers WHERE id = ?', [cid]);
      customersCreated.add(customerName);
    }
    const priceGiven = parseMoneyLoose(row.price_per_unit || row.unit_price || row.price);
    let material = get('SELECT * FROM materials WHERE LOWER(name) = LOWER(?)', [materialName]);
    if (!material) {
      const mid = run('INSERT INTO materials (name, unit, default_price) VALUES (?, ?, ?)', [materialName, row.unit || 'yard', priceGiven || 0]).lastInsertRowid;
      material = get('SELECT * FROM materials WHERE id = ?', [mid]);
      materialsCreated.add(materialName);
    }
    const pricePerUnit = priceGiven !== null ? priceGiven : material.default_price;
    const deliveryFee = parseMoneyLoose(row.delivery_fee) || 0;
    const taxRate = parseMoneyLoose(row.sales_tax_rate) || 0;
    const totals = computeOrderTotals(quantity, pricePerUnit, deliveryFee, taxRate);
    const totalOverride = parseMoneyLoose(row.total_amount || row.total);
    let driverId = null;
    const driverName = row.driver_name || row.driver;
    if (driverName) { const driver = get('SELECT id FROM drivers WHERE LOWER(name) = LOWER(?)', [driverName]); if (driver) driverId = driver.id; }
    let status = (row.status || 'delivered').toLowerCase().trim().replace(/\s+/g, '_');
    if (!['new', 'scheduled', 'out_for_delivery', 'delivered', 'invoiced', 'cancelled'].includes(status)) status = 'delivered';
    const orderNumber = row.order_number || nextOrderNumberForDate(new Date(`${orderDate}T00:00:00`));
    const createdAt = `${orderDate} 12:00:00`;
    const result = run(
      `INSERT INTO orders (order_number, customer_id, material_id, quantity, unit, price_per_unit, delivery_address, delivery_fee, sales_tax_rate, sales_tax_amount, total_amount, notes, status, driver_id, scheduled_date, delivered_at, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [orderNumber, customer.id, material.id, quantity, row.unit || material.unit, pricePerUnit, row.delivery_address || row.address || '(historical import — no address on file)', deliveryFee, totals.salesTaxRate, totals.salesTaxAmount, totalOverride !== null ? totalOverride : totals.totalAmount, row.notes || null, status, driverId, status !== 'new' ? orderDate : null, (status === 'delivered' || status === 'invoiced') ? createdAt : null, createdAt, createdAt]
    );
    let delStatus = 'unscheduled';
    if (status === 'cancelled') delStatus = 'cancelled';
    else if (status === 'delivered' || status === 'invoiced') delStatus = 'delivered';
    else if (status === 'out_for_delivery' || status === 'scheduled') delStatus = status === 'out_for_delivery' ? 'out_for_delivery' : 'scheduled';
    run(
      `INSERT INTO deliveries (order_id, sequence, quantity, driver_id, scheduled_date, slot_index, status, delivered_at) VALUES (?, 1, ?, ?, ?, ?, ?, ?)`,
      [result.lastInsertRowid, quantity, driverId, delStatus !== 'unscheduled' ? orderDate : null, (delStatus === 'scheduled' || delStatus === 'out_for_delivery') ? 0 : null, delStatus, delStatus === 'delivered' ? createdAt : null]
    );
    imported += 1;
  });
  sendJson(res, 200, { imported, customersCreated: [...customersCreated], materialsCreated: [...materialsCreated], errors });
});

// ---- FINANCIAL REPORTING ----
const JOB_WON_STATUSES = ['accepted', 'scheduled', 'deposit_received', 'in_progress', 'complete'];
function lastNMonthKeys(n) {
  const out = []; const d = new Date(); d.setDate(1);
  for (let i = 0; i < n; i++) { out.unshift(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`); d.setMonth(d.getMonth() - 1); }
  return out;
}
function computeFinancialSummary(months) {
  const monthKeys = lastNMonthKeys(months);
  const materialsByMonth = all(`SELECT strftime('%Y-%m', created_at) as month, SUM(total_amount) as revenue FROM orders WHERE status != 'cancelled' GROUP BY month`);
  const jobsByMonth = all(`SELECT strftime('%Y-%m', COALESCE(target_start_date, created_at)) as month, SUM(price) as revenue FROM jobs WHERE status != 'cancelled' AND price IS NOT NULL GROUP BY month`);
  const materialsMap = {}; materialsByMonth.forEach((r) => { materialsMap[r.month] = r.revenue || 0; });
  const jobsMap = {}; jobsByMonth.forEach((r) => { jobsMap[r.month] = r.revenue || 0; });
  const monthlyRevenue = monthKeys.map((month) => {
    const materials = money(materialsMap[month] || 0); const jobs = money(jobsMap[month] || 0);
    return { month, materials, jobs, total: money(materials + jobs) };
  });
  const revenueByMaterial = all(`SELECT m.name as material_name, SUM(o.total_amount) as revenue FROM orders o JOIN materials m ON m.id = o.material_id WHERE o.status != 'cancelled' GROUP BY o.material_id ORDER BY revenue DESC`)
    .map((r) => ({ material_name: r.material_name, revenue: money(r.revenue || 0) })).filter((r) => r.revenue > 0);
  const custFromOrders = all(`SELECT c.id as customer_id, c.name as customer_name, SUM(o.total_amount) as revenue, COUNT(*) as order_count FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status != 'cancelled' GROUP BY o.customer_id`);
  const custFromJobs = all(`SELECT customer_id, customer_name, SUM(price) as revenue, COUNT(*) as job_count FROM jobs WHERE status != 'cancelled' AND price IS NOT NULL GROUP BY LOWER(customer_name)`);
  // Outstanding = sent/partial invoices not yet fully paid, per customer.
  const custOutstanding = all(`SELECT c.id as customer_id, c.name as customer_name, SUM(i.total - i.amount_paid) as outstanding FROM invoices i JOIN customers c ON c.id = i.customer_id WHERE i.status IN ('sent', 'partial') GROUP BY i.customer_id`);
  const custMap = {};
  custFromOrders.forEach((r) => { const key = (r.customer_name || '').toLowerCase(); custMap[key] = custMap[key] || { customer_id: r.customer_id, customer_name: r.customer_name, revenue: 0, order_count: 0, job_count: 0, outstanding: 0 }; custMap[key].customer_id = custMap[key].customer_id || r.customer_id; custMap[key].revenue += r.revenue || 0; custMap[key].order_count += r.order_count || 0; });
  custFromJobs.forEach((r) => { const key = (r.customer_name || '').toLowerCase(); custMap[key] = custMap[key] || { customer_id: r.customer_id, customer_name: r.customer_name, revenue: 0, order_count: 0, job_count: 0, outstanding: 0 }; custMap[key].customer_id = custMap[key].customer_id || r.customer_id; custMap[key].revenue += r.revenue || 0; custMap[key].job_count += r.job_count || 0; });
  custOutstanding.forEach((r) => { const key = (r.customer_name || '').toLowerCase(); custMap[key] = custMap[key] || { customer_id: r.customer_id, customer_name: r.customer_name, revenue: 0, order_count: 0, job_count: 0, outstanding: 0 }; custMap[key].customer_id = custMap[key].customer_id || r.customer_id; custMap[key].outstanding += r.outstanding || 0; });
  const topCustomers = Object.values(custMap).map((c) => ({ ...c, revenue: money(c.revenue), outstanding: money(c.outstanding || 0) })).filter((c) => c.revenue > 0 || c.outstanding > 0).sort((a, b) => b.revenue - a.revenue);
  const invoiceRows = all(`SELECT status, SUM(total) as total, SUM(amount_paid) as paid, COUNT(*) as c FROM invoices GROUP BY status`);
  let paidInvoicesTotal = 0; let outstandingInvoices = 0; let voidTotal = 0; let draftTotal = 0;
  invoiceRows.forEach((r) => {
    if (r.status === 'paid') paidInvoicesTotal += r.total || 0;
    else if (r.status === 'sent' || r.status === 'partial') outstandingInvoices += (r.total || 0) - (r.paid || 0);
    else if (r.status === 'void') voidTotal += r.total || 0;
    else if (r.status === 'draft') draftTotal += r.total || 0;
  });
  const overdueCount = get(`SELECT COUNT(*) as c FROM invoices WHERE status IN ('sent','partial') AND due_date IS NOT NULL AND due_date < ?`, [todayStr()]).c;
  const orderAgg = get(`SELECT SUM(total_amount) as total, COUNT(*) as c, AVG(total_amount) as avg FROM orders WHERE status != 'cancelled'`);
  const jobsWonAgg = get(`SELECT SUM(price) as total FROM jobs WHERE status IN (${JOB_WON_STATUSES.map(() => '?').join(',')}) AND price IS NOT NULL`, JOB_WON_STATUSES);
  const jobsPipelineAgg = get(`SELECT SUM(price) as total FROM jobs WHERE status NOT IN ('complete','cancelled') AND price IS NOT NULL`);
  const materialsRevenueAllTime = money(orderAgg.total || 0);
  const jobsRevenueWon = money(jobsWonAgg.total || 0);
  return {
    monthlyRevenue, revenueByMaterial, topCustomers,
    invoices: { paidInvoicesTotal: money(paidInvoicesTotal), outstandingInvoices: money(outstandingInvoices), voidTotal: money(voidTotal), draftTotal: money(draftTotal), overdueCount },
    stats: { materialsRevenueAllTime, jobsRevenueWon, jobsPipelineValue: money(jobsPipelineAgg.total || 0), combinedRevenue: money(materialsRevenueAllTime + jobsRevenueWon), orderCount: orderAgg.c || 0, avgOrderValue: money(orderAgg.avg || 0) },
    aging: computeInvoiceAging(),
  };
}
// Accounts-receivable aging: every unpaid/partial invoice bucketed by how
// many days past its due date (or its issue date, if it was never given a
// due date) it is today. "Current" means not yet due. Only invoices that
// still carry a balance are included — a fully paid or void invoice never
// shows up here even if it once had a due date in the past.
const AGING_BUCKETS = [
  { key: 'current', label: 'Current' },
  { key: 'due_1_30', label: '1-30 Days' },
  { key: 'due_31_60', label: '31-60 Days' },
  { key: 'due_61_90', label: '61-90 Days' },
  { key: 'due_90_plus', label: '90+ Days' },
];
function computeInvoiceAging() {
  const rows = all(`SELECT i.id, i.invoice_number, i.customer_id, c.name as customer_name, i.total, i.amount_paid, i.due_date, i.issued_date
                     FROM invoices i JOIN customers c ON c.id = i.customer_id
                     WHERE i.status IN ('sent', 'partial')`);
  const today = new Date(`${todayStr()}T00:00:00Z`).getTime();
  const totals = {};
  AGING_BUCKETS.forEach((b) => { totals[b.key] = { count: 0, amount: 0 }; });
  const invoicesOut = [];
  rows.forEach((r) => {
    const balance = money((r.total || 0) - (r.amount_paid || 0));
    if (balance <= 0) return;
    const refDateStr = r.due_date || r.issued_date;
    const refDate = refDateStr ? new Date(`${refDateStr}T00:00:00Z`).getTime() : today;
    const daysPastDue = Math.floor((today - refDate) / 86400000);
    let bucketKey;
    if (daysPastDue <= 0) bucketKey = 'current';
    else if (daysPastDue <= 30) bucketKey = 'due_1_30';
    else if (daysPastDue <= 60) bucketKey = 'due_31_60';
    else if (daysPastDue <= 90) bucketKey = 'due_61_90';
    else bucketKey = 'due_90_plus';
    totals[bucketKey].count += 1;
    totals[bucketKey].amount = money(totals[bucketKey].amount + balance);
    invoicesOut.push({
      id: r.id, invoice_number: r.invoice_number, customer_id: r.customer_id, customer_name: r.customer_name,
      due_date: r.due_date, balance, days_past_due: Math.max(0, daysPastDue), bucket: bucketKey,
    });
  });
  invoicesOut.sort((a, b) => b.days_past_due - a.days_past_due);
  const buckets = AGING_BUCKETS.map((b) => ({ key: b.key, label: b.label, count: totals[b.key].count, amount: money(totals[b.key].amount) }));
  const totalOutstanding = money(buckets.reduce((s, b) => s + b.amount, 0));
  return { buckets, invoices: invoicesOut, totalOutstanding };
}
// ---- QUICK LOOK ----
// A second, CRM-style dashboard: a handful of KPI cards with genuine
// month-over-month deltas, a revenue trend, top customers, recent orders and
// an activity feed. Everything here is either a FLOW metric (something that
// happened during a calendar month, so this-month-vs-last-month is an honest
// comparison) or a real, queried event -- MaterialFlow keeps no historical
// point-in-time snapshots, so nothing here fabricates a percentage against
// data that was never actually captured at a past moment.
function pctDelta(curr, prev) {
  if (prev === null || prev === undefined || !prev) return null;
  return money(((curr - prev) / prev) * 100);
}
function computeQuickLook() {
  const monthKeys = lastNMonthKeys(6);
  const thisMonth = monthKeys[monthKeys.length - 1];
  const lastMonth = monthKeys[monthKeys.length - 2];

  // Reuses the exact same per-month order revenue as the Financials page's
  // chart, so the trend line and the "New Order Value" KPI never disagree.
  const fin = computeFinancialSummary(6);
  const trend = fin.monthlyRevenue.map((r) => ({ month: r.month, value: r.materials }));
  const valThis = trend[trend.length - 1] ? trend[trend.length - 1].value : 0;
  const valLast = trend[trend.length - 2] ? trend[trend.length - 2].value : 0;

  // Orders placed per month (count), excluding cancelled.
  const ordersByMonth = all(`SELECT strftime('%Y-%m', created_at) as month, COUNT(*) as c FROM orders WHERE status != 'cancelled' GROUP BY month`);
  const ordersMap = {}; ordersByMonth.forEach((r) => { ordersMap[r.month] = r.c || 0; });
  const ordersThisCount = ordersMap[thisMonth] || 0;
  const ordersLastCount = ordersMap[lastMonth] || 0;

  // Orders whose delivered_at falls in a given month, valued at total_amount
  // -- a genuine "closed this month" figure, independent of current status.
  const deliveredByMonth = all(`SELECT strftime('%Y-%m', delivered_at) as month, SUM(total_amount) as total FROM orders WHERE delivered_at IS NOT NULL AND status != 'cancelled' GROUP BY month`);
  const deliveredMap = {}; deliveredByMonth.forEach((r) => { deliveredMap[r.month] = money(r.total || 0); });
  const deliveredThis = deliveredMap[thisMonth] || 0;
  const deliveredLast = deliveredMap[lastMonth] || 0;

  // Fulfillment rate: of the orders CREATED in a given month, what share
  // have reached delivered/invoiced as of right now? The current month's
  // number is necessarily a work-in-progress figure -- like any live
  // "this month" rate, it can only go up as the month plays out; it isn't a
  // claim about where the month will finish.
  const cohortByMonth = all(`SELECT strftime('%Y-%m', created_at) as month,
      SUM(CASE WHEN status IN ('delivered','invoiced') THEN 1 ELSE 0 END) as fulfilled, COUNT(*) as total
    FROM orders WHERE status != 'cancelled' GROUP BY month`);
  const cohortMap = {}; cohortByMonth.forEach((r) => { cohortMap[r.month] = { fulfilled: r.fulfilled || 0, total: r.total || 0 }; });
  const rateFor = (m) => { const c = cohortMap[m]; if (!c || !c.total) return null; return money((c.fulfilled / c.total) * 100); };
  const rateThis = rateFor(thisMonth);
  const rateLast = rateFor(lastMonth);

  const kpis = {
    newOrderValue: { value: money(valThis), deltaPct: pctDelta(valThis, valLast) },
    ordersThisMonth: { value: ordersThisCount, deltaPct: pctDelta(ordersThisCount, ordersLastCount) },
    deliveredThisMonth: { value: deliveredThis, deltaPct: pctDelta(deliveredThis, deliveredLast) },
    fulfillmentRate: { value: rateThis, deltaPoints: (rateThis !== null && rateLast !== null) ? money(rateThis - rateLast) : null },
  };

  // Top customers by all-time revenue -- the same figures as Financials,
  // just the top 5, for a "top deals"-style ranked list.
  const topCustomers = fin.topCustomers.slice(0, 5);

  // Recent orders, newest first.
  const recentOrders = all(`${ORDER_SELECT} ORDER BY o.created_at DESC LIMIT 6`).map((o) => ({
    id: o.id, order_number: o.order_number, customer_name: o.customer_name,
    material_name: o.material_name, total_amount: o.total_amount, status: o.status, created_at: o.created_at,
  }));

  // Activity feed: three real event streams -- order creations, completed
  // deliveries, invoice payments -- merged and sorted by time. Queried
  // directly rather than through the superadmin-only audit log, so any
  // office user with financial access can see it.
  const createdEvents = all(`SELECT o.id, o.order_number, c.name as customer_name, o.created_at as ts FROM orders o JOIN customers c ON c.id = o.customer_id ORDER BY o.created_at DESC LIMIT 8`)
    .map((r) => ({ type: 'order_created', ts: r.ts, order_id: r.id, order_number: r.order_number, customer_name: r.customer_name }));
  const deliveredEvents = all(`SELECT o.id, o.order_number, c.name as customer_name, o.delivered_at as ts FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.delivered_at IS NOT NULL ORDER BY o.delivered_at DESC LIMIT 8`)
    .map((r) => ({ type: 'order_delivered', ts: r.ts, order_id: r.id, order_number: r.order_number, customer_name: r.customer_name }));
  const paymentEvents = all(`SELECT p.id, p.amount, i.id as invoice_id, i.invoice_number, c.name as customer_name, p.paid_at as ts FROM payments p JOIN invoices i ON i.id = p.invoice_id JOIN customers c ON c.id = i.customer_id ORDER BY p.paid_at DESC LIMIT 8`)
    .map((r) => ({ type: 'invoice_paid', ts: r.ts, invoice_id: r.invoice_id, invoice_number: r.invoice_number, customer_name: r.customer_name, amount: money(r.amount || 0) }));
  const activity = [...createdEvents, ...deliveredEvents, ...paymentEvents]
    .filter((e) => e.ts)
    .sort((a, b) => new Date(`${b.ts.replace(' ', 'T')}Z`) - new Date(`${a.ts.replace(' ', 'T')}Z`))
    .slice(0, 8);

  return { trend, kpis, topCustomers, recentOrders, activity };
}
on('GET', '/api/dashboard/quicklook', async (req, res) => {
  if (!requireSection(req, res, 'can_view_financials')) return;
  sendJson(res, 200, computeQuickLook());
});

on('GET', '/api/financial/summary', async (req, res, params, query) => {
  if (!requireSection(req, res, 'can_view_financials')) return;
  const months = Math.min(24, Math.max(1, Number((query && query.months) || 12)));
  sendJson(res, 200, computeFinancialSummary(months));
});
on('GET', '/api/financial/report.pdf', async (req, res, params, query) => {
  if (!requireSection(req, res, 'can_view_financials')) return;
  const months = Math.min(24, Math.max(1, Number((query && query.months) || 12)));
  const summary = computeFinancialSummary(months);
  const monthKeys = lastNMonthKeys(months);
  const orders = all(`${ORDER_SELECT} WHERE strftime('%Y-%m', o.created_at) >= ? ORDER BY o.created_at`, [monthKeys[0]]);
  const periodLabel = months === 1 ? 'Last Month' : `Last ${months} Months`;
  const buf = buildFinancialReportPdf(summary, orders, { periodLabel });
  res.writeHead(200, { 'Content-Type': 'application/pdf', 'Content-Disposition': 'attachment; filename="Financial-Report.pdf"', 'Content-Length': buf.length });
  res.end(buf);
});
function csvField(v) {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}
function toCsv(rows, columns) {
  const header = columns.map((c) => c.label).join(',');
  const body = rows.map((r) => columns.map((c) => csvField(typeof c.value === 'function' ? c.value(r) : r[c.value])).join(',')).join('\n');
  return header + '\n' + body + '\n';
}
function sendCsv(res, filename, csv) {
  res.writeHead(200, { 'Content-Type': 'text/csv; charset=utf-8', 'Content-Disposition': `attachment; filename="${filename}"` });
  res.end(csv);
}

// ---- PUBLIC PAY-BY-LINK ----
on('GET', '/api/pay/:token', async (req, res, params) => {
  const invoice = get(`SELECT i.*, c.name as customer_name, c.billing_address as customer_address FROM invoices i JOIN customers c ON c.id = i.customer_id WHERE i.pay_token = ?`, [params.token]);
  if (!invoice) return sendJson(res, 404, { error: 'Invoice not found' });
  const items = all('SELECT * FROM invoice_items WHERE invoice_id = ?', [invoice.id]);
  sendJson(res, 200, { ...invoice, items, company_phone: getSetting('company_phone', '') });
});
on('POST', '/api/pay/:token/checkout', async (req, res, params) => {
  const invoice = get(`SELECT i.*, c.name as customer_name FROM invoices i JOIN customers c ON c.id = i.customer_id WHERE i.pay_token = ?`, [params.token]);
  if (!invoice) return sendJson(res, 404, { error: 'Invoice not found' });
  if (invoice.status === 'paid') return sendJson(res, 400, { error: 'Invoice already paid' });
  if (!stripeConfigured()) return sendJson(res, 400, { error: 'Online payment is not enabled yet. Please contact us to pay by another method.' });
  const baseUrl = `${req.headers['x-forwarded-proto'] || 'https'}://${req.headers.host}`;
  try {
    const session = await createCheckoutSession({ invoiceNumber: invoice.invoice_number, amountCents: Math.round((invoice.total - invoice.amount_paid) * 100), customerName: invoice.customer_name, description: `Invoice ${invoice.invoice_number}`, successUrl: `${baseUrl}/pay/${invoice.pay_token}?paid=1`, cancelUrl: `${baseUrl}/pay/${invoice.pay_token}`, invoiceId: invoice.id });
    run('UPDATE invoices SET stripe_checkout_url = ?, stripe_session_id = ? WHERE id = ?', [session.url, session.id, invoice.id]);
    sendJson(res, 200, { url: session.url });
  } catch (e) { sendJson(res, 500, { error: e.message }); }
});

// ---- PUBLIC CUSTOMER PORTAL ----
// A customer's own read-only view of their order history and invoices,
// reached via the token from getOrCreatePortalToken. No auth — the token
// itself is the credential, same trust model as the existing /pay/:token
// links — so only customer-safe fields are selected here (no driver info,
// no internal notes, no other customers' data).
on('GET', '/api/portal/:token', async (req, res, params) => {
  const customer = get('SELECT id, name, phone, email FROM customers WHERE portal_token = ?', [params.token]);
  if (!customer) return sendJson(res, 404, { error: 'Portal link not found' });
  const orders = all(
    `SELECT o.id, o.order_number, o.order_type, o.status, o.quantity, o.unit, o.total_amount, o.delivery_address,
            o.trucking_dropoff_address, o.created_at, o.requested_date, o.requested_window,
            m.name as material_name
     FROM orders o JOIN materials m ON m.id = o.material_id
     WHERE o.customer_id = ? AND o.status != 'cancelled'
     ORDER BY o.created_at DESC LIMIT 100`,
    [customer.id]
  );
  const invoices = all(
    `SELECT id, invoice_number, status, total, amount_paid, due_date, issued_date, paid_date, pay_token
     FROM invoices WHERE customer_id = ? AND status != 'void' ORDER BY issued_date DESC, id DESC LIMIT 100`,
    [customer.id]
  );
  sendJson(res, 200, { customer, orders, invoices });
});

// ---- STRIPE WEBHOOK ----
async function handleStripeWebhook(rawBody, signature) {
  if (!verifyWebhookSignature(rawBody, signature)) return { status: 400, body: { error: 'Invalid signature' } };
  const event = JSON.parse(rawBody);
  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    const invoiceId = session.metadata && session.metadata.invoice_id;
    if (invoiceId) {
      const invoice = get('SELECT * FROM invoices WHERE id = ?', [invoiceId]);
      if (invoice && invoice.status !== 'paid') {
        const amount = money((session.amount_total || 0) / 100);
        run('INSERT INTO payments (invoice_id, amount, method, reference) VALUES (?, ?, ?, ?)', [invoiceId, amount, 'stripe', session.id]);
        const newPaid = money(invoice.amount_paid + amount);
        const fullyPaid = newPaid >= invoice.total - 0.005;
        run(`UPDATE invoices SET amount_paid = ?, status = ?, paid_date = ? WHERE id = ?`, [newPaid, fullyPaid ? 'paid' : 'partial', fullyPaid ? todayStr() : invoice.paid_date, invoiceId]);
      }
    }
  }
  return { status: 200, body: { received: true } };
}

